    def _legal_attack_actions(self, state: GameState, player_id: int) -> list[Action]:
        if state.turn_number == 1 and player_id == state.first_player_id:
            return []
        if state.remaining_attack_declarations.get(player_id, 1) <= 0:
            return []
        player = state.players[player_id]
        opponent_id = self._opponent_of(player_id)
        opp = state.players[opponent_id]
        targets: list[tuple[str, int | None]] = [("leader", None)]
        targets.extend(("battle", i) for i, c in enumerate(opp.battle_area) if c.resting)
        targets.extend(("unison", i) for i, c in enumerate(opp.unison_area) if c.resting)
        actions: list[Action] = []
        opponent_resting_leader_lock = any(
            self._resting_card_prevents_opponent_battle_attacks_on_leaders(
                state,
                protected_player_id=opponent_id,
                card=card,
            )
            for card in opp.battle_area
        )
        if self._can_card_attack_this_turn(player.leader_area, state):
            actions.extend(
                Action(action_type=ActionType.DECLARE_ATTACK, player_id=player_id, attacker_zone="leader", target_player_id=opponent_id, target_zone=z, target_index=i)
                for z, i in targets
            )
        for zone_name, zone_cards in (("battle", player.battle_area), ("unison", player.unison_area)):
            for ai, attacker in enumerate(zone_cards):
                if not self._can_card_attack_this_turn(attacker, state):
                    continue
                if zone_name == "battle" and not self._can_pay_battle_attack_bottom_deck_tax(
                    state,
                    player_id=player_id,
                    attacker=attacker,
                ):
                    continue
                if zone_name == "battle" and not self._can_pay_battle_attack_discard_hand_tax(
                    state,
                    player_id=player_id,
                ):
                    continue
                if not self._can_pay_non_leader_attack_hand_z_tax(state, player_id=player_id):
                    continue
                if not self._can_pay_non_leader_attack_rest_tax(
                    state,
                    player_id=player_id,
                    excluded_instance_ids={attacker.instance_id},
                ):
                    continue
                attack_targets = list(targets)
                if bool(getattr(attacker, "temporary_can_attack_active_battles", False)):
                    for candidate in (
                        ("battle", i)
                        for i, c in enumerate(opp.battle_area)
                        if not c.resting
                    ):
                        if candidate not in attack_targets:
                            attack_targets.append(candidate)
                if bool(getattr(attacker, "temporary_can_attack_active_battles_without_barrier", False)):
                    for candidate in (
                        ("battle", i)
                        for i, c in enumerate(opp.battle_area)
                        if not c.resting and not self._card_currently_has_barrier(c)
                    ):
                        if candidate not in attack_targets:
                            attack_targets.append(candidate)
                if self._text_can_attack_active_battles_without_barrier(attacker):
                    for candidate in (
                        ("battle", i)
                        for i, c in enumerate(opp.battle_area)
                        if not c.resting and not self._card_currently_has_barrier(c)
                    ):
                        if candidate not in attack_targets:
                            attack_targets.append(candidate)
                for tz, ti in attack_targets:
                    if tz == "leader" and opponent_resting_leader_lock:
                        continue
                    actions.append(
                        Action(
                            action_type=ActionType.DECLARE_ATTACK,
                            player_id=player_id,
                            attacker_zone=zone_name,
                            attacker_index=ai,
                            target_player_id=opponent_id,
                            target_zone=tz,
                            target_index=ti,
                        )
                    )
        return actions

    def _legal_activate_battle_actions(self, state: GameState, player_id: int) -> list[Action]:
        player = state.players[player_id]
        actions: list[Action] = []
        for i, c in enumerate(player.hand):
            if c.card_type in {"EXTRA", "Z-EXTRA"} or not c.has_activate_battle:
                continue
            if (
                self._is_valid_skill_source_area(c, "hand")
                and self._can_pay_energy_cost(
                    player,
                    self._effective_hand_energy_cost(state, player_id=player_id, card=c),
                    required_color=c.color,
                    specified_costs=dict(c.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", c)
                and self._can_pay_skill_cost(state, player, c, "activate_battle", source_zone="hand")
                and self._activate_effect_requirements_met(state, player_id=player_id, source=c, source_zone="hand", source_kind="battle")
            ):
                actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="hand", source_index=i))
        for i, card in enumerate(player.hand):
            if card.card_type not in {"EXTRA", "Z-EXTRA"} or not card.has_activate_battle:
                continue
            effective_energy_cost = self._effective_hand_energy_cost(state, player_id=player_id, card=card)
            if not self._can_pay_costs(
                player,
                energy_cost=effective_energy_cost,
                required_color=card.color,
                specified_costs=dict(card.specified_costs),
                z_cost=card.z_energy_cost or 0,
            ):
                continue
            effect_rules = [
                rule
                for rule in self._effect_rules.get(card.card_id, ())
                if str(rule.trigger or "") == "self_activate_extra_from_hand"
            ]
            if effect_rules:
                available_other_hand = max(len(player.hand) - 1, 0)
                choice_added = False
                for choice_index, rule in enumerate(effect_rules):
                    discard_before = int(rule.handler_params.get("discard_from_hand_before", 0) or 0)
                    if discard_before > available_other_hand:
                        continue
                    actions.append(
                        Action(
                            action_type=ActionType.PLAY_CARD_FROM_HAND,
                            player_id=player_id,
                            hand_index=i,
                            effect_choice=choice_index,
                        )
                    )
                    choice_added = True
                if choice_added:
                    continue
            actions.append(Action(action_type=ActionType.PLAY_CARD_FROM_HAND, player_id=player_id, hand_index=i))
        if (
            player.leader_area.has_activate_battle
            and self._can_pay_energy_cost(
                player,
                0,
                required_color=player.leader_area.color,
                specified_costs=dict(player.leader_area.specified_costs),
            )
            and not self._is_activate_limited_this_turn(state, player_id, "battle", player.leader_area)
            and self._can_pay_skill_cost(state, player, player.leader_area, "activate_battle", source_zone="leader")
            and self._activate_effect_requirements_met(state, player_id=player_id, source=player.leader_area, source_zone="leader", source_kind="battle")
        ):
            for choice in self._public_activate_effect_choices(
                state,
                player_id=player_id,
                source=player.leader_area,
                source_zone="leader",
                source_kind="battle",
            ):
                actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="leader", effect_choice=choice))
        for i, c in enumerate(player.battle_area):
            if (
                self._is_valid_skill_source_area(c, "battle")
                and
                c.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    0,
                    required_color=c.color,
                    specified_costs=dict(c.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", c)
                and self._can_pay_skill_cost(state, player, c, "activate_battle", source_zone="battle")
                and self._activate_effect_requirements_met(state, player_id=player_id, source=c, source_zone="battle", source_kind="battle")
            ):
                for choice in self._public_activate_effect_choices(
                    state,
                    player_id=player_id,
                    source=c,
                    source_zone="battle",
                    source_kind="battle",
                ):
                    actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="battle", source_index=i, effect_choice=choice))
        for i, c in enumerate(player.unison_area):
            if (
                self._is_valid_skill_source_area(c, "unison")
                and
                c.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    0,
                    required_color=c.color,
                    specified_costs=dict(c.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", c)
                and not self._is_unison_marker_skill_limited_this_turn(state, c, "activate_battle")
                and self._can_pay_skill_cost(state, player, c, "activate_battle", source_zone="unison")
                and self._activate_effect_requirements_met(state, player_id=player_id, source=c, source_zone="unison", source_kind="battle")
            ):
                for choice in self._public_activate_effect_choices(
                    state,
                    player_id=player_id,
                    source=c,
                    source_zone="unison",
                    source_kind="battle",
                ):
                    actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="unison", source_index=i, effect_choice=choice))
        for i, c in enumerate(player.combo_area):
            if (
                self._is_valid_skill_source_area(c, "combo")
                and c.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    0,
                    required_color=c.color,
                    specified_costs=dict(c.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", c)
                and self._can_pay_skill_cost(state, player, c, "activate_battle", source_zone="combo")
                and self._activate_effect_requirements_met(state, player_id=player_id, source=c, source_zone="combo", source_kind="battle")
            ):
                actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="combo", source_index=i))
        for i, c in enumerate(player.drop):
            if (
                self._is_valid_skill_source_area(c, "drop")
                and c.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    0,
                    required_color=c.color,
                    specified_costs=dict(c.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", c)
                and self._can_pay_skill_cost(state, player, c, "activate_battle", source_zone="drop")
                and self._activate_effect_requirements_met(state, player_id=player_id, source=c, source_zone="drop", source_kind="battle")
            ):
                actions.append(Action(action_type=ActionType.ACTIVATE_BATTLE_SKILL, player_id=player_id, source_zone="drop", source_index=i))
        for i, card_id in enumerate(tuple(player.leader_area.stacked_card_ids or ())):
            source = self._create_card_instance(
                next_instance_id=-(player_id * 100000 + i + 1),
                card_id=int(card_id),
                owner_id=player_id,
            )
            if (
                self._is_valid_skill_source_area(source, "leader_under")
                and source.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    self._public_activate_energy_cost(
                        state,
                        player_id=player_id,
                        source=source,
                        source_zone="leader_under",
                        source_kind="battle",
                    ),
                    required_color=source.color,
                    specified_costs=dict(source.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", source)
                and self._can_pay_skill_cost(state, player, source, "activate_battle", source_zone="leader_under")
                and self._activate_effect_requirements_met(
                    state,
                    player_id=player_id,
                    source=source,
                    source_zone="leader_under",
                    source_kind="battle",
                )
            ):
                for choice in self._public_activate_effect_choices(
                    state,
                    player_id=player_id,
                    source=source,
                    source_zone="leader_under",
                    source_kind="battle",
                ):
                    if not self._can_pay_energy_cost(
                        player,
                        self._public_activate_energy_cost(
                            state,
                            player_id=player_id,
                            source=source,
                            source_zone="leader_under",
                            source_kind="battle",
                            effect_choice=choice,
                        ),
                        required_color=source.color,
                        specified_costs=dict(source.specified_costs),
                    ):
                        continue
                    actions.append(
                        Action(
                            action_type=ActionType.ACTIVATE_BATTLE_SKILL,
                            player_id=player_id,
                            source_zone="leader_under",
                            source_index=i,
                            effect_choice=choice,
                        )
                    )
        for flat_index, _host, _under_index, source in self._iter_battle_under_entries(player):
            if (
                self._is_valid_skill_source_area(source, "battle_under")
                and source.has_activate_battle
                and self._can_pay_energy_cost(
                    player,
                    self._public_activate_energy_cost(
                        state,
                        player_id=player_id,
                        source=source,
                        source_zone="battle_under",
                        source_kind="battle",
                    ),
                    required_color=source.color,
                    specified_costs=dict(source.specified_costs),
                )
                and not self._is_activate_limited_this_turn(state, player_id, "battle", source)
                and self._can_pay_skill_cost(state, player, source, "activate_battle", source_zone="battle_under")
                and self._activate_effect_requirements_met(
                    state,
                    player_id=player_id,
                    source=source,
                    source_zone="battle_under",
                    source_kind="battle",
                )
            ):
                for choice in self._public_activate_effect_choices(
                    state,
                    player_id=player_id,
                    source=source,
                    source_zone="battle_under",
                    source_kind="battle",
                ):
                    if not self._can_pay_energy_cost(
                        player,
                        self._public_activate_energy_cost(
                            state,
                            player_id=player_id,
                            source=source,
                            source_zone="battle_under",
                            source_kind="battle",
                            effect_choice=choice,
                        ),
                        required_color=source.color,
                        specified_costs=dict(source.specified_costs),
                    ):
                        continue
                    actions.append(
                        Action(
                            action_type=ActionType.ACTIVATE_BATTLE_SKILL,
                            player_id=player_id,
                            source_zone="battle_under",
                            source_index=flat_index,
                            effect_choice=choice,
                        )
                    )
        return actions

    def _legal_combo_actions(self, state: GameState, player_id: int) -> list[Action]:
        player = state.players[player_id]
        actions: list[Action] = []
        for i, c in enumerate(player.hand):
            if c.card_type not in {"BATTLE", "Z-BATTLE"}:
                continue
            if not self._can_combo_card(state, player_id, c):
                continue
            if (c.combo_cost or 0) < 0 or (c.combo_power or 0) < 0:
                continue
            if self._can_pay_energy_cost(player, c.combo_cost or 0):
                actions.append(Action(action_type=ActionType.COMBO_FROM_HAND, player_id=player_id, hand_index=i))
        for i, c in enumerate(player.battle_area):
            if c.card_type not in {"BATTLE", "Z-BATTLE"}:
                continue
            if not bool(getattr(c, "temporary_can_combo_from_battle_while_resting", False)):
                continue
            if not c.resting:
                continue
            if not self._can_combo_card(state, player_id, c):
                continue
            if (c.combo_cost or 0) < 0 or (c.combo_power or 0) < 0:
                continue
            if self._can_pay_energy_cost(player, c.combo_cost or 0):
                actions.append(Action(action_type=ActionType.COMBO_FROM_BATTLE, player_id=player_id, source_zone="battle", source_index=i))
        return actions

    def _legal_arrival_actions(self, state: GameState, player_id: int) -> list[Action]:
        ctx = state.attack_context
        if ctx is None or state.battle_step not in {BattleStep.OFFENSE, BattleStep.DEFENSE}:
            return []
        owner = ctx.attacker_player_id if state.battle_step == BattleStep.OFFENSE else ctx.target_player_id
        if player_id != owner:
            return []
        player = state.players[player_id]
        combo_colors = self._combo_area_color_tokens(player)
        actions: list[Action] = []
        for i, card in enumerate(player.hand):
            if card.card_type not in {"BATTLE", "Z-BATTLE"}:
                continue
            if self._is_card_play_restricted(state, player_id=player_id, card_id=card.card_id):
                continue
            arrival_spec, _used_reduction_ids = self._effective_arrival_spec(state, player_id=player_id, card=card)
            if arrival_spec is None:
                continue
            required_colors = set(arrival_spec.get("required_colors", set()))
            if required_colors and not required_colors.issubset(combo_colors):
                continue
            if not self._arrival_header_requirements_met(
                state,
                owner_player_id=player_id,
                raw_req=arrival_spec.get("requirement_text") or arrival_spec.get("requires_leader"),
            ):
                continue
            if not self._can_pay_costs(
                player,
                energy_cost=int(arrival_spec.get("total_cost", 0) or 0),
                required_color=None,
                specified_costs=dict(arrival_spec.get("specified_costs", {})),
                z_cost=0,
            ):
                continue
            actions.append(Action(action_type=ActionType.ARRIVAL, player_id=player_id, hand_index=i))
        return actions

    def _legal_counter_actions(self, state: GameState, player_id: int) -> list[Action]:
        if state.counter_window is None or player_id != state.counter_window.responder_player_id:
            return []
        player = state.players[player_id]
        actions = [Action(action_type=ActionType.PASS_COUNTER_WINDOW, player_id=player_id)]
        allowed_modes = self._allowed_counter_modes(state)
        for i, c in enumerate(player.hand):
            if not c.has_counter:
                continue
            if self._is_counter_hand_activation_restricted(state, player_id=player_id, card=c):
                continue
            if allowed_modes and not self._card_matches_counter_window(c, allowed_modes):
                continue
            if (
                "Counter: Counter" in allowed_modes
                and self._text_counter_counter_negates_only_attack(c)
                and (
                    not state.counter_chain
                    or "Counter: Attack" not in tuple(state.counter_chain[-1].modes or ())
                )
            ):
                continue
            effective_energy_cost = self._effective_hand_energy_cost(state, player_id=player_id, card=c)
            can_pay_energy = self._can_pay_energy_cost(
                player,
                effective_energy_cost,
                required_color=c.color,
                specified_costs=dict(c.specified_costs),
            )
            if not can_pay_energy and self._text_counter_can_activate_for_free_with_four_colors_among_energy_and_battle(c):
                color_names: set[str] = set()
                for zone_card in [*player.energy, *player.battle_area]:
                    for part in str(getattr(zone_card, "color", "") or "").replace("/", ",").split(","):
                        cleaned = part.strip().lower()
                        if cleaned:
                            color_names.add(cleaned)
                if len(color_names) >= 4:
                    can_pay_energy = True
            if (can_pay_energy or self._can_pay_alternate_counter_hand_cost(state, player, c)) and self._can_pay_skill_cost(state, player, c, "counter_from_hand"):
                actions.append(Action(action_type=ActionType.DECLARE_COUNTER_FROM_HAND, player_id=player_id, hand_index=i))
        for i, c in enumerate(player.energy):
            if not c.has_counter:
                continue
            if allowed_modes and not self._card_matches_counter_window(c, allowed_modes):
                continue
            if not self._can_activate_counter_from_energy(state, player_id=player_id, card=c):
                continue
            if not self._can_pay_energy_cost(
                player,
                int(c.energy_cost or 0),
                required_color=c.color,
                specified_costs=dict(c.specified_costs),
            ):
                continue
            actions.append(Action(action_type=ActionType.DECLARE_COUNTER_FROM_ENERGY, player_id=player_id, source_zone="energy", source_index=i))
        return actions

    def _legal_battle_step_actions(self, state: GameState, player_id: int) -> list[Action]:
        ctx = state.attack_context
        if ctx is None or state.battle_step is None:
            return []
        if state.battle_step == BattleStep.OFFENSE:
            if player_id != ctx.attacker_player_id:
                return []
            acts = [Action(action_type=ActionType.END_OFFENSE_STEP, player_id=player_id)]
            acts.extend(self._legal_combo_actions(state, player_id))
            acts.extend(self._legal_arrival_actions(state, player_id))
            acts.extend(self._legal_activate_battle_actions(state, player_id))
            return acts
        if state.battle_step == BattleStep.DEFENSE:
            if player_id != ctx.target_player_id:
                return []
            acts = [Action(action_type=ActionType.END_DEFENSE_STEP, player_id=player_id)]
            acts.extend(self._legal_blocker_actions(state, player_id))
            acts.extend(self._legal_combo_actions(state, player_id))
            acts.extend(self._legal_arrival_actions(state, player_id))
            acts.extend(self._legal_aegis_actions(state, player_id))
            acts.extend(self._legal_activate_battle_actions(state, player_id))
            return acts
        if state.battle_step in {BattleStep.DAMAGE, BattleStep.BATTLE_END}:
            if player_id != ctx.attacker_player_id:
                return []
            return [Action(action_type=ActionType.RESOLVE_BATTLE, player_id=player_id)]
        return []

    def _legal_blocker_actions(self, state: GameState, player_id: int) -> list[Action]:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.DEFENSE or player_id != ctx.target_player_id:
            return []
        player = state.players[player_id]
        actions: list[Action] = []
        for i, card in enumerate(player.battle_area):
            if card.resting or not self._card_has_keyword(card, "Blocker"):
                continue
            if ctx.target_zone == "battle" and ctx.target_instance_id == card.instance_id:
                continue
            actions.append(
                Action(
                    action_type=ActionType.ACTIVATE_BLOCKER,
                    player_id=player_id,
                    source_zone="battle",
                    source_index=i,
                )
            )
        return actions

    def _declare_attack(self, state: GameState, action: Action) -> None:
        if action.attacker_zone not in {"leader", "battle", "unison"}:
            raise RulesViolation("Invalid attacker zone.")
        if action.target_zone not in {"leader", "battle", "unison"} or action.target_player_id is None:
            raise RulesViolation("Invalid target.")
        self._clear_current_battle_protections(state)
        attacker = self._resolve_zone_card(state, player_id=action.player_id, zone=action.attacker_zone, index=action.attacker_index)
        target = self._resolve_zone_card(state, player_id=action.target_player_id, zone=action.target_zone, index=action.target_index)
        for tax in list(state.attack_power_taxes):
            if int(tax.affected_player_id) != int(action.player_id):
                continue
            self._apply_temporary_power_delta(
                state,
                card=attacker,
                delta=int(tax.power_delta),
                reason="attack_power_tax",
            )
            self._checkpoint(state, "attack_power_tax_applied")
        if action.attacker_zone == "battle":
            if not self._can_pay_battle_attack_bottom_deck_tax(state, player_id=action.player_id, attacker=attacker):
                raise RulesViolation(
                    "This Battle Card attack requires cards from hand to be placed at the bottom of the deck."
                )
            if not self._apply_battle_attack_bottom_deck_tax(state, player_id=action.player_id, attacker=attacker):
                raise RulesViolation(
                    "This Battle Card attack requires cards from hand to be placed at the bottom of the deck."
                )
            if not self._can_pay_battle_attack_discard_hand_tax(state, player_id=action.player_id):
                raise RulesViolation(
                    "This Battle Card attack requires cards from hand to be discarded."
                )
            if not self._apply_battle_attack_discard_hand_tax(state, player_id=action.player_id):
                raise RulesViolation(
                    "This Battle Card attack requires cards from hand to be discarded."
                )
        if action.attacker_zone != "leader":
            if not self._can_pay_non_leader_attack_hand_z_tax(state, player_id=action.player_id):
                raise RulesViolation(
                    "A non-Leader attack requires a card from hand and Z-energy to be placed in Drop."
                )
            if not self._apply_non_leader_attack_hand_z_tax(state, player_id=action.player_id):
                raise RulesViolation(
                    "A non-Leader attack requires a card from hand and Z-energy to be placed in Drop."
                )
            if not self._apply_non_leader_attack_rest_tax(
                state,
                player_id=action.player_id,
                excluded_instance_ids={attacker.instance_id},
            ):
                raise RulesViolation("A non-Leader attack requires an additional active card to switch to Rest Mode.")
        if action.player_id in state.remaining_attack_declarations:
            remaining = int(state.remaining_attack_declarations.get(action.player_id, 0))
            if remaining <= 0:
                raise RulesViolation("This player cannot declare more attacks this turn.")
            state.remaining_attack_declarations[action.player_id] = remaining - 1
        attacks_used = self._attacks_used_this_turn(attacker)
        attacker.resting = True
        attacker.attacked_this_turn = True
        attacker.attack_count_this_turn = attacks_used + 1
        state.attack_context = AttackContext(
            attacker_player_id=action.player_id,
            attacker_zone=action.attacker_zone,
            attacker_instance_id=attacker.instance_id,
            target_player_id=action.target_player_id,
            target_zone=action.target_zone,
            target_instance_id=target.instance_id,
        )
        state.battle_step = None
        self._open_counter_window(
            state,
            kind="attack",
            responder_player_id=action.target_player_id,
            pending_action=PendingAction(action_type="attack", actor_player_id=action.player_id, payload={}),
        )
        self._emit_effect_event(
            state,
            name="attack_declared",
            actor_player_id=action.player_id,
            payload={
                "attacker_instance_id": attacker.instance_id,
                "attacker_zone": action.attacker_zone,
                "target_player_id": action.target_player_id,
                "target_zone": action.target_zone,
            },
        )
        self._checkpoint(state, "counter_timing_attack")

    def _declare_play_card_from_hand(self, state: GameState, action: Action) -> None:
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        if self._is_card_play_restricted(state, player_id=action.player_id, card_id=card.card_id):
            raise RulesViolation("This card can't be played right now.")
        effective_energy_cost = self._effective_hand_energy_cost(state, player_id=action.player_id, card=card)
        used_activate_extra_cost_reduction = (
            card.card_type in {"EXTRA", "Z-EXTRA"}
            and self._matching_activate_extra_cost_reduction_amount(state, player_id=action.player_id, source=card) > 0
        )
        paid_energy_cards, _ = self._pay_costs(
            player,
            energy_cost=effective_energy_cost,
            required_color=card.color,
            specified_costs=dict(card.specified_costs),
            z_cost=card.z_energy_cost or 0,
        )
        if used_activate_extra_cost_reduction:
            self._consume_matching_activate_extra_cost_reductions(state, player_id=action.player_id, source=card)
        if card.card_type in {"EXTRA", "Z-EXTRA"}:
            declared = player.hand.pop(action.hand_index)
            player.drop.append(declared)
            self._emit_card_placed_into_drop(state, owner_player_id=action.player_id, card=declared, source_zone="hand")
            selected_effect_id: int | None = None
            extra_effects = sorted(
                [
                    reg
                    for reg in state.effect_registry
                    if reg.source_instance_id == declared.instance_id
                    and reg.source_zone == "drop"
                    and reg.trigger == "self_activate_extra_from_hand"
                ],
                key=lambda row: int(row.effect_id),
            )
            if action.effect_choice is not None and 0 <= int(action.effect_choice) < len(extra_effects):
                selected_effect_id = int(extra_effects[int(action.effect_choice)].effect_id)
            elif len(extra_effects) == 1:
                selected_effect_id = int(extra_effects[0].effect_id)
            self._open_counter_window(
                state,
                kind="activate_extra_from_hand",
                responder_player_id=self._opponent_of(action.player_id),
                pending_action=PendingAction(
                    action_type="activate_extra_from_hand",
                    actor_player_id=action.player_id,
                    payload={
                        "card_instance_id": declared.instance_id,
                        "source_instance_id": declared.instance_id,
                        "source_card_id": declared.card_id,
                        "source_zone": "drop",
                        "selected_effect_id": selected_effect_id,
                    },
                ),
            )
            self._checkpoint(state, "extra_moved_to_drop_on_declare")
            self._checkpoint(state, "counter_timing_activate_extra")
            return

        self._open_counter_window(
            state,
            kind="play",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=PendingAction(
                action_type="play_from_hand",
                actor_player_id=action.player_id,
                payload={"card_instance_id": card.instance_id, "paid_energy_cards": paid_energy_cards},
            ),
        )
        self._checkpoint(state, "counter_timing_play")

    def _declare_dark_over_realm(self, state: GameState, action: Action) -> None:
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        spec = self._parse_dark_over_realm_spec(card)
        if spec is None:
            raise RulesViolation("Card does not have Dark Over Realm.")
        if self._is_card_play_restricted(state, player_id=action.player_id, card_id=card.card_id):
            raise RulesViolation("This card can't be played right now.")
        drop_to_warp = int(spec.get("drop_to_warp", 0) or 0)
        if len(player.drop) < drop_to_warp:
            raise RulesViolation("Not enough cards in Drop for Dark Over Realm.")
        paid_energy_cards = self._pay_energy_cost(
            player,
            int(spec.get("total_cost", 0) or 0),
            required_color=None,
            specified_costs=dict(spec.get("specified_costs", {})),
        )
        for _ in range(drop_to_warp):
            moved = player.drop.pop(0)
            self._append_to_owner_warp(state, owner_player_id=action.player_id, card=moved, source_zone="drop")
        self._open_counter_window(
            state,
            kind="play",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=PendingAction(
                action_type="play_from_hand",
                actor_player_id=action.player_id,
                payload={
                    "card_instance_id": card.instance_id,
                    "paid_energy_cards": paid_energy_cards,
                    "played_via": "dark_over_realm",
                },
            ),
        )
        self._checkpoint(state, "dark_over_realm_declared")
        self._checkpoint(state, "counter_timing_play")

    def _declare_over_realm(self, state: GameState, action: Action) -> None:
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        spec = self._parse_over_realm_spec(card)
        if spec is None:
            raise RulesViolation("Card does not have Over Realm.")
        if self._is_card_play_restricted(state, player_id=action.player_id, card_id=card.card_id):
            raise RulesViolation("This card can't be played right now.")
        drop_to_warp = int(spec.get("drop_to_warp", 0) or 0)
        if len(player.drop) < drop_to_warp:
            raise RulesViolation("Not enough cards in Drop for Over Realm.")
        paid_energy_cards = self._pay_energy_cost(
            player,
            int(spec.get("total_cost", 0) or 0),
            required_color=None,
            specified_costs=dict(spec.get("specified_costs", {})),
        )
        for _ in range(drop_to_warp):
            moved = player.drop.pop(0)
            self._append_to_owner_warp(state, owner_player_id=action.player_id, card=moved, source_zone="drop")
        self._open_counter_window(
            state,
            kind="play",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=PendingAction(
                action_type="play_from_hand",
                actor_player_id=action.player_id,
                payload={
                    "card_instance_id": card.instance_id,
                    "paid_energy_cards": paid_energy_cards,
                    "played_via": "over_realm",
                },
            ),
        )
        self._checkpoint(state, "over_realm_declared")
        self._checkpoint(state, "counter_timing_play")

    def _declare_arrival(self, state: GameState, action: Action) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step not in {BattleStep.OFFENSE, BattleStep.DEFENSE}:
            raise RulesViolation("Arrival is not legal right now.")
        owner = ctx.attacker_player_id if state.battle_step == BattleStep.OFFENSE else ctx.target_player_id
        if action.player_id != owner:
            raise RulesViolation("Wrong player for Arrival.")
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        spec, used_reduction_ids = self._effective_arrival_spec(state, player_id=action.player_id, card=card)
        if spec is None:
            raise RulesViolation("Card does not have Arrival.")
        required_colors = set(spec.get("required_colors", set()))
        combo_colors = self._combo_area_color_tokens(player)
        if required_colors and not required_colors.issubset(combo_colors):
            raise RulesViolation("Arrival color condition is not met.")
        if not self._arrival_header_requirements_met(
            state,
            owner_player_id=action.player_id,
            raw_req=spec.get("requirement_text") or spec.get("requires_leader"),
        ):
            raise RulesViolation("Arrival header condition is not met.")
        if self._is_card_play_restricted(state, player_id=action.player_id, card_id=card.card_id):
            raise RulesViolation("This card can't be played right now.")
        paid_energy_cards = self._pay_energy_cost(
            player,
            int(spec.get("total_cost", 0) or 0),
            required_color=None,
            specified_costs=dict(spec.get("specified_costs", {})),
        )
        header_draw_amount = int(spec.get("header_draw_amount", 0) or 0)
        for _ in range(header_draw_amount):
            self._draw_one_from_card_skill(state, player_id=action.player_id, card=card, source_zone="hand")
        self._consume_activate_arrival_cost_reductions(state, used_ids=used_reduction_ids)
        self._open_counter_window(
            state,
            kind="play",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=PendingAction(
                action_type="play_from_hand",
                actor_player_id=action.player_id,
                payload={
                    "card_instance_id": card.instance_id,
                    "paid_energy_cards": paid_energy_cards,
                    "played_via": "arrival",
                },
            ),
        )
        self._checkpoint(state, "arrival_declared")
        self._checkpoint(state, "counter_timing_play")

    def _legal_aegis_actions(self, state: GameState, player_id: int) -> list[Action]:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.DEFENSE:
            return []
        if player_id != ctx.target_player_id:
            return []
        player = state.players[player_id]
        actions: list[Action] = []
        for i, card in enumerate(player.battle_area):
            if self._card_skills_are_negated(card):
                continue
            spec = self._parse_aegis_spec(card)
            if spec is None:
                continue
            if bool(spec.get("once_per_turn")) and self._activate_usage_key(player_id, "aegis", card) in state.activate_skill_usage:
                continue
            required_colors = set(spec.get("required_colors", set()))
            if self._matching_hand_indices_for_color_requirements(player.hand, required_colors) is None:
                continue
            actions.append(
                Action(
                    action_type=ActionType.AEGIS,
                    player_id=player_id,
                    source_zone="battle",
                    source_index=i,
                )
            )
        return actions

    def _declare_aegis(self, state: GameState, action: Action) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.DEFENSE:
            raise RulesViolation("Aegis is only legal during the Defense Step.")
        if action.player_id != ctx.target_player_id:
            raise RulesViolation("Wrong player for Aegis.")
        if action.source_zone != "battle" or action.source_index is None:
            raise RulesViolation("Aegis requires a Battle Card source.")
        player = state.players[action.player_id]
        if not (0 <= action.source_index < len(player.battle_area)):
            raise RulesViolation("Invalid Aegis source.")
        source = player.battle_area[action.source_index]
        if self._card_skills_are_negated(source):
            raise RulesViolation("This card's skills are negated.")
        spec = self._parse_aegis_spec(source)
        if spec is None:
            raise RulesViolation("Card does not have Aegis.")
        if bool(spec.get("once_per_turn")) and self._activate_usage_key(action.player_id, "aegis", source) in state.activate_skill_usage:
            raise RulesViolation("This Aegis skill was already used this turn.")
        required_colors = set(spec.get("required_colors", set()))
        hand_indices = self._matching_hand_indices_for_color_requirements(player.hand, required_colors)
        if hand_indices is None:
            raise RulesViolation("Not enough matching colors in hand for Aegis.")
        for idx in sorted(hand_indices, reverse=True):
            discarded = player.hand.pop(idx)
            player.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=action.player_id, card=discarded, source_zone="hand")
        activated = 0
        max_energy_to_activate = int(spec.get("max_energy_to_activate", 0) or 0)
        for energy in player.energy:
            if not energy.resting:
                continue
            energy.resting = False
            activated += 1
            if activated >= max_energy_to_activate:
                break
        if bool(spec.get("once_per_turn")):
            state.activate_skill_usage.add(self._activate_usage_key(action.player_id, "aegis", source))
        self._emit_effect_event(
            state,
            name="aegis_activated",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": source.instance_id,
                "source_zone": "battle",
                "required_colors": "/".join(sorted(required_colors)),
            },
        )
        self._checkpoint(state, "aegis_activated")

    def _declare_activate_skill(self, state: GameState, action: Action, *, source_kind: str) -> None:
        player = state.players[action.player_id]
        if action.source_zone not in {"leader", "battle", "unison", "hand", "energy", "warp", "combo", "drop", "z_energy", "leader_under", "battle_under"}:
            raise RulesViolation("Invalid source zone.")
        if action.source_zone == "leader":
            source = player.leader_area
        elif action.source_zone == "leader_under":
            if action.source_index is None:
                raise RulesViolation("Missing source index.")
            leader_under = tuple(player.leader_area.stacked_card_ids or ())
            if not (0 <= action.source_index < len(leader_under)):
                raise RulesViolation("Source index out of range.")
            source = self._create_card_instance(
                next_instance_id=-(action.player_id * 100000 + action.source_index + 1),
                card_id=int(leader_under[action.source_index]),
                owner_id=action.player_id,
            )
        elif action.source_zone == "battle_under":
            if action.source_index is None:
                raise RulesViolation("Missing source index.")
            entry = self._find_battle_under_entry(player, source_index=action.source_index)
            if entry is None:
                raise RulesViolation("Source index out of range.")
            _flat_index, _host, _under_index, source = entry
        else:
            if action.source_index is None:
                raise RulesViolation("Missing source index.")
            zone = (
                player.battle_area
                if action.source_zone == "battle"
                else player.unison_area
                if action.source_zone == "unison"
                else player.hand
                if action.source_zone == "hand"
                else player.energy
                if action.source_zone == "energy"
                else player.combo_area
                if action.source_zone == "combo"
                else player.drop
                if action.source_zone == "drop"
                else player.z_energy
                if action.source_zone == "z_energy"
                else player.warp
            )
            if not (0 <= action.source_index < len(zone)):
                raise RulesViolation("Source index out of range.")
            source = zone[action.source_index]
        if source_kind == "main" and not source.has_activate_main:
            raise RulesViolation("No Activate: Main.")
        if source_kind == "battle" and not source.has_activate_battle:
            raise RulesViolation("No Activate: Battle.")
        if not self._is_valid_skill_source_area(source, action.source_zone):
            raise RulesViolation("Skill source is in an invalid area for its card type.")
        if action.source_zone in {"hand", "energy", "warp", "combo", "drop", "z_energy"}:
            self._register_card_effects(state, player_id=action.player_id, source_zone=action.source_zone, card=source)
        if self._is_activate_limited_this_turn(state, action.player_id, source_kind, source):
            raise RulesViolation("Activate skill limit already used this turn.")
        if self._is_unison_marker_skill_limited_this_turn(state, source, f"activate_{source_kind}", source_zone=action.source_zone):
            raise RulesViolation("This Unison already used a marker-cost skill this turn.")
        if not self._activate_effect_requirements_met(
            state,
            player_id=action.player_id,
            source=source,
            source_zone=action.source_zone,
            source_kind=source_kind,
        ):
            raise RulesViolation("Activate skill requirements are not met.")
        if not self._can_pay_skill_cost(state, player, source, f"activate_{source_kind}", source_zone=action.source_zone):
            raise RulesViolation("Cannot pay skill cost.")
        energy_cost = 0
        if action.source_zone == "hand":
            energy_cost = self._effective_hand_energy_cost(state, player_id=action.player_id, card=source)
        else:
            energy_cost = self._public_activate_energy_cost(
                state,
                player_id=action.player_id,
                source=source,
                source_zone=str(action.source_zone or ""),
                source_kind=source_kind,
                effect_choice=action.effect_choice,
            )
        self._pay_energy_cost(
            player,
            energy_cost,
            required_color=source.color,
            specified_costs=dict(source.specified_costs),
        )
        skill_cost_payload = self._pay_skill_cost(state, player, source, f"activate_{source_kind}", source_zone=action.source_zone)
        selected_effect_id: int | None = None
        if action.source_zone in {"leader", "battle", "unison", "battle_under"} and action.effect_choice is not None:
            selected_effect_id = int(action.effect_choice)
        self._open_counter_window(
            state,
            kind=f"activate_{source_kind}",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=PendingAction(
                action_type=f"activate_{source_kind}",
                actor_player_id=action.player_id,
                payload={
                    "source_zone": action.source_zone,
                    "source_index": action.source_index,
                    "source_instance_id": source.instance_id,
                    "source_card_id": source.card_id,
                    "selected_effect_id": selected_effect_id,
                    **dict(skill_cost_payload),
                },
            ),
        )
        self._checkpoint(state, f"counter_timing_activate_{source_kind}")

    @staticmethod
    def _activate_usage_key(player_id: int, source_kind: str, source: CardInstance) -> tuple[int, str, int]:
        return (player_id, f"activate_{source_kind}", int(source.card_id))

    def _is_activate_limited_this_turn(self, state: GameState, player_id: int, source_kind: str, source: CardInstance) -> bool:
        if not source.activate_limit_once_per_turn:
            return False
        return self._activate_usage_key(player_id, source_kind, source) in state.activate_skill_usage

    def _skill_cost_spec_has_marker_adjustment(self, card_id: int, context: str, *, source_zone: str | None = None) -> bool:
        spec = self._resolve_skill_cost_spec(card_id, context, source_zone=source_zone)
        if spec is None:
            return False
        return any(step.kind in {"remove_markers", "add_markers"} for step in spec.steps)

    def _is_unison_marker_skill_limited_this_turn(self, state: GameState, source: CardInstance, context: str, *, source_zone: str | None = None) -> bool:
        if source.card_type not in {"UNISON", "Z-UNISON"}:
            return False
        if not self._skill_cost_spec_has_marker_adjustment(source.card_id, context, source_zone=source_zone):
            return False
        return source.instance_id in state.unison_marker_skill_usage

    @staticmethod
    def _same_card_number(left: CardInstance, right: CardInstance) -> bool:
        if str(left.card_number or "").strip() and str(right.card_number or "").strip():
            return str(left.card_number).strip().upper() == str(right.card_number).strip().upper()
        return int(left.card_id) == int(right.card_id)

    def _apply_unison_growth(self, state: GameState, action: Action) -> None:
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("UNISON_GROWTH requires a valid hand index.")
        if len(player.unison_area) != 1:
            raise RulesViolation("Unison Growth requires exactly one Unison in play.")
        if action.source_zone != "unison" or action.source_index not in {0, None}:
            raise RulesViolation("Unison Growth must target the active Unison.")
        current_unison = player.unison_area[0]
        if current_unison.instance_id in state.unison_growth_usage:
            raise RulesViolation("This Unison already used growth this turn.")
        growth_card = player.hand[action.hand_index]
        if growth_card.card_type not in {"UNISON", "Z-UNISON"}:
            raise RulesViolation("Only Unison cards can be used for growth.")
        if not self._same_card_number(growth_card, current_unison):
            raise RulesViolation("Unison Growth requires the same card number.")

        grown = player.hand.pop(action.hand_index)
        current_unison.markers += 1
        current_unison.stacked_card_ids = tuple(current_unison.stacked_card_ids) + (int(grown.card_id),)
        if grown.card_type.startswith("Z-"):
            player.removed_from_game.append(grown)
        else:
            player.drop.append(grown)
        state.unison_growth_usage.add(current_unison.instance_id)
        self._emit_effect_event(
            state,
            name="unison_grew",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": current_unison.instance_id,
                "source_card_id": current_unison.card_id,
                "growth_card_id": grown.card_id,
                "markers": current_unison.markers,
            },
        )
        self._checkpoint(state, "unison_growth")

    def _apply_ex_evolve(self, state: GameState, action: Action) -> None:
        player = state.players[action.player_id]
        if action.source_zone not in {"hand", "drop"} or action.source_index is None:
            raise RulesViolation("EX_EVOLVE requires a hand or drop source.")
        source_zone = player.hand if action.source_zone == "hand" else player.drop
        if not (0 <= action.source_index < len(source_zone)):
            raise RulesViolation("EX_EVOLVE source index out of range.")
        if action.target_zone != "battle" or action.target_index is None:
            raise RulesViolation("EX_EVOLVE requires a battle target.")
        if not (0 <= action.target_index < len(player.battle_area)):
            raise RulesViolation("EX_EVOLVE target index out of range.")
        source = source_zone[action.source_index]
        target = player.battle_area[action.target_index]
        spec = self._parse_ex_evolve_spec(source)
        if spec is None:
            raise RulesViolation("Source card does not have EX-Evolve.")
        if bool(spec.get("limit_once")) and (action.player_id, "ex_evolve", int(source.card_id)) in state.activate_skill_usage:
            raise RulesViolation("EX-Evolve limit already used this turn.")
        min_owner_energy = spec.get("min_owner_energy")
        if min_owner_energy is not None and len(player.energy) < int(min_owner_energy):
            raise RulesViolation("EX-Evolve energy threshold is not met.")
        if action.source_zone == "drop" and self._matching_ex_evolve_permission(state, player_id=action.player_id, source=source) is None:
            raise RulesViolation("This EX-Evolve cannot currently activate from Drop.")
        if not self._card_matches_ex_evolve_target(target, spec):
            raise RulesViolation("Battle target does not match EX-Evolve requirements.")
        self._pay_costs(
            player,
            energy_cost=int(spec.get("total_cost", 0) or 0),
            required_color=None,
            specified_costs=dict(spec.get("specified_costs", {})),
            z_cost=0,
        )
        evolved = source_zone.pop(action.source_index)
        base = player.battle_area[action.target_index]
        evolved.resting = bool(base.resting)
        evolved.hidden_mode = bool(base.hidden_mode)
        evolved.attacked_this_turn = bool(base.attacked_this_turn)
        evolved.attack_count_this_turn = int(base.attack_count_this_turn)
        evolved.stacked_card_ids = tuple(base.stacked_card_ids) + (int(base.card_id),)
        player.battle_area[action.target_index] = evolved
        self._register_card_effects(state, player_id=action.player_id, source_zone="battle", card=evolved)
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": evolved.instance_id,
                "source_card_id": evolved.card_id,
                "source_zone": "battle",
                "played_from": action.source_zone,
                "played_via": "ex_evolve",
                "evolved_from_instance_id": base.instance_id,
                "evolved_from_card_id": base.card_id,
            },
        )
        if bool(spec.get("limit_once")):
            state.activate_skill_usage.add((action.player_id, "ex_evolve", int(evolved.card_id)))
        if self._matching_ex_evolve_permission(state, player_id=action.player_id, source=evolved) is not None:
            self._consume_matching_ex_evolve_permission(state, player_id=action.player_id, source=evolved)
        self._checkpoint(state, "ex_evolve")

    def _can_combo_card(self, state: GameState, player_id: int, card: CardInstance) -> bool:
        if self._is_combo_restricted(state, player_id=player_id, card_id=card.card_id):
            return False
        if not card.has_super_combo:
            return True
        player = state.players[player_id]
        if len(player.life) <= 4:
            return True
        if card.sparking_threshold is not None and len(player.drop) >= int(card.sparking_threshold):
            return True
        return False

    def _combo_from_hand(self, state: GameState, action: Action) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step not in {BattleStep.OFFENSE, BattleStep.DEFENSE}:
            raise RulesViolation("Combo not legal now.")
        owner = ctx.attacker_player_id if state.battle_step == BattleStep.OFFENSE else ctx.target_player_id
        if action.player_id != owner:
            raise RulesViolation("Wrong combo player.")
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        if card.card_type not in {"BATTLE", "Z-BATTLE"}:
            raise RulesViolation("Only battle cards can combo.")
        if not self._can_combo_card(state, action.player_id, card):
            raise RulesViolation("This card cannot be comboed right now.")
        self._pay_energy_cost(player, card.combo_cost or 0)
        combo_card = player.hand.pop(action.hand_index)
        combo_card.comboed_from = "hand"
        player.combo_area.append(combo_card)
        self._register_card_effects(state, player_id=action.player_id, source_zone="combo", card=combo_card)
        self._emit_effect_event(
            state,
            name="card_comboed",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": combo_card.instance_id,
                "source_card_id": combo_card.card_id,
                "source_zone": "combo",
                "comboed_from": "hand",
            },
        )
        self._checkpoint(state, "combo_declared")

    def _combo_from_battle(self, state: GameState, action: Action) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step not in {BattleStep.OFFENSE, BattleStep.DEFENSE}:
            raise RulesViolation("Combo not legal now.")
        owner = ctx.attacker_player_id if state.battle_step == BattleStep.OFFENSE else ctx.target_player_id
        if action.player_id != owner:
            raise RulesViolation("Wrong combo player.")
        player = state.players[action.player_id]
        if action.source_zone != "battle" or action.source_index is None or not (0 <= action.source_index < len(player.battle_area)):
            raise RulesViolation("Invalid battle combo source.")
        card = player.battle_area[action.source_index]
        if card.card_type not in {"BATTLE", "Z-BATTLE"}:
            raise RulesViolation("Only battle cards can combo.")
        if not bool(getattr(card, "temporary_can_combo_from_battle_while_resting", False)) or not card.resting:
            raise RulesViolation("This card cannot be comboed from the Battle Area right now.")
        if not self._can_combo_card(state, action.player_id, card):
            raise RulesViolation("This card cannot be comboed right now.")
        self._pay_energy_cost(player, card.combo_cost or 0)
        combo_card = player.battle_area.pop(action.source_index)
        combo_card.comboed_from = "battle"
        player.combo_area.append(combo_card)
        self._register_card_effects(state, player_id=action.player_id, source_zone="combo", card=combo_card)
        self._emit_effect_event(
            state,
            name="card_comboed",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": combo_card.instance_id,
                "source_card_id": combo_card.card_id,
                "source_zone": "combo",
                "comboed_from": "battle",
            },
        )
        self._checkpoint(state, "combo_declared")

    def _activate_blocker(self, state: GameState, action: Action) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.DEFENSE:
            raise RulesViolation("Blocker cannot be activated now.")
        if action.player_id != ctx.target_player_id:
            raise RulesViolation("Wrong blocker player.")
        if action.source_zone != "battle" or action.source_index is None:
            raise RulesViolation("Blocker requires a battle card source.")
        blocker = self._resolve_zone_card(state, player_id=action.player_id, zone="battle", index=action.source_index)
        if blocker.resting:
            raise RulesViolation("Blocker must be active.")
        if not self._card_has_keyword(blocker, "Blocker"):
            raise RulesViolation("Selected card does not have Blocker.")
        if ctx.target_zone == "battle" and ctx.target_instance_id == blocker.instance_id:
            raise RulesViolation("Attack is already targeting this blocker.")
        blocker.resting = True
        state.attack_context = AttackContext(
            attacker_player_id=ctx.attacker_player_id,
            attacker_zone=ctx.attacker_zone,
            attacker_instance_id=ctx.attacker_instance_id,
            target_player_id=ctx.target_player_id,
            target_zone="battle",
            target_instance_id=blocker.instance_id,
        )
        self._emit_effect_event(
            state,
            name="blocker_activated",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": blocker.instance_id,
                "source_card_id": blocker.card_id,
                "redirected_attacker_instance_id": ctx.attacker_instance_id,
            },
        )
        self._checkpoint(state, "blocker_redirect")

    def _end_offense_step(self, state: GameState, player_id: int) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.OFFENSE or player_id != ctx.attacker_player_id:
            raise RulesViolation("Cannot end offense step now.")
        state.battle_step = BattleStep.DAMAGE if ctx.target_zone == "unison" else BattleStep.DEFENSE
        self._checkpoint(state, "battle_damage_step" if state.battle_step == BattleStep.DAMAGE else "battle_defense_step")

    def _end_defense_step(self, state: GameState, player_id: int) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step != BattleStep.DEFENSE or player_id != ctx.target_player_id:
            raise RulesViolation("Cannot end defense step now.")
        state.battle_step = BattleStep.DAMAGE
        self._checkpoint(state, "battle_damage_step")

    def _resolve_battle(self, state: GameState, player_id: int) -> None:
        ctx = state.attack_context
        if ctx is None or state.battle_step is None:
            raise RulesViolation("No battle to resolve.")
        if player_id != ctx.attacker_player_id:
            raise RulesViolation("Only attacker resolves battle.")
        if state.battle_step == BattleStep.BATTLE_END:
            self._apply_due_delayed_mode_switches(
                state,
                trigger_kind="battle_end",
                trigger_player_id=ctx.target_player_id,
            )
            self._clear_battle_modifiers(state)
            self._cleanup_combo_areas(state)
            self._clear_current_battle_protections(state)
            state.attack_context = None
            state.battle_step = None
            return
        if state.battle_step != BattleStep.DAMAGE:
            raise RulesViolation("Resolve battle only in damage/battle-end.")

        attacker = self._find_by_instance(state.players[ctx.attacker_player_id], ctx.attacker_zone, ctx.attacker_instance_id)
        guard = self._find_by_instance(state.players[ctx.target_player_id], ctx.target_zone, ctx.target_instance_id)
        if attacker is None or guard is None:
            state.battle_step = BattleStep.BATTLE_END
            self._emit_effect_event(
                state,
                name="battle_end",
                actor_player_id=ctx.attacker_player_id,
                payload={
                    "attacker_player_id": ctx.attacker_player_id,
                    "attacker_zone": ctx.attacker_zone,
                    "attacker_instance_id": ctx.attacker_instance_id,
                    "target_player_id": ctx.target_player_id,
                    "target_zone": ctx.target_zone,
                    "target_instance_id": ctx.target_instance_id,
                    "target_battle_koed": False,
                },
            )
            if (
                attacker is not None
                and self._card_has_keyword(attacker, "Dual Attack")
                and self._attacks_used_this_turn(attacker) < self._max_attacks_per_turn(attacker)
                and self._can_switch_card_to_active(attacker)
            ):
                attacker.resting = False
            self._clear_current_battle_protections(state)
            self._checkpoint(state, "battle_end_step")
            return
        atk = attacker.power + sum(max(c.combo_power or 0, 0) for c in state.players[ctx.attacker_player_id].combo_area)
        gdp = guard.power + sum(max(c.combo_power or 0, 0) for c in state.players[ctx.target_player_id].combo_area)
        target_battle_koed = False
        if atk >= gdp:
            if ctx.target_zone == "leader":
                if ctx.target_player_id not in state.battle_no_damage_player_ids:
                    self._deal_damage_to_player(
                        state,
                        ctx.target_player_id,
                        self._strike_damage_against_target(
                            state,
                            attacker=attacker,
                            target_player_id=ctx.target_player_id,
                            target_zone=ctx.target_zone,
                        ),
                        critical=self._card_has_keyword(attacker, "Critical"),
                    )
            elif ctx.target_zone == "battle":
                if ctx.target_instance_id not in state.battle_ko_protected_instance_ids:
                    moved = None
                    if self._text_attack_ko_replaced_with_gain_control(attacker):
                        moved = self._transfer_board_card_control(
                            state,
                            from_player_id=ctx.target_player_id,
                            to_player_id=ctx.attacker_player_id,
                            zone="battle",
                            instance_id=ctx.target_instance_id,
                        )
                        if moved is not None:
                            moved.resting = False
                            self._checkpoint(state, "battle_ko_replaced_with_gain_control")
                    if moved is None and self._text_battle_ko_replaced_with_place_one_under_to_drop(guard):
                        if self._pay_self_under_drop_replacement(state, owner_player_id=ctx.target_player_id, source=guard, amount=1):
                            moved = guard
                            self._checkpoint(state, "battle_ko_replaced_with_under_drop")
                    if moved is None:
                        self._ko_card(state, ctx.target_player_id, "battle", ctx.target_instance_id)
                        target_battle_koed = True
            else:
                self._apply_unison_battle_damage(state, ctx.target_player_id, ctx.target_instance_id, attacker)
        self._check_loss_conditions(state)
        state.battle_step = BattleStep.BATTLE_END
        self._emit_effect_event(
            state,
            name="battle_end",
            actor_player_id=ctx.attacker_player_id,
            payload={
                "attacker_player_id": ctx.attacker_player_id,
                "attacker_zone": ctx.attacker_zone,
                "attacker_instance_id": ctx.attacker_instance_id,
                "target_player_id": ctx.target_player_id,
                "target_zone": ctx.target_zone,
                "target_instance_id": ctx.target_instance_id,
                "target_battle_koed": target_battle_koed,
            },
        )
        if (
            self._card_has_keyword(attacker, "Dual Attack")
            and self._attacks_used_this_turn(attacker) < self._max_attacks_per_turn(attacker)
            and self._can_switch_card_to_active(attacker)
        ):
            attacker.resting = False
        self._checkpoint(state, "battle_end_step")

    def _declare_counter_from_hand(self, state: GameState, action: Action) -> None:
        win = state.counter_window
        if win is None or action.player_id != win.responder_player_id:
            raise RulesViolation("Counter not legal now.")
        player = state.players[action.player_id]
        if action.hand_index is None or not (0 <= action.hand_index < len(player.hand)):
            raise RulesViolation("Invalid hand index.")
        card = player.hand[action.hand_index]
        if not card.has_counter:
            raise RulesViolation("Card is not Counter.")
        allowed_modes = self._allowed_counter_modes(state)
        if allowed_modes and not self._card_matches_counter_window(card, allowed_modes):
            raise RulesViolation("Counter mode does not match current counter timing.")
        if (
            "Counter: Counter" in allowed_modes
            and self._text_counter_counter_negates_only_attack(card)
            and (
                not state.counter_chain
                or "Counter: Attack" not in tuple(state.counter_chain[-1].modes or ())
            )
        ):
            raise RulesViolation("Counter: Counter card can only negate Counter: Attack here.")
        if self._is_counter_hand_activation_restricted(state, player_id=action.player_id, card=card):
            raise RulesViolation("This counter skill is currently restricted.")
        if not self._can_pay_skill_cost(state, player, card, "counter_from_hand"):
            raise RulesViolation("Cannot pay counter skill cost.")
        closed_pending_counter_ids = self._other_pending_counter_hand_instance_ids(
            state,
            player_id=action.player_id,
            chosen_hand_index=action.hand_index,
        )
        effective_energy_cost = self._effective_hand_energy_cost(state, player_id=action.player_id, card=card)
        free_counter_via_four_colors = False
        if self._text_counter_can_activate_for_free_with_four_colors_among_energy_and_battle(card):
            color_names: set[str] = set()
            for zone_card in [*player.energy, *player.battle_area]:
                for part in str(getattr(zone_card, "color", "") or "").replace("/", ",").split(","):
                    cleaned = part.strip().lower()
                    if cleaned:
                        color_names.add(cleaned)
            free_counter_via_four_colors = len(color_names) >= 4
        if self._can_pay_energy_cost(
            player,
            effective_energy_cost,
            required_color=card.color,
            specified_costs=dict(card.specified_costs),
        ):
            self._pay_energy_cost(
                player,
                effective_energy_cost,
                required_color=card.color,
                specified_costs=dict(card.specified_costs),
            )
        elif free_counter_via_four_colors:
            pass
        elif not self._pay_alternate_counter_hand_cost(state, player, card):
            raise RulesViolation("Not enough resources to pay counter cost.")
        skill_cost_payload = self._pay_skill_cost(state, player, card, "counter_from_hand")
        declared = player.hand.pop(action.hand_index)
        player.drop.append(declared)
        self._register_card_effects(state, player_id=action.player_id, source_zone="drop", card=declared)
        self._emit_card_placed_into_drop(state, owner_player_id=action.player_id, card=declared, source_zone="hand")
        self._emit_effect_event(
            state,
            name="counter_skill_activated",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": declared.instance_id,
                "source_card_id": declared.card_id,
                "source_zone": "drop",
                "counter_modes": ",".join(str(mode) for mode in tuple(declared.counter_modes or ())),
                "counter_window_kind": win.kind,
            },
        )
        self._checkpoint(state, "counter_declared")
        state.counter_chain.append(
            CounterMotion(
                motion_id=state.next_counter_motion_id,
                player_id=action.player_id,
                card_instance_id=declared.instance_id,
                modes=declared.counter_modes,
                payload=dict(skill_cost_payload),
            )
        )
        state.counter_motion_trace.append(
            CounterMotionTrace(
                motion_id=state.next_counter_motion_id,
                turn_number=state.turn_number,
                phase=state.phase,
                window_kind=win.kind,
                pending_action_type=win.pending_action.action_type,
                player_id=action.player_id,
                card_instance_id=declared.instance_id,
                modes=declared.counter_modes,
                resolved=None,
                negated_motion_id=None,
            )
        )
        self._checkpoint(state, f"counter_motion_declared_{state.next_counter_motion_id}")
        if closed_pending_counter_ids:
            state.log.append(
                "Counter pending choices closed: "
                f"player_id={action.player_id} hand_instance_ids={','.join(str(v) for v in closed_pending_counter_ids)} window_kind={win.kind}"
            )
            self._checkpoint(state, "counter_pending_choices_closed")
        state.next_counter_motion_id += 1

        pending = win.pending_action
        state.counter_window = None
        self._open_counter_window(
            state,
            kind="counter_chain",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=pending,
        )
        self._checkpoint(state, "counter_chain_timing")

    def _declare_counter_from_energy(self, state: GameState, action: Action) -> None:
        win = state.counter_window
        if win is None or action.player_id != win.responder_player_id:
            raise RulesViolation("Counter not legal now.")
        player = state.players[action.player_id]
        if action.source_zone != "energy" or action.source_index is None or not (0 <= action.source_index < len(player.energy)):
            raise RulesViolation("Invalid energy index.")
        card = player.energy[action.source_index]
        if not card.has_counter:
            raise RulesViolation("Card is not Counter.")
        allowed_modes = self._allowed_counter_modes(state)
        if allowed_modes and not self._card_matches_counter_window(card, allowed_modes):
            raise RulesViolation("Counter mode does not match current counter timing.")
        if not self._can_activate_counter_from_energy(state, player_id=action.player_id, card=card):
            raise RulesViolation("This counter cannot be activated from energy here.")
        if not self._can_pay_energy_cost(
            player,
            int(card.energy_cost or 0),
            required_color=card.color,
            specified_costs=dict(card.specified_costs),
        ):
            raise RulesViolation("Not enough resources to pay counter cost.")
        self._pay_energy_cost(
            player,
            int(card.energy_cost or 0),
            required_color=card.color,
            specified_costs=dict(card.specified_costs),
        )
        lower = str(card.skill_text_raw or "").lower()
        if "discarding 1 card from your hand" in lower:
            if not player.hand:
                raise RulesViolation("Not enough resources to pay counter cost.")
            discarded = player.hand.pop(0)
            player.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=action.player_id, card=discarded, source_zone="hand")
        declared = player.energy.pop(action.source_index)
        player.drop.append(declared)
        self._register_card_effects(state, player_id=action.player_id, source_zone="drop", card=declared)
        self._emit_card_placed_into_drop(state, owner_player_id=action.player_id, card=declared, source_zone="energy")
        self._emit_effect_event(
            state,
            name="counter_skill_activated",
            actor_player_id=action.player_id,
            payload={
                "source_instance_id": declared.instance_id,
                "source_card_id": declared.card_id,
                "source_zone": "drop",
                "counter_modes": ",".join(str(mode) for mode in tuple(declared.counter_modes or ())),
                "counter_window_kind": win.kind,
            },
        )
        self._checkpoint(state, "counter_declared")
        state.counter_chain.append(
            CounterMotion(
                motion_id=state.next_counter_motion_id,
                player_id=action.player_id,
                card_instance_id=declared.instance_id,
                modes=declared.counter_modes,
                payload={},
            )
        )
        state.counter_motion_trace.append(
            CounterMotionTrace(
                motion_id=state.next_counter_motion_id,
                turn_number=state.turn_number,
                phase=state.phase,
                window_kind=win.kind,
                pending_action_type=win.pending_action.action_type,
                player_id=action.player_id,
                card_instance_id=declared.instance_id,
                modes=declared.counter_modes,
                resolved=None,
                negated_motion_id=None,
            )
        )
        self._checkpoint(state, f"counter_motion_declared_{state.next_counter_motion_id}")
        state.next_counter_motion_id += 1

        pending = win.pending_action
        state.counter_window = None
        self._open_counter_window(
            state,
            kind="counter_chain",
            responder_player_id=self._opponent_of(action.player_id),
            pending_action=pending,
        )
        self._checkpoint(state, "counter_chain_timing")

    def _other_pending_counter_hand_instance_ids(
        self,
        state: GameState,
        *,
        player_id: int,
        chosen_hand_index: int,
    ) -> list[int]:
        win = state.counter_window
        if win is None or player_id != win.responder_player_id:
            return []
        player = state.players[player_id]
        allowed_modes = self._allowed_counter_modes(state)
        pending_ids: list[int] = []
        for index, card in enumerate(player.hand):
            if index == chosen_hand_index or not card.has_counter:
                continue
            if allowed_modes and not self._card_matches_counter_window(card, allowed_modes):
                continue
            effective_energy_cost = self._effective_hand_energy_cost(state, player_id=player_id, card=card)
            can_pay_energy = self._can_pay_energy_cost(
                player,
                effective_energy_cost,
                required_color=card.color,
                specified_costs=dict(card.specified_costs),
            )
            if not (can_pay_energy or self._can_pay_alternate_counter_hand_cost(state, player, card)):
                continue
            if not self._can_pay_skill_cost(state, player, card, "counter_from_hand"):
                continue
            pending_ids.append(int(card.instance_id))
        return pending_ids

    def _pass_counter_window(self, state: GameState, player_id: int) -> None:
        if state.counter_window is None or state.counter_window.responder_player_id != player_id:
            raise RulesViolation("No counter window to pass.")
        if state.counter_window.kind == "counter_chain":
            negated = self._resolve_counter_chain(state)
            self._resolve_pending_effects(state)
            self._resolve_pending_action(state, negated=negated)
            return
        self._resolve_pending_action(state, negated=False)

    def _open_counter_window(self, state: GameState, *, kind: str, responder_player_id: int, pending_action: PendingAction) -> None:
        if state.counter_window is not None:
            raise RulesViolation("Counter window already open.")
        state.counter_window = CounterWindow(kind=kind, responder_player_id=responder_player_id, pending_action=pending_action)

    def _allowed_counter_modes(self, state: GameState) -> set[str]:
        win = state.counter_window
        if win is None:
            return set()
        if win.kind == "counter_chain":
            return {"Counter: Counter"}
        if win.kind == "attack":
            modes = {"Counter: Attack"}
            ctx = state.attack_context
            if ctx is not None and ctx.attacker_zone == "battle":
                modes.add("Counter: Battle Card Attack")
            return modes
        if win.kind == "play":
            return {"Counter: Play"}
        if win.kind == "activate_extra_from_hand":
            return {"Counter: Counter"}
        if win.kind.startswith("activate_"):
            return {"Counter: Counter"}
        return set()

    @staticmethod
    def _card_matches_counter_window(card: CardInstance, allowed_modes: set[str]) -> bool:
        if not allowed_modes:
            return True
        if card.counter_modes:
            return any(mode in allowed_modes for mode in card.counter_modes)
        # Strict mode: no generic fallback; explicit mode/flags required.
        if "Counter: Attack" in allowed_modes and card.has_counter_attack:
            return True
        if "Counter: Play" in allowed_modes and card.has_counter_play:
            return True
        if "Counter: Counter" in allowed_modes and card.has_counter_counter:
            return True
        if "Counter: Battle Card Attack" in allowed_modes and card.has_counter_battle_card_attack:
            return True
        return False

    @staticmethod
    def _card_skills_are_negated(card: CardInstance) -> bool:
        return bool(getattr(card, "temporary_skills_negated", False) or getattr(card, "permanent_skills_negated", False))

    @staticmethod
    def _card_keyword_skills_are_negated(card: CardInstance) -> bool:
        return bool(
            getattr(card, "temporary_keyword_skills_negated", False)
            or RulesEngine._card_skills_are_negated(card)
        )

    @staticmethod
    def _card_has_keyword(card: CardInstance, keyword: str) -> bool:
        if RulesEngine._card_keyword_skills_are_negated(card):
            return False
        needle = str(keyword).strip().lower()
        return any(
            str(item).strip().lower() == needle
            for item in (
                (card.keywords or ())
                + (card.temporary_keywords or ())
                + (card.battle_temporary_keywords or ())
                + (card.delayed_temporary_keywords or ())
            )
        )

    def _apply_delayed_union_play_keyword_grants(self, state: GameState, event: EffectEvent) -> None:
        if event.name != "card_played":
            return
        played_via = str(event.payload.get("played_via") or "").strip().lower()
        if not played_via.startswith("union_"):
            return
        actor_player_id = event.actor_player_id
        if actor_player_id is None:
            return
        owner = state.players.get(actor_player_id)
        if owner is None:
            return
        source_instance_id = int(event.payload.get("source_instance_id") or -1)
        target = self._find_by_instance(owner, "battle", source_instance_id)
        if target is None:
            return
        updated: list[DelayedUnionPlayKeywordGrant] = []
        applied = False
        for row in state.delayed_union_play_keyword_grants:
            if (
                not applied
                and int(row.owner_player_id) == int(actor_player_id)
                and self._card_matches_effect_filters(
                    target,
                    allowed_colors={item.strip().lower() for item in str(row.allowed_colors or "").split(",") if item.strip()},
                    required_traits={item.strip().lower() for item in str(row.required_traits or "").split(",") if item.strip()},
                    required_characters={item.strip().lower() for item in str(row.required_characters or "").split(",") if item.strip()},
                    required_name_contains=str(row.required_name_contains or ""),
                    required_card_types={"BATTLE", "Z-BATTLE"},
                )
            ):
                if str(row.grant_keyword or "").strip():
                    self._append_temporary_keyword(target, str(row.grant_keyword), duration="turn")
                applied = True
                remaining = int(row.uses_remaining) - 1
                if remaining > 0:
                    updated.append(
                        DelayedUnionPlayKeywordGrant(
                            owner_player_id=row.owner_player_id,
                            created_turn_number=row.created_turn_number,
                            grant_keyword=row.grant_keyword,
                            allowed_colors=row.allowed_colors,
                            required_traits=row.required_traits,
                            required_characters=row.required_characters,
                            required_name_contains=row.required_name_contains,
                            uses_remaining=remaining,
                            expires_on_turn_end_player_id=row.expires_on_turn_end_player_id,
                        )
                    )
                continue
            updated.append(row)
        if applied:
            state.delayed_union_play_keyword_grants = updated
            self._checkpoint(state, "delayed_union_play_keyword_grant_applied")

    def _max_attacks_per_turn(self, card: CardInstance) -> int:
        return 2 if self._card_has_keyword(card, "Dual Attack") else 1

    def _attacks_used_this_turn(self, card: CardInstance) -> int:
        return max(int(getattr(card, "attack_count_this_turn", 0)), 1 if card.attacked_this_turn else 0)

    def _available_rest_tax_cards(
        self,
        state: GameState,
        *,
        player_id: int,
        excluded_instance_ids: set[int] | None = None,
    ) -> list[CardInstance]:
        owner = state.players[player_id]
        excluded = {int(item) for item in (excluded_instance_ids or set())}
        candidates: list[CardInstance] = []
        if owner.leader_area.instance_id not in excluded and not owner.leader_area.resting:
            candidates.append(owner.leader_area)
        for zone_cards in (owner.energy, owner.battle_area, owner.unison_area):
            for card in zone_cards:
                if int(card.instance_id) in excluded or card.resting:
                    continue
                candidates.append(card)
        return candidates

    def _owner_has_battle_skill_negation_protection(self, state: GameState, *, player_id: int) -> bool:
        owner = state.players.get(player_id)
        if owner is None:
            return False
        needle = "skills on your battle cards can't be negated by your opponent's skills"
        for card in owner.battle_area:
            text = str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "").strip().lower()
            if needle in text:
                return True
        return False

    def _owner_has_rest_protection_against_opponent_skills(self, state: GameState, *, player_id: int) -> bool:
        owner = state.players.get(player_id)
        if owner is None:
            return False
        needle = "your cards can't be switched to rest mode by your opponent's skills"
        for card in owner.battle_area:
            text = str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "").strip().lower()
            if needle in text:
                return True
        return False

    def _controller_player_id_for_card(self, state: GameState, card: CardInstance) -> int:
        for player_id, player in state.players.items():
            if player.leader_area.instance_id == card.instance_id:
                return player_id
            for zone_cards in (
                player.hand,
                player.life,
                player.energy,
                player.z_energy,
                player.battle_area,
                player.unison_area,
                player.combo_area,
                player.drop,
                player.warp,
                player.removed_from_game,
            ):
                if any(item.instance_id == card.instance_id for item in zone_cards):
                    return player_id
        return int(getattr(card, "owner_id", 0) or 0)

    @staticmethod
    def _text_resting_card_prevents_opponent_battle_attacks_on_leaders(card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "").lower()
        return (
            "this card is in rest mode" in text
            and (
                "your opponent's battle cards can't attack leaders" in text
                or "your opponent's battle cards can't attack leader cards" in text
            )
        )

    def _resting_card_prevents_opponent_battle_attacks_on_leaders(
        self,
        state: GameState,
        *,
        protected_player_id: int,
        card: CardInstance,
    ) -> bool:
        if not bool(getattr(card, "resting", False)):
            return False
        if not self._text_resting_card_prevents_opponent_battle_attacks_on_leaders(card):
            return False
        text = str(card.skill_text_raw or "")
        if "mono-blue" not in text.lower() and "mono blue" not in text.lower():
            return True
        owner = state.players.get(protected_player_id)
        if owner is None:
            return False
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        return self._text_hand_cost_reduction_requirements_met(
            text,
            state=state,
            owner=owner,
            leader=leader,
            leader_runtime=leader_runtime,
        )

    @staticmethod
    def _text_card_cannot_attack(card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "").lower()
        return "this card can't attack" in text

    @staticmethod
    def _text_replaces_battle_or_combo_drop_with_bottom_deck(card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "").lower()
        return (
            "when this card is placed in a drop area from a battle area or combo area" in text
            and "bottom of its owner's deck instead" in text
        )

    @staticmethod
    def _text_replaces_battle_leave_with_removed(card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "").lower()
        return "if this card would leave the battle area" in text and "remove it from the game instead" in text

    @staticmethod
    def _text_can_attack_active_battles_without_barrier(card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "").lower()
        return "can attack battle cards without [barrier] in active mode" in text

    def _opponent_skill_can_negate_battle_card_skills(
        self,
        state: GameState,
        *,
        acting_player_id: int | None,
        target_card: CardInstance,
    ) -> bool:
        controlled_by = self._controller_player_id_for_card(state, target_card)
        if acting_player_id is None or int(acting_player_id) == controlled_by:
            return True
        if str(target_card.card_type or "").strip().upper() not in {"BATTLE", "Z-BATTLE"}:
            return True
        return not self._owner_has_battle_skill_negation_protection(state, player_id=controlled_by)

    def _opponent_skill_can_switch_card_to_rest(
        self,
        state: GameState,
        *,
        acting_player_id: int | None,
        target_card: CardInstance,
    ) -> bool:
        controlled_by = self._controller_player_id_for_card(state, target_card)
        if acting_player_id is None or int(acting_player_id) == controlled_by:
            return True
        return not self._owner_has_rest_protection_against_opponent_skills(state, player_id=controlled_by)

    def _required_non_leader_attack_rest_count(
        self,
        state: GameState,
        *,
        affected_player_id: int,
    ) -> int:
        return sum(
            max(int(row.rest_count), 0)
            for row in state.non_leader_attack_rest_taxes
            if int(row.affected_player_id) == int(affected_player_id)
        )

    def _can_pay_non_leader_attack_rest_tax(
        self,
        state: GameState,
        *,
        player_id: int,
        excluded_instance_ids: set[int] | None = None,
    ) -> bool:
        required = self._required_non_leader_attack_rest_count(state, affected_player_id=player_id)
        if required <= 0:
            return True
        return len(self._available_rest_tax_cards(state, player_id=player_id, excluded_instance_ids=excluded_instance_ids)) >= required

    def _apply_non_leader_attack_rest_tax(
        self,
        state: GameState,
        *,
        player_id: int,
        excluded_instance_ids: set[int] | None = None,
    ) -> bool:
        required = self._required_non_leader_attack_rest_count(state, affected_player_id=player_id)
        if required <= 0:
            return True
        if any(
            int(row.affected_player_id) == int(player_id)
            and int(row.owner_player_id) != int(player_id)
            for row in state.non_leader_attack_rest_taxes
        ) and self._owner_has_rest_protection_against_opponent_skills(state, player_id=player_id):
            self._checkpoint(state, "non_leader_attack_rest_tax_prevented_by_protection")
            return True
        candidates = self._available_rest_tax_cards(state, player_id=player_id, excluded_instance_ids=excluded_instance_ids)
        if len(candidates) < required:
            return False
        for card in candidates[:required]:
            card.resting = True
        self._checkpoint(state, "non_leader_attack_rest_tax_applied")
        return True

    def _required_non_leader_attack_hand_z_tax(
        self,
        state: GameState,
        *,
        affected_player_id: int,
    ) -> tuple[int, int]:
        required_hand = 0
        required_z = 0
        for row in state.non_leader_attack_hand_z_taxes:
            if int(row.affected_player_id) != int(affected_player_id):
                continue
            required_hand += max(int(row.hand_count), 0)
            required_z += max(int(row.z_energy_count), 0)
        return required_hand, required_z

    def _can_pay_non_leader_attack_hand_z_tax(
        self,
        state: GameState,
        *,
        player_id: int,
    ) -> bool:
        required_hand, required_z = self._required_non_leader_attack_hand_z_tax(state, affected_player_id=player_id)
        if required_hand <= 0 and required_z <= 0:
            return True
        player = state.players.get(player_id)
        if player is None:
            return False
        return len(player.hand) >= required_hand and len(player.z_energy) >= required_z

    def _apply_non_leader_attack_hand_z_tax(
        self,
        state: GameState,
        *,
        player_id: int,
    ) -> bool:
        required_hand, required_z = self._required_non_leader_attack_hand_z_tax(state, affected_player_id=player_id)
        if required_hand <= 0 and required_z <= 0:
            return True
        player = state.players.get(player_id)
        if player is None:
            return False
        if len(player.hand) < required_hand or len(player.z_energy) < required_z:
            return False
        for _ in range(required_hand):
            discarded = player.hand.pop(0)
            player.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=player_id, card=discarded, source_zone="hand")
        for _ in range(required_z):
            z_card = player.z_energy.pop(0)
            player.drop.append(z_card)
            self._emit_card_placed_into_drop(state, owner_player_id=player_id, card=z_card, source_zone="z_energy")
        self._checkpoint(state, "non_leader_attack_hand_z_tax_applied")
        return True

    @staticmethod
    def _battle_attack_bottom_deck_tax_applies_to_attacker(
        row: BattleAttackBottomDeckHandTax,
        *,
        attacker: CardInstance,
        current_energy_count: int,
    ) -> bool:
        attack_cost = int(attacker.energy_cost or 0)
        max_cost = int(getattr(row, "max_cost", -1) or -1)
        if max_cost >= 0 and attack_cost > max_cost:
            return False
        threshold = current_energy_count + max(int(row.min_cost_greater_than_current_energy), 0)
        return attack_cost >= threshold

    def _required_battle_attack_bottom_deck_battle_count(
        self,
        state: GameState,
        *,
        affected_player_id: int,
        attacker: CardInstance,
    ) -> tuple[int, int]:
        player = state.players.get(affected_player_id)
        if player is None:
            return 0, -1
        current_energy_count = len(player.energy)
        required = 0
        payment_max_battle_cost = -1
        for row in state.battle_attack_bottom_deck_taxes:
            if int(row.affected_player_id) != int(affected_player_id):
                continue
            if not self._battle_attack_bottom_deck_tax_applies_to_attacker(row, attacker=attacker, current_energy_count=current_energy_count):
                continue
            required += max(int(getattr(row, "battle_count", 0) or 0), 0)
            row_payment_max = int(getattr(row, "payment_max_battle_cost", -1) or -1)
            if row_payment_max >= 0:
                payment_max_battle_cost = row_payment_max if payment_max_battle_cost < 0 else min(payment_max_battle_cost, row_payment_max)
        return required, payment_max_battle_cost

    def _required_battle_attack_bottom_deck_hand_count(
        self,
        state: GameState,
        *,
        affected_player_id: int,
        attacker: CardInstance,
    ) -> int:
        player = state.players.get(affected_player_id)
        if player is None:
            return 0
        current_energy_count = len(player.energy)
        required = 0
        for row in state.battle_attack_bottom_deck_taxes:
            if int(row.affected_player_id) != int(affected_player_id):
                continue
            if not self._battle_attack_bottom_deck_tax_applies_to_attacker(row, attacker=attacker, current_energy_count=current_energy_count):
                continue
            required += max(int(row.hand_count), 0)
        return required

    def _can_pay_battle_attack_bottom_deck_tax(
        self,
        state: GameState,
        *,
        player_id: int,
        attacker: CardInstance,
    ) -> bool:
        required_hand = self._required_battle_attack_bottom_deck_hand_count(
            state,
            affected_player_id=player_id,
            attacker=attacker,
        )
        if required_hand <= 0:
            return True
        player = state.players.get(player_id)
        if player is None:
            return False
        required_battle, payment_max_battle_cost = self._required_battle_attack_bottom_deck_battle_count(
            state,
            affected_player_id=player_id,
            attacker=attacker,
        )
        if len(player.hand) < required_hand:
            return False
        if required_battle <= 0:
            return True
        available_battles = sum(
            1
            for card in player.battle_area
            if payment_max_battle_cost < 0 or int(card.energy_cost or -1) <= payment_max_battle_cost
        )
        return available_battles >= required_battle

    def _apply_battle_attack_bottom_deck_tax(
        self,
        state: GameState,
        *,
        player_id: int,
        attacker: CardInstance,
    ) -> bool:
        required_hand = self._required_battle_attack_bottom_deck_hand_count(
            state,
            affected_player_id=player_id,
            attacker=attacker,
        )
        required_battle, payment_max_battle_cost = self._required_battle_attack_bottom_deck_battle_count(
            state,
            affected_player_id=player_id,
            attacker=attacker,
        )
        if required_hand <= 0 and required_battle <= 0:
            return True
        player = state.players.get(player_id)
        if player is None or len(player.hand) < required_hand:
            return False
        if required_battle > 0:
            available_battle_indexes = [
                i
                for i, card in enumerate(player.battle_area)
                if payment_max_battle_cost < 0 or int(card.energy_cost or -1) <= payment_max_battle_cost
            ]
            if len(available_battle_indexes) < required_battle:
                return False
        for _ in range(required_hand):
            player.deck.append(player.hand.pop(0).card_id)
        removed = 0
        if required_battle > 0:
            for battle_idx in available_battle_indexes[:required_battle]:
                moved = player.battle_area.pop(battle_idx - removed)
                removed += 1
                player.deck.append(moved.card_id)
        self._checkpoint(state, "battle_attack_bottom_deck_tax_applied")
        return True

    def _required_battle_attack_discard_hand_count(
        self,
        state: GameState,
        *,
        affected_player_id: int,
    ) -> int:
        required = 0
        for row in state.battle_attack_discard_hand_taxes:
            if int(row.affected_player_id) != int(affected_player_id):
                continue
            required += max(int(row.hand_count), 0)
        return required

    def _can_pay_battle_attack_discard_hand_tax(
        self,
        state: GameState,
        *,
        player_id: int,
    ) -> bool:
        required_hand = self._required_battle_attack_discard_hand_count(state, affected_player_id=player_id)
        if required_hand <= 0:
            return True
        player = state.players.get(player_id)
        if player is None:
            return False
        return len(player.hand) >= required_hand

    def _apply_battle_attack_discard_hand_tax(
        self,
        state: GameState,
        *,
        player_id: int,
    ) -> bool:
        required_hand = self._required_battle_attack_discard_hand_count(state, affected_player_id=player_id)
        if required_hand <= 0:
            return True
        player = state.players.get(player_id)
        if player is None or len(player.hand) < required_hand:
            return False
        for _ in range(required_hand):
            discarded = player.hand.pop(0)
            player.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=player.player_id, card=discarded, source_zone="hand")
        self._checkpoint(state, "battle_attack_discard_hand_tax_applied")
        return True

    @staticmethod
    def _clear_current_battle_protections(state: GameState) -> None:
        state.battle_no_damage_player_ids.clear()
        state.battle_ko_protected_instance_ids.clear()

    def _can_card_attack_this_turn(self, card: CardInstance, state: GameState) -> bool:
        card_name = str(getattr(card, "card_name", "") or "").upper()
        if (
            card.resting
            or card.hidden_mode
            or card.instance_id in state.attack_restricted_instance_ids
            or any(needle and needle in card_name for needle in state.attack_restricted_name_contains)
        ):
            return False
        if self._text_card_cannot_attack(card):
            return False
        return self._attacks_used_this_turn(card) < self._max_attacks_per_turn(card)

