    @staticmethod
    def _owner_hidden_mode_count(player: PlayerState) -> int:
        return sum(
            1
            for card in [*player.battle_area, *player.unison_area, *player.energy]
            if getattr(card, "hidden_mode", False)
        )

    def _resolve_pending_action(self, state: GameState, *, negated: bool) -> None:
        win = state.counter_window
        if win is None:
            raise RulesViolation("No pending action.")
        pending = win.pending_action
        state.counter_window = None
        if pending.action_type == "attack":
            state.battle_step = BattleStep.BATTLE_END if negated else BattleStep.OFFENSE
            self._checkpoint(state, "battle_end_step" if negated else "battle_offense_step")
            if negated:
                state.attack_context = None
            return
        if pending.action_type == "play_from_hand":
            self._resolve_play_from_hand(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_drop":
            self._resolve_play_from_drop(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_warp":
            self._resolve_play_from_warp(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_z_energy":
            self._resolve_play_from_z_energy(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_energy":
            self._resolve_play_from_energy(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_leader_under":
            self._resolve_play_from_leader_under(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_battle_under":
            self._resolve_play_from_battle_under(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_leader_under_to_opponent_battle":
            self._resolve_play_from_leader_under_to_opponent_battle(state, pending, negated=negated)
            return
        if pending.action_type == "play_from_opponent_hand_to_opponent_battle":
            self._resolve_play_from_opponent_hand_to_opponent_battle(state, pending, negated=negated)
            return
        if pending.action_type == "activate_extra_from_hand":
            self._resolve_extra_activation_from_hand(state, pending, negated=negated)
            return
        if pending.action_type in {"activate_main", "activate_battle"}:
            if negated:
                self._checkpoint(state, "skill_activation_negated")
                return
            source_zone = str(pending.payload.get("source_zone") or "")
            source_index_raw = pending.payload.get("source_index")
            source_index = None if source_index_raw in {None, -1} else int(source_index_raw)
            player = state.players[pending.actor_player_id]
            source_instance_id = int(pending.payload.get("source_instance_id") or -1)
            source = self._find_by_instance(player, source_zone, source_instance_id) if source_instance_id != -1 else None
            if source is None and source_instance_id != -1:
                found = self._find_card_anywhere_by_instance(
                    state,
                    owner_player_id=pending.actor_player_id,
                    instance_id=source_instance_id,
                )
                if found is not None:
                    _found_zone, source = found
            if source is None and source_zone not in {"hand", "warp", "combo", "drop"}:
                source = self._resolve_zone_card(state, player_id=pending.actor_player_id, zone=source_zone, index=source_index)
            if source is not None and source.activate_limit_once_per_turn:
                source_kind = "main" if pending.action_type == "activate_main" else "battle"
                state.activate_skill_usage.add(self._activate_usage_key(pending.actor_player_id, source_kind, source))
            if (
                source is not None
                and source.card_type in {"UNISON", "Z-UNISON"}
                and self._skill_cost_spec_has_marker_adjustment(
                    int(pending.payload.get("source_card_id") or getattr(source, "card_id", -1)),
                    pending.action_type,
                    source_zone=source_zone,
                )
            ):
                state.unison_marker_skill_usage.add(int(pending.payload.get("source_instance_id") or source.instance_id))
            selected_effect_id_for_event = int(pending.payload.get("selected_effect_id") or -1)
            if selected_effect_id_for_event > 0:
                selected_reg = next(
                    (
                        reg
                        for reg in state.effect_registry
                        if int(reg.effect_id) == selected_effect_id_for_event
                        and int(reg.source_instance_id) == int(source_instance_id)
                    ),
                    None,
                )
                if selected_reg is None or not bool(selected_reg.handler_params.get("requires_effect_choice_match")):
                    selected_effect_id_for_event = -1
            self._emit_effect_event(
                state,
                name="skill_activated",
                actor_player_id=pending.actor_player_id,
                payload={
                    "source_zone": str(pending.payload.get("source_zone") or ""),
                    "source_index": (
                        -1
                        if pending.payload.get("source_index") in {None, -1}
                        else int(pending.payload.get("source_index"))
                    ),
                    "source_instance_id": int(pending.payload.get("source_instance_id") or -1),
                    "source_card_id": int(pending.payload.get("source_card_id") or -1),
                    "skill_kind": pending.action_type,
                    "selected_effect_id": selected_effect_id_for_event,
                    **{
                        str(key): value
                        for key, value in pending.payload.items()
                        if str(key).startswith("cost_")
                    },
                },
            )
            matching_registered_effect = any(
                reg.source_instance_id == source_instance_id
                and reg.trigger == ("self_activate_main" if pending.action_type == "activate_main" else "self_activate_battle")
                for reg in state.effect_registry
            )
            if not matching_registered_effect:
                state.log.append(
                    f"Unsupported skill activation: source_card_id={int(pending.payload.get('source_card_id') or -1)} kind={pending.action_type}"
                )
                self._checkpoint(state, "skill_activation_no_registered_effect")
            self._checkpoint(state, "skill_activation_resolved")
            return
        raise RulesViolation(f"Unknown pending action type: {pending.action_type}")

    def _resolve_counter_chain(self, state: GameState) -> bool:
        motions = state.counter_chain
        if not motions:
            return False
        self._checkpoint(state, "counter_chain_resolution_begin")
        state.log.append(f"Counter chain resolution begin: motion_count={len(motions)}")

        motion_by_id = {motion.motion_id: motion for motion in motions}
        pending_action_type_by_motion = {
            trace.motion_id: trace.pending_action_type
            for trace in state.counter_motion_trace
            if trace.resolved is None
        }
        active: dict[int, bool] = {m.motion_id: True for m in motions}
        index_by_id = {m.motion_id: i for i, m in enumerate(motions)}

        resolutions: list[CounterResolution] = []
        for resolution_order, motion in enumerate(reversed(motions), start=1):
            if not active[motion.motion_id]:
                resolutions.append(
                    CounterResolution(
                        motion_id=motion.motion_id,
                        player_id=motion.player_id,
                        pending_action_type=pending_action_type_by_motion.get(motion.motion_id, "unknown"),
                        resolved=False,
                        negated_motion_id=None,
                        resolution_order=resolution_order,
                    )
                )
                continue

            prev_idx = index_by_id[motion.motion_id] - 1
            negated_id: int | None = None
            if prev_idx >= 0:
                prev_motion = motions[prev_idx]
                active[prev_motion.motion_id] = False
                negated_id = prev_motion.motion_id

            resolutions.append(
                CounterResolution(
                    motion_id=motion.motion_id,
                    player_id=motion.player_id,
                    pending_action_type=pending_action_type_by_motion.get(motion.motion_id, "unknown"),
                    resolved=True,
                    negated_motion_id=negated_id,
                    resolution_order=resolution_order,
                )
            )

        effect_tags_by_motion = self._apply_resolved_counter_motion_effects(state, motions, resolutions)
        enriched_resolutions = [
            CounterResolution(
                motion_id=r.motion_id,
                player_id=r.player_id,
                pending_action_type=r.pending_action_type,
                resolved=r.resolved,
                negated_motion_id=r.negated_motion_id,
                resolution_order=r.resolution_order,
                applied_effects=effect_tags_by_motion.get(r.motion_id, ()),
            )
            for r in resolutions
        ]
        state.counter_resolutions.extend(enriched_resolutions)
        for r in enriched_resolutions:
            self._checkpoint(state, f"counter_motion_resolved_{r.motion_id}")
            source = next(
                (t for t in reversed(state.counter_motion_trace) if t.motion_id == r.motion_id and t.resolved is None),
                None,
            )
            if source is None:
                continue
            state.counter_motion_trace.append(
                CounterMotionTrace(
                    motion_id=source.motion_id,
                    turn_number=source.turn_number,
                    phase=source.phase,
                    window_kind=source.window_kind,
                    pending_action_type=source.pending_action_type,
                    player_id=source.player_id,
                    card_instance_id=source.card_instance_id,
                    modes=source.modes,
                    resolved=r.resolved,
                    negated_motion_id=r.negated_motion_id,
                    resolution_order=r.resolution_order,
                    applied_effects=r.applied_effects,
                )
            )
        root_negated = any(r.resolved and r.negated_motion_id is None for r in enriched_resolutions)
        state.counter_chain = []
        state.log.append(
            "Counter chain resolution complete: "
            + ", ".join(
                f"motion_id={r.motion_id} order={r.resolution_order} resolved={r.resolved} "
                f"pending_action_type={r.pending_action_type} negated_motion_id={r.negated_motion_id} "
                f"effects={','.join(r.applied_effects) or 'none'}"
                for r in enriched_resolutions
            )
        )
        self._checkpoint(state, "counter_chain_resolution_complete")
        if not root_negated:
            return False
        top_resolution = next((r for r in enriched_resolutions if r.resolved and r.negated_motion_id is None), None)
        if top_resolution is None:
            return False
        top_motion = motion_by_id.get(top_resolution.motion_id)
        if top_motion is None:
            return False
        return self._counter_motion_negates_pending_action(state, top_motion)

    def _counter_motion_negates_pending_action(self, state: GameState, motion: CounterMotion) -> bool:
        win = state.counter_window
        if win is None:
            return False
        player = state.players.get(motion.player_id)
        if player is None:
            return False
        card = next(
            (
                c
                for c in [
                    *player.drop,
                    *player.battle_area,
                    *player.unison_area,
                    *player.energy,
                    *player.hand,
                    player.leader_area,
                ]
                if c.instance_id == motion.card_instance_id
            ),
            None,
        )
        if card is None:
            return False
        pending = win.pending_action
        if pending.action_type == "attack":
            text = str(card.skill_text_raw or "").strip()
            if self._text_counter_negates_attack(card):
                return True
            if not text:
                return card.has_counter_attack or "Counter: Attack" in (card.counter_modes or ())
            return False
        if pending.action_type in {"play_from_hand", "play_from_drop", "play_from_warp", "play_from_z_energy", "play_from_energy", "play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle", "play_from_opponent_hand_to_opponent_battle"}:
            text = str(card.skill_text_raw or "").lower()
            if "negate the play" not in text:
                return False
            leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=player.leader_area,
                leader_runtime=leader_runtime,
            ):
                return False
            return True
        if pending.action_type in {"activate_main", "activate_battle", "activate_extra_from_hand"}:
            text = str(card.skill_text_raw or "").lower()
            return "negate the skill" in text or "counter the skill" in text
        return False

    def _apply_resolved_counter_motion_effects(
        self,
        state: GameState,
        motions: list[CounterMotion],
        resolutions: list[CounterResolution],
    ) -> dict[int, Tuple[str, ...]]:
        motion_by_id = {motion.motion_id: motion for motion in motions}
        effect_tags_by_motion: dict[int, Tuple[str, ...]] = {}
        for resolution in resolutions:
            if not resolution.resolved or resolution.negated_motion_id is not None:
                continue
            motion = motion_by_id.get(resolution.motion_id)
            if motion is None:
                continue
            player = state.players[motion.player_id]
            card = next((c for c in player.drop if c.instance_id == motion.card_instance_id), None)
            if card is None:
                continue
            if resolution.pending_action_type == "attack":
                payload: dict[str, int | str | None] = {
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "drop",
                    "pending_action_type": resolution.pending_action_type,
                    **dict(motion.payload),
                }
                if state.attack_context is not None:
                    payload.update(
                        {
                            "attacker_player_id": state.attack_context.attacker_player_id,
                            "attacker_zone": state.attack_context.attacker_zone,
                            "attacker_instance_id": state.attack_context.attacker_instance_id,
                        }
                    )
                self._emit_effect_event(
                    state,
                    name="counter_attack",
                    actor_player_id=motion.player_id,
                    payload=payload,
                )
            elif resolution.pending_action_type in {"play_from_hand", "play_from_drop", "play_from_warp", "play_from_z_energy", "play_from_energy", "play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle", "play_from_opponent_hand_to_opponent_battle"}:
                payload = {
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "drop",
                    "pending_action_type": resolution.pending_action_type,
                    **dict(motion.payload),
                }
                pending_preview = self._pending_play_preview_card(state, state.counter_window.pending_action) if state.counter_window is not None else None
                if pending_preview is not None:
                    payload.update(
                        {
                            "pending_source_instance_id": pending_preview.instance_id,
                            "pending_source_card_id": pending_preview.card_id,
                            "pending_source_power": int(pending_preview.power or 0),
                            "pending_source_energy_cost": int(pending_preview.energy_cost or 0),
                            "pending_source_card_type": str(pending_preview.card_type or ""),
                        }
                    )
                self._emit_effect_event(
                    state,
                    name="counter_play",
                    actor_player_id=motion.player_id,
                    payload=payload,
                )
            handled = False
            effect_tags: list[str] = []
            if self._apply_counter_force_pending_play_rest_family(state, card):
                handled = True
                effect_tags.append("force_pending_play_rest")
            if self._apply_counter_place_pending_play_to_warp_if_cost_at_most_family(state, player, card):
                handled = True
                effect_tags.append("pending_play_to_warp")
            if self._apply_counter_spirit_boost_power_reduce_family(state, player, card):
                handled = True
                effect_tags.append("spirit_boost_power_reduce")
            if self._apply_counter_power_reduce_opponent_battle_family(state, player, card):
                handled = True
                effect_tags.append("power_reduce")
            if self._apply_counter_ko_opponent_battle_total_cost_family(state, player, card):
                handled = True
                effect_tags.append("ko_total_cost")
            if self._apply_counter_negate_attacker_skills_and_prevent_switch_active_family(state, player, card):
                handled = True
                effect_tags.append("negate_attacker_skills_prevent_switch_active")
            if self._apply_counter_reduce_attacker_and_attack_power_tax_family(state, player, card):
                handled = True
                effect_tags.append("attacker_reduce_attack_tax")
            if self._apply_counter_copy_hand_restriction_for_turn_family(state, player, card):
                handled = True
                effect_tags.append("copy_counter_restriction")
            if self._apply_counter_other_mode_hand_restriction_for_turn_family(state, player, card):
                handled = True
                effect_tags.append("other_counter_mode_restriction")
            if self._apply_counter_permanent_copy_hand_restriction_family(state, player, card):
                handled = True
                effect_tags.append("permanent_copy_counter_restriction")
            if (
                self._text_describes_counter_play_self(card)
                and not any(
                    self._has_registered_effect_handler(
                        state,
                        owner_player_id=player.player_id,
                        source_instance_id=card.instance_id,
                        trigger=trigger,
                        handler_id=handler_id,
                    )
                    for trigger, handler_id in (
                        ("counter_attack", "counter_play_self_rest_then_ko_attacking_battle_if_trait_and_opponent_draw_n"),
                        ("counter_attack", "counter_negate_attack_play_self_attack_restriction"),
                        ("counter_attack", "counter_play_self_from_counter_counter"),
                        ("counter_play", "counter_play_self_then_return_pending_to_owner_hand_if_cost_at_most"),
                    )
                )
            ):
                effect_tags.extend(self._resolve_counter_play_self_family(state, player, card, motion.payload))
                handled = True
            if self._apply_counter_hidden_then_reveal_family(state, player, card):
                handled = True
                effect_tags.append("hidden_then_reveal")
            if self._apply_counter_switch_owner_energy_hidden_then_draw_family(state, player, card):
                handled = True
                effect_tags.append("switch_owner_energy_hidden_then_draw")
            if self._apply_counter_discard_then_switch_owner_card_hidden_family(state, player, card):
                handled = True
                effect_tags.append("discard_then_switch_owner_card_hidden")
            if self._apply_counter_attack_restriction_family(state, card):
                handled = True
                effect_tags.append("attack_restriction")
            if not handled and str(card.skill_text_raw or "").strip():
                state.log.append(
                    f"Unsupported counter effect: source_card_id={card.card_id} modes={','.join(card.counter_modes or ()) or 'unknown'}"
                )
                self._checkpoint(state, "counter_effect_no_registered_family")
                effect_tags.append("unsupported")
            if effect_tags:
                effect_tags_by_motion[motion.motion_id] = tuple(effect_tags)
                state.log.append(
                    "Counter motion effects applied: "
                    f"motion_id={motion.motion_id} effects={','.join(effect_tags)}"
                )
        return effect_tags_by_motion

    def _pending_play_preview_card(self, state: GameState, pending: PendingAction) -> CardInstance | None:
        actor = state.players.get(pending.actor_player_id)
        if actor is None:
            return None
        if pending.action_type == "play_from_hand":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.hand if c.instance_id == target_id), None)
        if pending.action_type == "play_from_drop":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.drop if c.instance_id == target_id), None)
        if pending.action_type == "play_from_warp":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.warp if c.instance_id == target_id), None)
        if pending.action_type == "play_from_z_energy":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.z_energy if c.instance_id == target_id), None)
        if pending.action_type == "play_from_energy":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.energy if c.instance_id == target_id), None)
        if pending.action_type in {"play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle"}:
            source_index = pending.payload.get("source_index")
            source_card_id = int(pending.payload.get("source_card_id") or -1)
            if source_index is None or source_card_id <= 0:
                return None
            leader_under = tuple(actor.leader_area.stacked_card_ids or ())
            if not (0 <= int(source_index) < len(leader_under)):
                return None
            if int(leader_under[int(source_index)]) != source_card_id:
                return None
            return self._create_card_instance(
                next_instance_id=-(pending.actor_player_id * 100000 + int(source_index) + 1),
                card_id=source_card_id,
                owner_id=pending.actor_player_id,
            )
        if pending.action_type == "play_from_opponent_hand_to_opponent_battle":
            target_id = int(pending.payload.get("card_instance_id") or -1)
            if target_id <= 0:
                return None
            return next((c for c in actor.hand if c.instance_id == target_id), None)
        return None

    def _apply_counter_force_pending_play_rest_family(self, state: GameState, card: CardInstance) -> bool:
        if not self._text_counter_forces_pending_play_rest(card):
            return False
        win = state.counter_window
        if win is None:
            return False
        pending = win.pending_action
        if pending.action_type not in {"play_from_hand", "play_from_drop", "play_from_warp", "play_from_z_energy", "play_from_energy", "play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle", "play_from_opponent_hand_to_opponent_battle"}:
            return False
        target = self._pending_play_preview_card(state, pending)
        if target is None or target.card_type not in {"BATTLE", "Z-BATTLE"}:
            return False
        pending.payload["resting"] = True
        self._checkpoint(state, "counter_effect_force_pending_play_rest_applied")
        return True

    def _text_counter_places_pending_play_to_warp_if_cost_at_most(self, card: CardInstance) -> int | None:
        text = str(card.skill_text_raw or "").lower()
        m = re.search(
            r"battle card being played has an energy cost of (\d+) or less,\s*it is sent to its owner'?s warp instead of being played",
            text,
        )
        if m is None:
            return None
        try:
            return int(m.group(1))
        except ValueError:
            return None

    def _apply_counter_place_pending_play_to_warp_if_cost_at_most_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
    ) -> bool:
        max_cost = self._text_counter_places_pending_play_to_warp_if_cost_at_most(card)
        if max_cost is None:
            return False
        leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
        if not self._text_hand_cost_reduction_requirements_met(
            card.skill_text_raw,
            state=state,
            owner=player,
            leader=player.leader_area,
            leader_runtime=leader_runtime,
        ):
            return False
        win = state.counter_window
        if win is None:
            return False
        pending = win.pending_action
        if pending.action_type not in {"play_from_hand", "play_from_drop", "play_from_warp", "play_from_z_energy", "play_from_energy", "play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle", "play_from_opponent_hand_to_opponent_battle"}:
            return False
        target = self._pending_play_preview_card(state, pending)
        if target is None or target.card_type not in {"BATTLE", "Z-BATTLE"}:
            return False
        if int(target.energy_cost or 0) > max_cost:
            return False
        pending.payload["force_warp_instead_of_play"] = True
        self._checkpoint(state, "counter_effect_pending_play_to_warp_scheduled")
        return True

    def _apply_counter_spirit_boost_power_reduce_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_spirit_boost_reduces_opponent_cards(card):
            return False
        primary_targets = self._select_opponent_cards(
            state,
            owner_player_id=player.player_id,
            max_targets=1,
            policy="first",
            prefer_attacker=True,
        )
        if primary_targets:
            self._apply_temporary_power_delta(
                state,
                card=primary_targets[0],
                delta=-5000,
                reason="counter_effect_spirit_boost_power_reduce",
            )
        removed_markers = 0
        red_unisons = [
            unison
            for unison in player.unison_area
            if int(getattr(unison, "markers", 0) or 0) > 0
            and "red" in {part.strip().lower() for part in str(unison.color or "").replace("/", ",").split(",") if part.strip()}
        ]
        if red_unisons:
            chosen_unison = red_unisons[0]
            self._remove_unison_markers(state, unison=chosen_unison, amount=1, reason="spirit_boost")
            removed_markers = 1
        if removed_markers > 0:
            bonus_targets = self._select_opponent_cards(
                state,
                owner_player_id=player.player_id,
                max_targets=1,
                policy="first",
                prefer_attacker=True,
            )
            if bonus_targets:
                self._apply_temporary_power_delta(
                    state,
                    card=bonus_targets[0],
                    delta=-5000 * removed_markers,
                    reason="counter_effect_spirit_boost_bonus_power_reduce",
                )
            self._checkpoint(state, "counter_effect_spirit_boost_bonus_resolved")
        self._run_confirmative_rule_processing(state)
        self._checkpoint(state, "counter_effect_spirit_boost_power_reduce_resolved")
        return True

    def _apply_counter_power_reduce_opponent_battle_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        parsed = self._parse_counter_power_reduce_opponent_battle_for_turn(card)
        if parsed is None:
            return False
        max_targets, power_delta = parsed
        if max_targets <= 0 or power_delta == 0:
            return False
        opponent = state.players.get(self._opponent_of(player.player_id))
        if opponent is None or not opponent.battle_area:
            return False
        selected = list(opponent.battle_area[:max_targets])
        if not selected:
            return False
        for target in selected:
            self._apply_temporary_power_delta(
                state,
                card=target,
                delta=power_delta,
                reason="counter_effect_power_reduce",
            )
        self._checkpoint(state, "counter_effect_power_reduce_resolved")
        return True

    def _apply_counter_ko_opponent_battle_total_cost_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        total_cost_budget = self._parse_counter_ko_opponent_battle_total_cost(card)
        if total_cost_budget is None:
            return False
        selected = self._select_opponent_battle_targets_up_to_total_cost(
            state,
            owner_player_id=player.player_id,
            total_cost_budget=total_cost_budget,
            prefer_attacker=True,
        )
        if selected:
            opponent = state.players.get(self._opponent_of(player.player_id))
            if opponent is not None:
                target_ids = {target.instance_id for target in selected}
                i = 0
                while i < len(opponent.battle_area):
                    battle = opponent.battle_area[i]
                    if battle.instance_id not in target_ids:
                        i += 1
                        continue
                    opponent.drop.append(opponent.battle_area.pop(i))
                self._run_confirmative_rule_processing(state)
        if self._text_counter_optional_discard_limits_opponent_attacks(card):
            discard_idx = next(
                (
                    i
                    for i, hand_card in enumerate(player.hand)
                    if "green" in {part.strip().lower() for part in str(hand_card.color or "").replace("/", ",").split(",") if part.strip()}
                ),
                -1,
            )
            if discard_idx >= 0:
                player.drop.append(player.hand.pop(discard_idx))
                opponent_id = self._opponent_of(player.player_id)
                current_remaining = int(state.remaining_attack_declarations.get(opponent_id, 1))
                state.remaining_attack_declarations[opponent_id] = min(current_remaining, 1)
                self._checkpoint(state, "counter_effect_attack_limit_applied")
        self._checkpoint(state, "counter_effect_ko_total_cost_resolved")
        return True

    def _apply_counter_negate_attacker_skills_and_prevent_switch_active_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_negates_attacker_skills_and_prevents_switch_active(card):
            return False
        ctx = state.attack_context
        if ctx is None:
            return False
        opponent = state.players.get(self._opponent_of(player.player_id))
        if opponent is None:
            return False
        attacker = self._find_by_instance(opponent, ctx.attacker_zone, ctx.attacker_instance_id)
        if attacker is None:
            return False
        if self._opponent_skill_can_negate_battle_card_skills(state, acting_player_id=player.player_id, target_card=attacker):
            attacker.temporary_skills_negated = True
            self._checkpoint(state, "counter_effect_attacker_skills_negated")
        else:
            self._checkpoint(state, "counter_effect_attacker_skill_negation_prevented")
        attacker.temporary_cannot_switch_active = True
        self._checkpoint(state, "counter_effect_attacker_cannot_switch_active")
        return True

    def _apply_counter_reduce_attacker_and_attack_power_tax_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
    ) -> bool:
        if not self._text_counter_reduces_attacker_and_applies_attack_power_tax(card):
            return False
        ctx = state.attack_context
        if ctx is None:
            return True
        opponent = state.players.get(self._opponent_of(player.player_id))
        if opponent is None:
            return True
        attacker = self._find_by_instance(opponent, ctx.attacker_zone, ctx.attacker_instance_id)
        if attacker is None:
            return True
        self._apply_temporary_power_delta(
            state,
            card=attacker,
            delta=-10000,
            reason="counter_effect_attacker_power_reduce",
        )
        self._checkpoint(state, "counter_effect_attacker_power_reduce_applied")
        state.attack_power_taxes.append(
            AttackPowerTax(
                owner_player_id=player.player_id,
                affected_player_id=self._opponent_of(player.player_id),
                power_delta=-5000,
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        self._checkpoint(state, "counter_effect_attack_power_tax_applied")
        state.active_counter_hand_restrictions.append(
            CounterHandActivationRestriction(
                owner_player_id=player.player_id,
                restricted_card_id=int(card.card_id),
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        self._checkpoint(state, "counter_effect_hand_counter_restriction_applied")
        return True

    def _apply_counter_permanent_copy_hand_restriction_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
    ) -> bool:
        if not self._text_counter_restricts_copies_for_game(card):
            return False
        if not self._add_permanent_skill_activation_restriction(
            state,
            owner_player_id=player.player_id,
            restricted_card_id=int(card.card_id),
            scope="counter_from_hand",
        ):
            return False
        state.log.append(
            "Counter copies permanently restricted for the game: "
            f"player_id={player.player_id} card_id={card.card_id}"
        )
        self._checkpoint(state, "counter_effect_permanent_copy_counter_restriction_applied")
        return True

    def _apply_counter_copy_hand_restriction_for_turn_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
    ) -> bool:
        if not self._text_counter_restricts_copies_for_turn(card):
            return False
        restricted_card_id = int(card.card_id)
        exists = any(
            int(row.owner_player_id) == int(player.player_id)
            and int(getattr(row, "restricted_card_id", 0) or 0) == restricted_card_id
            and not str(getattr(row, "restricted_mode", "") or "").strip()
            and int(getattr(row, "expires_on_turn_end_player_id", 0)) == int(state.active_player)
            for row in state.active_counter_hand_restrictions
        )
        if exists:
            return False
        state.active_counter_hand_restrictions.append(
            CounterHandActivationRestriction(
                owner_player_id=player.player_id,
                restricted_card_id=restricted_card_id,
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        state.log.append(
            "Counter copies restricted for the turn: "
            f"player_id={player.player_id} card_id={card.card_id}"
        )
        self._checkpoint(state, "counter_effect_copy_counter_restriction_applied")
        return True

    def _apply_counter_other_mode_hand_restriction_for_turn_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
    ) -> bool:
        restricted_mode = self._parse_counter_restricted_other_counter_mode_for_turn(card)
        if not restricted_mode:
            return False
        exists = any(
            int(row.owner_player_id) == int(player.player_id)
            and str(getattr(row, "restricted_mode", "") or "") == restricted_mode
            and int(getattr(row, "expires_on_turn_end_player_id", 0)) == int(state.active_player)
            for row in state.active_counter_hand_restrictions
        )
        if exists:
            return False
        state.active_counter_hand_restrictions.append(
            CounterHandActivationRestriction(
                owner_player_id=player.player_id,
                restricted_mode=restricted_mode,
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        state.log.append(
            "Counter mode restricted for the turn: "
            f"player_id={player.player_id} mode={restricted_mode}"
        )
        self._checkpoint(state, "counter_effect_other_counter_mode_restriction_applied")
        return True

    def _has_registered_effect_handler(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        source_instance_id: int,
        trigger: str,
        handler_id: str | None = None,
    ) -> bool:
        return any(
            int(reg.owner_player_id) == int(owner_player_id)
            and int(reg.source_instance_id) == int(source_instance_id)
            and str(reg.trigger) == str(trigger)
            and (handler_id is None or str(reg.handler_id) == handler_id)
            for reg in state.effect_registry
        )

    def _resolve_counter_play_self_family(
        self,
        state: GameState,
        player: PlayerState,
        card: CardInstance,
        payload: dict[str, int | str | None],
    ) -> Tuple[str, ...]:
        effect_tags = ["play_self"]
        card.resting = self._text_requires_play_self_in_rest(card)
        if card in player.drop:
            player.drop.remove(card)
        player.battle_area.append(card)
        self._register_card_effects(state, player_id=player.player_id, source_zone="battle", card=card)
        self._emit_effect_event(
            state,
            name="counter_played_from_drop",
            actor_player_id=player.player_id,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": "battle",
            },
        )
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=player.player_id,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": "battle",
                "played_from": "hand",
                "played_via": "counter",
            },
        )
        if self._text_counter_switches_self_to_hidden(card):
            card.hidden_mode = True
            effect_tags.append("switch_self_hidden")
            self._emit_effect_event(
                state,
                name="card_switched_hidden_mode",
                actor_player_id=player.player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "owner_player_id": player.player_id,
                },
            )
            self._checkpoint(state, "counter_effect_switch_self_hidden_resolved")
        target_instance_id = int(payload.get("cost_target_instance_id") or -1)
        if target_instance_id > 0 and self._text_reveals_hidden_cost_target_at_turn_end(card):
            effect_tags.append("delayed_reveal")
            self._schedule_delayed_mode_switch(
                state,
                owner_player_id=player.player_id,
                target_instance_id=target_instance_id,
                trigger_kind="turn_end",
                trigger_player_id=state.active_player,
                switch_to_hidden=False,
            )
            self._checkpoint(state, "counter_effect_delayed_reveal_scheduled")
        if self._apply_counter_redirect_to_self_family(state, player, card):
            effect_tags.append("redirect_to_self")
            self._checkpoint(state, "counter_effect_redirect_to_self_resolved")
        if self._apply_counter_switch_owner_battle_hidden_at_battle_end_family(state, player, card):
            effect_tags.append("delayed_hidden_battle_end")
            self._checkpoint(state, "counter_effect_delayed_hidden_battle_end_scheduled")
        pending_drop_threshold = self._parse_counter_play_self_pending_power_drop_threshold(card)
        if pending_drop_threshold is not None:
            win = state.counter_window
            pending_action = win.pending_action if win is not None else None
            if pending_action is not None and pending_action.action_type in {"play_from_hand", "play_from_drop", "play_from_z_energy", "play_from_energy", "play_from_leader_under", "play_from_battle_under", "play_from_leader_under_to_opponent_battle", "play_from_opponent_hand_to_opponent_battle"}:
                target = self._pending_play_preview_card(state, pending_action)
                if target is not None and target.card_type in {"BATTLE", "Z-BATTLE"} and int(target.power) <= pending_drop_threshold:
                    pending_action.payload["force_drop_instead_of_play"] = 1
                    effect_tags.append("pending_play_to_drop")
                    self._checkpoint(state, "counter_effect_pending_play_to_drop_scheduled")
        battle_buff = self._parse_counter_play_self_buff_owner_cards_for_battle(card)
        if battle_buff is not None:
            max_targets, delta = battle_buff
            owner_cards = [player.leader_area] + list(player.battle_area) + list(player.unison_area)
            if max_targets > 0 and delta != 0 and owner_cards:
                indexes = self._choose_effect_target_indexes(
                    state,
                    EffectRegistration(
                        effect_id=0,
                        owner_player_id=player.player_id,
                        source_instance_id=card.instance_id,
                        source_card_id=card.card_id,
                        source_zone="battle",
                        trigger="counter_attack",
                        handler_id="counter_play_self_buff_owner_cards_for_battle",
                        handler_params={},
                    ),
                    owner_cards,
                    max_targets,
                    "first",
                )
                for idx in indexes:
                    self._apply_battle_temporary_power_delta(
                        state,
                        card=owner_cards[idx],
                        delta=delta,
                        reason="counter_effect_play_self_battle_buff",
                    )
                if indexes:
                    effect_tags.append("battle_buff")
                    self._checkpoint(state, "counter_effect_play_self_battle_buff_resolved")
        draw_n = self._parse_counter_play_self_draw_n(card)
        if draw_n > 0:
            for _ in range(min(draw_n, len(player.deck))):
                self._draw_one_from_card_skill(state, player_id=player.player_id, card=card, source_zone="drop")
            effect_tags.append("draw")
            self._checkpoint(state, "counter_effect_play_self_draw_resolved")
        self._checkpoint(state, "counter_effect_play_self_resolved")
        return tuple(effect_tags)

    def _apply_counter_redirect_to_self_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_redirects_attack_to_self(card):
            return False
        ctx = state.attack_context
        if ctx is None:
            return True
        state.attack_context = AttackContext(
            attacker_player_id=ctx.attacker_player_id,
            attacker_zone=ctx.attacker_zone,
            attacker_instance_id=ctx.attacker_instance_id,
            target_player_id=player.player_id,
            target_zone="battle",
            target_instance_id=card.instance_id,
        )
        if state.battle_step == BattleStep.DEFENSE:
            state.battle_step = BattleStep.OFFENSE
        return True

    def _apply_counter_switch_owner_battle_hidden_at_battle_end_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_switches_owner_battle_to_hidden_at_battle_end(card):
            return False
        candidates: list[CardInstance] = []
        if (
            card in player.battle_area
            and not card.hidden_mode
            and "white" in {part.strip().lower() for part in str(card.color or "").replace("/", ",").split(",") if part.strip()}
        ):
            candidates.append(card)
        candidates.extend(
            target
            for target in player.battle_area
            if target.instance_id != card.instance_id
            and not target.hidden_mode
            and "white" in {part.strip().lower() for part in str(target.color or "").replace("/", ",").split(",") if part.strip()}
        )
        if not candidates:
            return True
        target = candidates[0]
        self._schedule_delayed_mode_switch(
            state,
            owner_player_id=player.player_id,
            target_instance_id=target.instance_id,
            trigger_kind="battle_end",
            trigger_player_id=player.player_id,
            switch_to_hidden=True,
        )
        return True

    def _apply_counter_attack_restriction_family(self, state: GameState, card: CardInstance) -> bool:
        ctx = state.attack_context
        if ctx is None:
            return False
        if self._text_restricts_leader_attacker(card) and ctx.attacker_zone == "leader":
            state.attack_restricted_instance_ids.add(ctx.attacker_instance_id)
            self._checkpoint(state, "counter_effect_attack_restriction_applied")
            return True
        if self._text_restricts_battle_attacker(card) and ctx.attacker_zone == "battle":
            state.attack_restricted_instance_ids.add(ctx.attacker_instance_id)
            self._checkpoint(state, "counter_effect_attack_restriction_applied")
            return True
        return False

    def _apply_counter_hidden_then_reveal_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_switches_opponent_battle_to_hidden_then_reveal(card):
            return False
        opponent_id = self._opponent_of(player.player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return False
        max_targets = self._owner_hidden_mode_count(player)
        if max_targets <= 0:
            return True
        candidates = [target for target in opponent.battle_area if not target.hidden_mode]
        if not candidates:
            return True
        indexes = list(range(min(max_targets, len(candidates))))
        if not indexes:
            return True
        for idx in indexes:
            target = candidates[idx]
            target.hidden_mode = True
            self._emit_effect_event(
                state,
                name="card_switched_hidden_mode",
                actor_player_id=player.player_id,
                payload={
                    "source_instance_id": target.instance_id,
                    "source_card_id": target.card_id,
                    "source_zone": "battle",
                    "owner_player_id": opponent_id,
                },
            )
            self._schedule_delayed_mode_switch(
                state,
                owner_player_id=opponent_id,
                target_instance_id=target.instance_id,
                trigger_kind="turn_end",
                trigger_player_id=state.active_player,
                switch_to_hidden=False,
            )
        self._checkpoint(state, "counter_effect_hidden_then_reveal_scheduled")
        return True

    def _apply_counter_switch_owner_energy_hidden_then_draw_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_switches_owner_energy_to_hidden_then_draw(card):
            return False
        target = next(
            (
                energy
                for energy in player.energy
                if not energy.hidden_mode and "white" in {part.strip().lower() for part in str(energy.color or "").replace("/", ",").split(",") if part.strip()}
            ),
            None,
        )
        if target is None:
            return True
        target.hidden_mode = True
        self._draw_one_from_card_skill(state, player_id=player.player_id, card=card, source_zone="drop")
        self._checkpoint(state, "counter_effect_switch_owner_energy_hidden_then_draw")
        return True

    def _apply_counter_discard_then_switch_owner_card_hidden_family(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        if not self._text_counter_discards_then_switches_owner_card_to_hidden(card):
            return False
        if not player.hand:
            return True
        player.drop.append(player.hand.pop(0))
        candidates = [
            target
            for target in [*player.battle_area, *player.unison_area, *player.energy]
            if not target.hidden_mode
            and "white" in {part.strip().lower() for part in str(target.color or "").replace("/", ",").split(",") if part.strip()}
        ]
        if not candidates:
            return True
        candidates[0].hidden_mode = True
        self._checkpoint(state, "counter_effect_discard_then_switch_owner_card_hidden")
        return True

    def _resolve_play_from_hand(self, state: GameState, pending: PendingAction, *, negated: bool) -> None:
        player = state.players[pending.actor_player_id]
        opponent = state.players[self._opponent_of(pending.actor_player_id)]
        target_id = int(pending.payload.get("card_instance_id") or -1)
        idx = next((i for i, c in enumerate(player.hand) if c.instance_id == target_id), None)
        if idx is None:
            return
        card = player.hand.pop(idx)
        card.resting = bool(pending.payload.get("resting") or False)
        delayed_keyword = str(pending.payload.get("grant_keyword_after_play") or "").strip()
        power_after_play = int(pending.payload.get("grant_power_after_play") or 0)
        keyword_clear_trigger_player_id = int(pending.payload.get("keyword_clear_trigger_player_id") or -1)
        opponent_discards_after_play = int(pending.payload.get("opponent_discards_after_play") or 0)
        post_play_rest_max_targets = int(pending.payload.get("post_play_rest_max_targets") or 0)
        post_play_revealed_max_targets = int(pending.payload.get("post_play_revealed_max_targets") or 0)
        post_play_place_under_self_max_targets = int(pending.payload.get("post_play_place_under_self_max_targets") or 0)
        post_play_place_owner_battle_under_self_max_targets = int(
            pending.payload.get("post_play_place_owner_battle_under_self_max_targets") or 0
        )
        post_play_token_amount = int(pending.payload.get("post_play_token_amount") or 0)
        post_play_drop_opponent_rest_battle_unison = bool(pending.payload.get("post_play_drop_opponent_rest_battle_unison") or False)
        post_play_drop_opponent_rest_ignores_barrier = bool(
            pending.payload.get("post_play_drop_opponent_rest_ignores_barrier") or False
        )
        played_via = str(pending.payload.get("played_via") or "").strip().lower()
        if negated:
            player.drop.append(card)
            self._checkpoint(state, "play_negated")
            return
        if bool(pending.payload.get("force_drop_instead_of_play")):
            player.drop.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=pending.actor_player_id, card=card, source_zone="hand")
            self._checkpoint(state, "play_replaced_to_drop")
            return
        if bool(pending.payload.get("force_warp_instead_of_play")):
            self._append_to_owner_warp(state, owner_player_id=pending.actor_player_id, card=card, source_zone="hand")
            self._checkpoint(state, "play_replaced_to_warp")
            return
        if bool(pending.payload.get("force_hand_instead_of_play")):
            player.hand.append(card)
            self._checkpoint(state, "play_replaced_to_hand")
            return
        if bool(pending.payload.get("force_bottom_deck_instead_of_play")):
            player.deck.append(card.card_id)
            self._checkpoint(state, "play_replaced_to_bottom_deck")
            return
        if card.card_type in {"BATTLE", "Z-BATTLE"}:
            player.battle_area.append(card)
            if delayed_keyword:
                self._append_temporary_keyword(card, delayed_keyword, duration="delayed")
                if keyword_clear_trigger_player_id > 0:
                    state.delayed_keyword_clears.append(
                        DelayedKeywordClear(
                            owner_player_id=pending.actor_player_id,
                            target_instance_id=card.instance_id,
                            trigger_player_id=keyword_clear_trigger_player_id,
                            keyword=delayed_keyword,
                        )
                    )
            if power_after_play:
                self._apply_temporary_power_delta(state, card=card, delta=power_after_play, reason="pending_play_power_after_play")
            self._register_card_effects(state, player_id=pending.actor_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=pending.actor_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "hand",
                    "played_via": played_via or None,
                },
            )
            for _ in range(min(opponent_discards_after_play, len(opponent.hand))):
                discarded = opponent.hand.pop(0)
                opponent.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=discarded, source_zone="hand")
            if post_play_rest_max_targets > 0:
                candidates = [
                    target for target in opponent.battle_area if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=pending.actor_player_id, target_card=target)
                ]
                for target in candidates[:post_play_rest_max_targets]:
                    target.resting = True
            revealed_instance_ids: set[int] = set()
            if post_play_revealed_max_targets > 0:
                reveal_candidates = [target for target in opponent.battle_area if target.hidden_mode]
                for target in reveal_candidates[:post_play_revealed_max_targets]:
                    target.hidden_mode = False
                    revealed_instance_ids.add(target.instance_id)
                    self._emit_effect_event(
                        state,
                        name="card_switched_revealed_mode",
                        actor_player_id=pending.actor_player_id,
                        payload={
                            "source_instance_id": target.instance_id,
                            "source_card_id": target.card_id,
                            "source_zone": "battle",
                            "owner_player_id": opponent.player_id,
                        },
                    )
            if post_play_place_under_self_max_targets > 0:
                kept: list[CardInstance] = []
                moved = 0
                for target in list(opponent.battle_area):
                    if moved >= post_play_place_under_self_max_targets:
                        kept.append(target)
                        continue
                    if target.instance_id in revealed_instance_ids:
                        kept.append(target)
                        continue
                    if target.hidden_mode or self._card_currently_has_barrier(target):
                        kept.append(target)
                        continue
                    self._place_card_under_host(card, target)
                    moved += 1
                opponent.battle_area = [target for target in opponent.battle_area if target in kept]
            if post_play_place_owner_battle_under_self_max_targets > 0:
                allowed_colors = {
                    part.strip().lower()
                    for part in str(pending.payload.get("post_play_place_owner_battle_under_self_allowed_colors", ""))
                    .replace("|", ",")
                    .replace("/", ",")
                    .split(",")
                    if part.strip()
                }
                required_traits = {
                    part.strip().lower()
                    for part in str(pending.payload.get("post_play_place_owner_battle_under_self_required_traits", ""))
                    .replace("|", ",")
                    .split(",")
                    if part.strip()
                }
                required_characters = {
                    part.strip().lower()
                    for part in str(pending.payload.get("post_play_place_owner_battle_under_self_required_characters", ""))
                    .replace("|", ",")
                    .split(",")
                    if part.strip()
                }
                required_name_contains = str(
                    pending.payload.get("post_play_place_owner_battle_under_self_required_name_contains", "")
                ).strip().upper()
                candidates = [
                    target
                    for target in player.battle_area
                    if int(target.instance_id) != int(card.instance_id)
                    and self._card_matches_effect_filters(
                        target,
                        allowed_colors=allowed_colors,
                        required_traits=required_traits,
                        required_characters=required_characters,
                        required_name_contains=required_name_contains,
                        required_card_types={"BATTLE", "Z-BATTLE"},
                    )
                ]
                indexes = self._choose_effect_target_indexes(
                    state,
                    EffectRegistration(
                        effect_id=0,
                        owner_player_id=pending.actor_player_id,
                        source_instance_id=card.instance_id,
                        source_card_id=card.card_id,
                        source_zone="battle",
                        trigger="self_activate_main",
                        handler_id="activate_play_self_from_hand",
                        handler_params={"target_policy": str(pending.payload.get("post_play_place_owner_battle_under_self_target_policy") or "first")},
                    ),
                    candidates,
                    post_play_place_owner_battle_under_self_max_targets,
                    str(pending.payload.get("post_play_place_owner_battle_under_self_target_policy") or "first"),
                ) if candidates else []
                if indexes:
                    target_ids = {candidates[idx].instance_id for idx in indexes}
                    kept_owner_battles: list[CardInstance] = []
                    for target in list(player.battle_area):
                        if target.instance_id not in target_ids:
                            kept_owner_battles.append(target)
                            continue
                        self._place_card_under_host(card, target)
                        self._emit_card_placed_under_card(
                            state,
                            owner_player_id=pending.actor_player_id,
                            host=card,
                            host_zone="battle",
                            card=target,
                            source_zone="battle",
                        )
                    player.battle_area = kept_owner_battles
                    self._register_battle_under_card_effects(state, player_id=pending.actor_player_id)
            if post_play_token_amount > 0:
                raw_token_keywords = str(pending.payload.get("post_play_token_temporary_keywords", "") or "")
                token_keywords = self._parse_keyword_list(raw_token_keywords)
                clear_player_id = self._token_keyword_clear_trigger_player_id(
                    state,
                    owner_player_id=pending.actor_player_id,
                    duration=str(pending.payload.get("post_play_token_keyword_duration", "turn") or "turn"),
                )
                for _ in range(max(post_play_token_amount, 0)):
                    self._play_token_to_battle_area(
                        state,
                        owner_player_id=pending.actor_player_id,
                        controller_player_id=pending.actor_player_id,
                        token_name=str(pending.payload.get("post_play_token_name") or "Token"),
                        power=int(pending.payload.get("post_play_token_power") or 0),
                        combo_cost=int(pending.payload.get("post_play_token_combo_cost") or 0),
                        combo_power=int(pending.payload.get("post_play_token_combo_power") or 0),
                        resting=bool(pending.payload.get("post_play_token_resting") or False),
                        temporary_keywords=token_keywords,
                        clear_temporary_keywords_on_player_id=clear_player_id,
                        created_by_source_instance_id=int(pending.payload.get("source_instance_id") or -1),
                        created_by_source_card_id=int(pending.payload.get("source_card_id") or 0),
                        created_by_source_zone=str(pending.payload.get("source_zone") or ""),
                        created_by_source_card_type=str(card.card_type or self._resolve_card_runtime_data(card.card_id).card_type or ""),
                    )
            if post_play_drop_opponent_rest_battle_unison:
                kept_battle: list[CardInstance] = []
                for target in list(opponent.battle_area):
                    if not target.resting:
                        kept_battle.append(target)
                        continue
                    if not post_play_drop_opponent_rest_ignores_barrier and self._card_currently_has_barrier(target):
                        kept_battle.append(target)
                        continue
                    opponent.drop.append(target)
                    self._emit_card_placed_into_drop(
                        state, owner_player_id=opponent.player_id, card=target, source_zone="battle"
                    )
                opponent.battle_area = kept_battle
                kept_unison: list[CardInstance] = []
                for target in list(opponent.unison_area):
                    if not target.resting:
                        kept_unison.append(target)
                        continue
                    if not post_play_drop_opponent_rest_ignores_barrier and self._card_currently_has_barrier(target):
                        kept_unison.append(target)
                        continue
                    opponent.drop.append(target)
                    self._emit_card_placed_into_drop(
                        state, owner_player_id=opponent.player_id, card=target, source_zone="unison"
                    )
                opponent.unison_area = kept_unison
            self._checkpoint(state, "main_play_battle")
            return
        if card.card_type in {"UNISON", "Z-UNISON"}:
            marker_override = pending.payload.get("marker_count")
            paid_energy = int(pending.payload.get("paid_energy_cards") or 0)
            card.markers = max(int(marker_override) if marker_override is not None else paid_energy, 0)
            self._replace_owner_unison_if_needed(state, player)
            player.unison_area.append(card)
            self._register_card_effects(state, player_id=pending.actor_player_id, source_zone="unison", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=pending.actor_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "unison",
                    "played_from": "hand",
                    "played_via": played_via or None,
                },
            )
            self._checkpoint(state, "main_play_unison")
            return
        player.drop.append(card)
        self._checkpoint(state, "main_play_extra")

