    def _record_secret_auto_opportunities(self, state: GameState, event: EffectEvent) -> None:
        created = False
        preblocked = False
        regs_by_id = self._effect_registrations_for_limit_counting(state)
        events_by_id = {evt.event_id: evt for evt in state.effect_events}
        resolved_once_per_turn_counts = self._current_effect_once_per_turn_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        resolved_limit_counts = self._current_effect_limit_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        for row in state.deferred_secret_autos:
            if not self._effect_trigger_matches_event(
                row.trigger,
                source_instance_id=row.source_instance_id,
                owner_player_id=row.owner_player_id,
                event=event,
            ):
                continue
            exists = any(
                opp.secret_auto_id == row.secret_auto_id and opp.event_id == event.event_id
                for opp in state.secret_auto_opportunities
            )
            if exists:
                continue
            temp_reg = EffectRegistration(
                effect_id=-int(row.secret_auto_id),
                owner_player_id=row.owner_player_id,
                source_instance_id=row.source_instance_id,
                source_card_id=row.source_card_id,
                source_zone=row.source_zone,
                trigger=row.trigger,
                handler_id=row.handler_id,
                handler_params=dict(row.handler_params),
                source_skill_text=row.source_skill_text,
                source_card_number=row.source_card_number,
                once_per_turn=row.once_per_turn,
                limit_per_turn=row.limit_per_turn,
                limit_scope=row.limit_scope,
            )
            status = "pending"
            if self._is_registration_temporarily_activation_restricted(state, temp_reg):
                status = "blocked_temporary_restriction"
            elif self._is_registration_permanently_activation_restricted(state, temp_reg):
                status = "blocked_permanent_restriction"
            elif not self._event_specific_requirements_met(state, event, temp_reg):
                status = "blocked_requirements"
            else:
                once_key = self._effect_once_per_turn_key(temp_reg)
                if once_key is not None and resolved_once_per_turn_counts.get(once_key, 0) >= 1:
                    status = "blocked_once_per_turn"
                else:
                    limit_key = self._effect_limit_key(temp_reg)
                    if limit_key is not None and resolved_limit_counts.get(limit_key, 0) >= int(temp_reg.limit_per_turn or 0):
                        status = "blocked_limit_per_turn"
            state.secret_auto_opportunities.append(
                SecretAutoOpportunity(
                    opportunity_id=state.next_secret_auto_opportunity_id,
                    secret_auto_id=row.secret_auto_id,
                    owner_player_id=row.owner_player_id,
                    source_instance_id=row.source_instance_id,
                    source_card_id=row.source_card_id,
                    source_card_number=row.source_card_number,
                    source_zone=row.source_zone,
                    trigger=row.trigger,
                    handler_id=row.handler_id,
                    source_skill_text=row.source_skill_text,
                    event_id=event.event_id,
                    event_name=event.name,
                    created_turn_number=state.turn_number,
                    created_phase=state.phase,
                    origin_zone=str(row.origin_zone or row.source_zone),
                    handler_params=dict(row.handler_params),
                    once_per_turn=row.once_per_turn,
                    limit_per_turn=row.limit_per_turn,
                    limit_scope=row.limit_scope,
                    status=status,
                    preblocked=(status != "pending"),
                )
            )
            state.next_secret_auto_opportunity_id += 1
            if status == "pending":
                state.log.append(
                    "Secret-area auto opportunity created: "
                    f"source_instance_id={row.source_instance_id} event_id={event.event_id} trigger={row.trigger}"
                )
            else:
                preblocked = True
                state.log.append(
                    "Secret-area auto opportunity preblocked: "
                    f"source_instance_id={row.source_instance_id} event_id={event.event_id} trigger={row.trigger} status={status}"
                )
            created = True
        if created:
            self._checkpoint(state, "secret_auto_opportunity_created")
        if preblocked:
            self._checkpoint(state, "secret_auto_opportunity_preblocked")

    def _apply_active_low_power_battle_play_hand_warp_penalties(self, state: GameState, event: EffectEvent) -> None:
        if event.name != "card_played":
            return
        played_player_id = event.actor_player_id
        if played_player_id is None:
            return
        if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
            return
        penalties = [
            row
            for row in state.low_power_battle_play_hand_warp_penalties
            if int(row.affected_player_id) == int(played_player_id)
        ]
        if not penalties:
            return
        player = state.players.get(played_player_id)
        if player is None:
            return
        source_instance_id = int(event.payload.get("source_instance_id") or -1)
        if source_instance_id <= 0:
            return
        played_card = next((card for card in player.battle_area if int(card.instance_id) == source_instance_id), None)
        if played_card is None:
            return
        applied = False
        for row in penalties:
            if int(getattr(played_card, "power", 0) or 0) > int(row.max_power):
                continue
            moved = 0
            while moved < int(row.hand_to_warp) and player.hand:
                card = player.hand.pop(0)
                self._append_to_owner_warp(state, owner_player_id=played_player_id, card=card, source_zone="hand")
                moved += 1
            if moved > 0:
                applied = True
        if applied:
            self._checkpoint(state, "low_power_battle_play_hand_warp_penalty_applied")

    def _reset_once_per_turn_effect_counters(self, state: GameState, *, player_id: int) -> None:
        updated: list[EffectRegistration] = []
        for reg in state.effect_registry:
            if reg.owner_player_id == player_id and reg.triggers_this_turn != 0:
                updated.append(
                    EffectRegistration(
                        effect_id=reg.effect_id,
                        owner_player_id=reg.owner_player_id,
                        source_instance_id=reg.source_instance_id,
                        source_card_id=reg.source_card_id,
                        source_zone=reg.source_zone,
                        trigger=reg.trigger,
                        handler_id=reg.handler_id,
                        handler_params=dict(reg.handler_params),
                        source_card_number=reg.source_card_number,
                        once_per_turn=reg.once_per_turn,
                        limit_per_turn=reg.limit_per_turn,
                        limit_scope=reg.limit_scope,
                        triggers_this_turn=0,
                    )
                )
            else:
                updated.append(reg)
        state.effect_registry = updated

    @staticmethod
    def _resolve_effect_limit_per_turn(handler_params: dict[str, int | str | bool]) -> int | None:
        raw = handler_params.get("limit_per_turn")
        return int(raw) if isinstance(raw, int) and raw > 0 else None

    @staticmethod
    def _effect_once_per_turn_key(reg: EffectRegistration) -> tuple[object, ...] | None:
        if not reg.once_per_turn:
            return None
        return (
            reg.owner_player_id,
            reg.source_instance_id,
            reg.trigger,
            reg.handler_id,
            tuple(sorted(reg.handler_params.items())),
        )

    def _current_effect_once_per_turn_counts(
        self,
        state: GameState,
        *,
        regs_by_id: dict[int, EffectRegistration],
        events_by_id: dict[int, EffectEvent],
    ) -> dict[tuple[object, ...], int]:
        counts: dict[tuple[object, ...], int] = {}
        for row in state.effect_resolutions:
            if not row.resolved:
                continue
            reg = regs_by_id.get(row.effect_id)
            evt = events_by_id.get(row.event_id)
            if reg is None or evt is None or evt.turn_number != state.turn_number:
                continue
            key = self._effect_once_per_turn_key(reg)
            if key is None:
                continue
            counts[key] = counts.get(key, 0) + 1
        return counts

    @staticmethod
    def _effect_limit_source_group(reg: EffectRegistration) -> str:
        scope = str(reg.limit_scope or "card_number").strip() or "card_number"
        if scope == "source_instance":
            return f"instance:{reg.source_instance_id}"
        if scope == "card_id":
            return f"card_id:{reg.source_card_id}"
        return str(reg.source_card_number or f"card_id:{reg.source_card_id}")

    @staticmethod
    def _effect_limit_key(reg: EffectRegistration) -> tuple[object, ...] | None:
        if reg.limit_per_turn is None or reg.limit_per_turn <= 0:
            return None
        scope = str(reg.limit_scope or "card_number").strip() or "card_number"
        source_group = RulesEngine._effect_limit_source_group(reg)
        return (
            reg.owner_player_id,
            scope,
            source_group,
            reg.trigger,
            reg.handler_id,
            tuple(sorted(reg.handler_params.items())),
        )

    def _current_effect_limit_counts(
        self,
        state: GameState,
        *,
        regs_by_id: dict[int, EffectRegistration],
        events_by_id: dict[int, EffectEvent],
    ) -> dict[tuple[object, ...], int]:
        counts: dict[tuple[object, ...], int] = {}
        for row in state.effect_resolutions:
            if not row.resolved:
                continue
            reg = regs_by_id.get(row.effect_id)
            evt = events_by_id.get(row.event_id)
            if reg is None or evt is None or evt.turn_number != state.turn_number:
                continue
            key = self._effect_limit_key(reg)
            if key is None:
                continue
            counts[key] = counts.get(key, 0) + 1
        return counts

    def _effect_registrations_for_limit_counting(self, state: GameState) -> dict[int, EffectRegistration]:
        regs_by_id = {reg.effect_id: reg for reg in state.effect_registry}
        for opportunity in state.secret_auto_opportunities:
            if opportunity.status != "declared":
                continue
            effect_id = -int(opportunity.secret_auto_id)
            regs_by_id[effect_id] = EffectRegistration(
                effect_id=effect_id,
                owner_player_id=opportunity.owner_player_id,
                source_instance_id=opportunity.source_instance_id,
                source_card_id=opportunity.source_card_id,
                source_zone=opportunity.source_zone,
                trigger=opportunity.trigger,
                handler_id=opportunity.handler_id,
                handler_params=dict(opportunity.handler_params),
                source_card_number=opportunity.source_card_number,
                once_per_turn=opportunity.once_per_turn,
                limit_per_turn=opportunity.limit_per_turn,
                limit_scope=opportunity.limit_scope,
            )
        return regs_by_id

    def _pop_next_pending_effect(self, state: GameState) -> PendingEffect | None:
        if not state.pending_effects:
            return None
        regs_by_id = {reg.effect_id: reg for reg in state.effect_registry}
        owner_order = [state.active_player, self._opponent_of(state.active_player)]
        for owner_id in owner_order:
            matching: list[tuple[int, PendingEffect]] = []
            for idx, entry in enumerate(state.pending_effects):
                reg = regs_by_id.get(entry.effect_id)
                if reg is not None and reg.owner_player_id == owner_id:
                    matching.append((idx, entry))
            if matching:
                selected_idx = min(matching, key=lambda item: (int(item[1].event_id), int(item[1].effect_id), int(item[0])))[0]
                return state.pending_effects.pop(selected_idx)
        return state.pending_effects.pop(0)

    def _resolve_pending_effects(self, state: GameState) -> None:
        if not state.pending_effects:
            return
        regs_by_id = self._effect_registrations_for_limit_counting(state)
        events_by_id = {evt.event_id: evt for evt in state.effect_events}
        resolved_once_per_turn_counts = self._current_effect_once_per_turn_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        resolved_limit_counts = self._current_effect_limit_counts(state, regs_by_id=regs_by_id, events_by_id=events_by_id)
        while state.pending_effects:
            entry = self._pop_next_pending_effect(state)
            if entry is None:
                break
            regs_by_id = self._effect_registrations_for_limit_counting(state)
            events_by_id = {evt.event_id: evt for evt in state.effect_events}
            reg = regs_by_id.get(entry.effect_id)
            evt = events_by_id.get(entry.event_id)
            if reg is None or evt is None:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=entry.effect_id, event_id=entry.event_id, resolved=False, reason="missing_context")
                )
                continue
            once_key = self._effect_once_per_turn_key(reg)
            if once_key is not None and resolved_once_per_turn_counts.get(once_key, 0) >= 1:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="once_per_turn_used")
                )
                state.log.append(
                    "Public effect blocked by once-per-turn: "
                    f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                    f"trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_once_per_turn_blocked")
                continue
            limit_key = self._effect_limit_key(reg)
            if limit_key is not None and resolved_limit_counts.get(limit_key, 0) >= int(reg.limit_per_turn or 0):
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="limit_per_turn_used")
                )
                state.log.append(
                    "Public effect blocked by limit: "
                    f"effect_id={reg.effect_id} source_instance_id={reg.source_instance_id} "
                    f"limit_scope={reg.limit_scope} limit_per_turn={reg.limit_per_turn} "
                    f"trigger={reg.trigger} handler={reg.handler_id}"
                )
                self._checkpoint(state, "effect_limit_per_turn_blocked")
                continue
            if not self._is_effect_source_active(state, reg):
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="source_missing")
                )
                continue
            handler = self._effect_handlers.get(reg.handler_id)
            if handler is None:
                state.effect_resolutions.append(
                    EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=False, reason="missing_handler")
                )
                continue
            handler(state, evt, reg)
            self._apply_post_resolution_registration_effects(state, evt, reg)
            next_reg = EffectRegistration(
                effect_id=reg.effect_id,
                owner_player_id=reg.owner_player_id,
                source_instance_id=reg.source_instance_id,
                source_card_id=reg.source_card_id,
                source_zone=reg.source_zone,
                trigger=reg.trigger,
                handler_id=reg.handler_id,
                handler_params=dict(reg.handler_params),
                source_card_number=reg.source_card_number,
                once_per_turn=reg.once_per_turn,
                limit_per_turn=reg.limit_per_turn,
                limit_scope=reg.limit_scope,
                triggers_this_turn=reg.triggers_this_turn + 1,
            )
            state.effect_registry = [next_reg if item.effect_id == reg.effect_id else item for item in state.effect_registry]
            if once_key is not None:
                resolved_once_per_turn_counts[once_key] = resolved_once_per_turn_counts.get(once_key, 0) + 1
            if limit_key is not None:
                resolved_limit_counts[limit_key] = resolved_limit_counts.get(limit_key, 0) + 1
            state.effect_resolutions.append(
                EffectResolution(effect_id=reg.effect_id, event_id=evt.event_id, resolved=True, reason="ok")
            )

    @staticmethod
    def _evaluate_continuous_effects(_state: GameState) -> None:
        # Phase 4.1: continuous/permanent effects will be evaluated here without entering pending status.
        return

    @staticmethod
    def _handle_noop_effect(state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        state.log.append(
            f"Effect resolved: effect_id={reg.effect_id} source={reg.source_instance_id} trigger={reg.trigger} event={event.name}"
        )

    def _handle_auto_draw_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_on_play")

    def _handle_auto_draw_on_attack(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_on_attack")

    def _handle_auto_draw_n(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name not in {"card_played", "attack_declared", "card_comboed", "skill_activated", "turn_start", "turn_end", "main_phase_start", "aegis_activated", "leader_wished", "leader_z_awakened", "union_activated", "card_added_to_z_energy", "card_added_to_energy", "card_placed_under_card", "card_placed_into_drop", "card_placed_in_leader_area", "card_switched_to_active", "card_switched_to_rest", "card_koed", "battle_end"}:
            return
        if reg.trigger == "owner_opponent_card_switched_to_rest":
            if event.name != "card_switched_to_rest":
                return
            if event.actor_player_id != reg.owner_player_id:
                return
            if not bool(event.payload.get("by_skill", False)):
                return
            switched_row = self._find_card_anywhere_by_instance(
                state,
                owner_player_id=self._opponent_of(reg.owner_player_id),
                instance_id=int(event.payload.get("source_instance_id") or -1),
            )
            if switched_row is None:
                return
            _, switched = switched_row
        if not self._effect_requirements_met(state, reg):
            return
        if reg.trigger == "self_attacks":
            if event.name != "attack_declared" or int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
                return
            if not self._pay_self_attack_auto_cost_if_needed(state, event, reg):
                return
        if reg.trigger == "self_comboed":
            if event.name != "card_comboed" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            required_comboed_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
            if required_comboed_from:
                comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
                if comboed_from != required_comboed_from:
                    return
            if not self._pay_self_combo_skill_cost_if_needed(state, event, reg):
                return
        if reg.trigger == "self_in_hand_sent_to_drop_or_warp":
            if event.name not in {"card_placed_into_drop", "card_sent_to_warp"}:
                return
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if str(event.payload.get("source_zone") or "").strip().lower() != "hand":
                return
            required_destination_zone = str(reg.handler_params.get("required_destination_zone", "")).strip().lower()
            if required_destination_zone == "drop" and event.name != "card_placed_into_drop":
                return
            if required_destination_zone == "warp" and event.name != "card_sent_to_warp":
                return
            required_drop_causes = {
                part.strip().lower()
                for part in str(reg.handler_params.get("required_drop_causes", "")).replace("|", ",").split(",")
                if part.strip()
            }
            if required_drop_causes and str(event.payload.get("drop_cause") or "").strip().lower() not in required_drop_causes:
                return
        if reg.trigger == "self_placed_under_owner_card":
            if event.name != "card_placed_under_card" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if int(event.payload.get("host_owner_player_id") or -1) != reg.owner_player_id:
                return
        if reg.trigger == "self_placed_into_drop":
            if event.name != "card_placed_into_drop" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            required_from = {
                part.strip().lower()
                for part in str(reg.handler_params.get("requires_placed_from_zones", "")).replace("|", ",").split(",")
                if part.strip()
            }
            placed_from = str(event.payload.get("source_zone") or "").strip().lower()
            if required_from and placed_from not in required_from:
                return
            required_drop_causes = {
                part.strip().lower()
                for part in str(reg.handler_params.get("required_drop_causes", "")).replace("|", ",").split(",")
                if part.strip()
            }
            drop_cause = str(event.payload.get("drop_cause") or "").strip().lower()
            if required_drop_causes and drop_cause not in required_drop_causes:
                return
            if not self._pay_self_drop_skill_cost_if_needed(state, event, reg):
                return
        if reg.trigger == "self_added_to_energy":
            if event.name != "card_added_to_energy" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            required_from = {
                part.strip().lower()
                for part in str(reg.handler_params.get("requires_added_from_zones", "")).replace("|", ",").split(",")
                if part.strip()
            }
            added_from = str(event.payload.get("added_from") or "").strip().lower()
            if required_from and added_from not in required_from:
                return
        if reg.trigger == "self_koed":
            if event.name != "card_koed" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            required_ko_cause = str(reg.handler_params.get("required_ko_cause", "") or "").strip().lower()
            if required_ko_cause:
                ko_cause = str(event.payload.get("ko_cause") or event.payload.get("drop_cause") or "").strip().lower()
                if ko_cause != required_ko_cause:
                    return
        if reg.trigger == "owner_card_comboed":
            owner_combo_match = self._match_owner_combo_event(state, event, reg)
            if owner_combo_match is None:
                return
            owner, _live_combo_card, _combo_probe = owner_combo_match
            if not self._pay_owner_combo_skill_cost_if_needed(state, event, reg, owner):
                return
        if event.name == "main_phase_start":
            if not self._can_pay_main_phase_auto_costs(state, reg):
                return
            if not self._pay_main_phase_auto_costs(state, reg):
                return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        if amount <= 0:
            return
        for _ in range(amount):
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_n")

    def _handle_auto_draw_n_on_owner_battle_switched_to_rest_by_skill(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_switched_to_rest":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if not bool(event.payload.get("by_skill", True)):
            return
        if state.active_player != reg.owner_player_id:
            return
        switched_instance_id = int(event.payload.get("source_instance_id") or -1)
        switched_card: CardInstance | None = None
        for player in state.players.values():
            switched_card = self._find_by_instance(player, str(event.payload.get("source_zone") or "").strip().lower(), switched_instance_id)
            if switched_card is not None:
                break
        if switched_card is None or str(switched_card.card_type or "").upper() != "BATTLE":
            return
        if not self._effect_requirements_met(state, reg):
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(0, amount)):
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_n_on_owner_battle_switched_to_rest_by_skill")

    def _handle_auto_draw_n_on_owner_bardocks_crew_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if not self._effect_requirements_met(state, reg):
            return
        if bool(reg.handler_params.get("requires_owner_turn", False)) and state.active_player != reg.owner_player_id:
            return
        match = self._match_owner_battle_played_event(state, event, reg)
        if match is None:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(0, amount)):
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_draw_n_on_owner_bardocks_crew_played")

    def _handle_auto_play_yellow_bardocks_crew_from_hand_rest_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        for idx, card in enumerate(owner.hand):
            colors = {
                part.strip().lower()
                for part in str(card.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            if colors != {"yellow"}:
                continue
            if int(card.energy_cost or -1) != 1:
                continue
            if not self._card_matches_effect_filters(
                card,
                allowed_colors={"yellow"},
                required_traits={"bardock's crew"},
                required_characters=set(),
                required_name_contains="",
                required_card_types={"BATTLE"},
            ):
                continue
            played = owner.hand.pop(idx)
            played.resting = True
            owner.battle_area.append(played)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=played)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": played.instance_id,
                    "source_card_id": played.card_id,
                    "source_zone": "battle",
                    "played_from": "hand",
                    "played_via": "effect",
                },
            )
            self._emit_card_switched_to_rest(
                state,
                actor_player_id=reg.owner_player_id,
                card=played,
                source_zone="battle",
                by_skill=True,
            )
            self._checkpoint(state, "effect_auto_play_yellow_bardocks_crew_from_hand_rest_on_play")
            return

    def _handle_auto_discard_n_from_owner_hand_then_apply_non_leader_attack_rest_tax_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        discard_amount = self._resolve_effect_int_param(state, reg, "discard_amount", default=1)
        if discard_amount < 0 or len(owner.hand) < discard_amount:
            return
        for _ in range(discard_amount):
            discarded = owner.hand.pop(0)
            owner.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=discarded, source_zone="hand")
        state.non_leader_attack_rest_taxes.append(
            NonLeaderAttackRestTax(
                owner_player_id=reg.owner_player_id,
                affected_player_id=self._opponent_of(reg.owner_player_id),
                rest_count=self._resolve_effect_int_param(state, reg, "rest_count", default=1),
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        self._checkpoint(state, "effect_auto_discard_n_from_owner_hand_then_apply_non_leader_attack_rest_tax_on_play")

    def _handle_auto_mark_self_played_turn_number(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, str(reg.source_zone or "").strip().lower(), reg.source_instance_id)
        if source is None:
            return
        setattr(source, "_played_turn_number", int(state.turn_number))
        self._checkpoint(state, "effect_auto_mark_self_played_turn_number")

    def _handle_auto_draw_n_switch_up_to_n_owner_leader_and_energy_active_and_grant_owner_leader_keyword_for_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "main_phase_start":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if not self._can_pay_main_phase_auto_costs(state, reg):
            return
        if not self._pay_main_phase_auto_costs(state, reg):
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_leader_targets = self._resolve_effect_int_param(state, reg, "max_leader_targets", default=1)
        if max_leader_targets > 0:
            owner.leader_area.resting = False
        max_energy_targets = self._resolve_effect_int_param(state, reg, "max_energy_targets", default=1)
        if max_energy_targets > 0:
            activated = 0
            for card in owner.energy:
                if activated >= max_energy_targets:
                    break
                if not card.resting:
                    continue
                card.resting = False
                activated += 1
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if grant_keyword:
            self._append_temporary_keyword(owner.leader_area, grant_keyword, duration="turn")
        self._checkpoint(state, "effect_auto_draw_n_switch_up_to_n_owner_leader_and_energy_active_and_grant_owner_leader_keyword_for_turn")

    def _handle_auto_switch_up_to_n_opponent_energy_rest_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        candidates = [card for card in opponent.energy if not card.resting]
        if not candidates:
            return
        policy = str(reg.handler_params.get("target_policy", "first"))
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].resting = True
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_energy_rest_on_aegis")

    def _handle_auto_draw_n_switch_self_active_and_switch_up_to_n_opponent_board_rest_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is not None and source.resting and self._can_switch_card_to_active(source):
            source.resting = False
        targets = self._select_opponent_battle_or_unison_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
            prefer_attacker=bool(reg.handler_params.get("prefer_attacker", False)),
        )
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_draw_n_switch_self_active_and_switch_up_to_n_opponent_board_rest_on_aegis")

    def _handle_auto_optional_discard_play_up_to_n_from_owner_drop_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.drop:
            return
        discard_before = self._resolve_effect_int_param(state, reg, "discard_from_hand_before", default=1)
        if discard_before > 0:
            if len(owner.hand) < discard_before:
                return
            for _ in range(discard_before):
                discarded = owner.hand.pop(0)
                owner.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=discarded, source_zone="hand")
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_card_types", reg.handler_params.get("required_card_type", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        requires_no_keywords = bool(reg.handler_params.get("requires_no_keywords", False))
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        negate_skills = bool(reg.handler_params.get("negate_skills", False))
        candidates: list[tuple[int, CardInstance]] = []
        for idx, card in enumerate(owner.drop):
            if max_cost >= 0 and (card.energy_cost is None or int(card.energy_cost) > max_cost):
                continue
            if required_card_types and str(card.card_type or "").upper() not in required_card_types:
                continue
            if requires_no_keywords and any(str(keyword).strip() for keyword in (card.keywords or ())):
                continue
            if not self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_card_types=required_card_types or None,
            ):
                continue
            candidates.append((idx, card))
        if not candidates:
            return
        chosen_indexes = self._choose_effect_target_indexes(
            state,
            reg,
            [card for _, card in candidates],
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not chosen_indexes:
            return
        removed = 0
        for chosen in chosen_indexes:
            source_idx, _ = candidates[chosen]
            card = owner.drop.pop(source_idx - removed)
            removed += 1
            card.resting = rest_mode
            if negate_skills:
                card.keywords = ()
                card.counter_modes = ()
                card.has_counter = False
                card.has_counter_attack = False
                card.has_counter_battle_card_attack = False
                card.has_counter_play = False
                card.has_counter_counter = False
                card.has_activate_main = False
                card.has_activate_battle = False
                card.has_auto = False
                card.has_permanent = False
                card.has_draw = False
                card.max_draw = None
                card.auto_once_per_turn = False
                card.auto_draw_on_play = False
                card.auto_draw_on_attack = False
                card.has_barrier = False
            target_zone = "battle"
            if "UNISON" in str(card.card_type or "").upper():
                target_zone = "unison"
                self._replace_owner_unison_if_needed(state, owner)
                owner.unison_area.append(card)
            else:
                owner.battle_area.append(card)
            if not negate_skills:
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone=target_zone, card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": target_zone,
                    "played_from": "drop",
                },
            )
        self._checkpoint(state, "effect_auto_optional_discard_play_up_to_n_from_owner_drop_on_aegis")

    def _handle_auto_place_top_n_from_opponent_deck_into_drop_on_aegis(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "owner_aegis_activated":
            if event.name != "aegis_activated" or event.actor_player_id != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None or not opponent.deck:
            return
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_no_other_owner_traits", reg.handler_params.get("required_traits", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_no_other_owner_characters", reg.handler_params.get("required_characters", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(
            reg.handler_params.get("required_no_other_owner_name_contains", reg.handler_params.get("required_name_contains", ""))
        ).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_no_other_owner_card_types", "BATTLE")).replace("|", ",").split(",")
            if part.strip()
        }
        if required_traits or required_characters or required_name_contains:
            for card in owner.battle_area:
                if card.instance_id == reg.source_instance_id:
                    continue
                if self._card_matches_effect_filters(
                    card,
                    allowed_colors=set(),
                    required_traits=required_traits,
                    required_characters=required_characters,
                    required_name_contains=required_name_contains,
                    required_card_types=required_card_types or None,
                ):
                    return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        removed = 0
        while removed < amount and opponent.deck:
            card_id = opponent.deck.pop(0)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=opponent.player_id)
            state.next_instance_id += 1
            opponent.drop.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=card, source_zone="deck")
            removed += 1
        if removed:
            self._checkpoint(state, "effect_auto_place_top_n_from_opponent_deck_into_drop_on_aegis")

    def _handle_auto_pay_life_on_attack_gain_power_and_keyword_for_turn(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        life_to_hand = self._resolve_effect_int_param(state, reg, "life_to_hand", default=1)
        if life_to_hand > 0:
            if len(owner.life) < life_to_hand:
                return
            for _ in range(life_to_hand):
                owner.hand.append(owner.life.pop(0))
        if bool(reg.handler_params.get("switch_self_active", False)) and source.resting and self._can_switch_card_to_active(source):
            source.resting = False
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta != 0:
            if str(reg.handler_params.get("power_duration", "")).strip().lower() == "battle":
                self._apply_battle_temporary_power_delta(state, card=source, delta=delta, reason="effect_self_attack_battle_buff")
            else:
                self._apply_temporary_power_delta(state, card=source, delta=delta, reason="effect_self_attack_buff")
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if grant_keyword and not self._card_has_keyword(source, grant_keyword):
            source.temporary_keywords = tuple(list(source.temporary_keywords) + [grant_keyword])
        self._checkpoint(state, "effect_auto_pay_life_on_attack_gain_power_and_keyword_for_turn")

    def _handle_auto_pay_life_look_top_play_up_to_n_named_rest_and_gain_power_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        life_to_hand = self._resolve_effect_int_param(state, reg, "life_to_hand", default=1)
        if life_to_hand > 0:
            if len(owner.life) < life_to_hand:
                return
            for _ in range(life_to_hand):
                owner.hand.append(owner.life.pop(0))

        look_count = self._resolve_effect_int_param(state, reg, "look_count", default=0)
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        played_any = False
        if look_count > 0 and max_targets > 0 and owner.deck:
            top_n = min(look_count, len(owner.deck))
            chosen_indexes: list[int] = []
            for i in range(top_n):
                deck_card = owner.deck[i]
                deck_card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
                runtime = self._resolve_card_runtime_data(deck_card_id)
                if required_name_contains and required_name_contains not in str(runtime.card_name or "").upper():
                    continue
                chosen_indexes.append(i)
                if len(chosen_indexes) >= max_targets:
                    break
            removed = 0
            for idx in chosen_indexes:
                deck_card = owner.deck.pop(idx - removed)
                removed += 1
                card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
                card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
                state.next_instance_id += 1
                card.resting = rest_mode
                owner.battle_area.append(card)
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
                self._emit_effect_event(
                    state,
                    name="card_played",
                    actor_player_id=reg.owner_player_id,
                    payload={
                        "source_instance_id": card.instance_id,
                        "source_card_id": card.card_id,
                        "source_zone": "battle",
                        "played_from": "deck",
                    },
                )
                played_any = True
            if bool(reg.handler_params.get("shuffle_deck_after", False)) and owner.deck:
                random.Random(0).shuffle(owner.deck)

        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta != 0:
            self._apply_temporary_power_delta(state, card=source, delta=delta, reason="effect_auto_pay_life_look_top_play_up_to_n_named_rest_and_gain_power_on_attack")
        if life_to_hand > 0 or played_any or delta != 0:
            self._checkpoint(state, "effect_auto_pay_life_look_top_play_up_to_n_named_rest_and_gain_power_on_attack")

    def _handle_auto_pay_life_look_top_play_up_to_n_matching_unison_with_marker_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        life_to_hand = self._resolve_effect_int_param(state, reg, "life_to_hand", default=1)
        if life_to_hand > 0:
            if len(owner.life) < life_to_hand:
                return
            for _ in range(life_to_hand):
                owner.hand.append(owner.life.pop(0))

        look_count = self._resolve_effect_int_param(state, reg, "look_count", default=0)
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        specified_cost_total = self._resolve_effect_int_param(state, reg, "specified_cost_total", default=-1)
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        marker_count = self._resolve_effect_int_param(state, reg, "markers", default=1)
        allowed_colors = {
            c.strip().lower()
            for c in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if c.strip()
        }
        required_card_type = str(reg.handler_params.get("required_card_type", "")).strip().upper()
        played_any = False
        if look_count > 0 and max_targets > 0 and owner.deck:
            top_n = min(look_count, len(owner.deck))
            chosen_indexes: list[int] = []
            for i in range(top_n):
                deck_card = owner.deck[i]
                deck_card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
                runtime = self._resolve_card_runtime_data(deck_card_id)
                if required_card_type and required_card_type not in str(runtime.card_type or "").upper():
                    continue
                runtime_colors = {
                    part.strip().lower()
                    for part in str(runtime.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
                if allowed_colors and runtime_colors.isdisjoint(allowed_colors):
                    continue
                specified_costs = dict(runtime.specified_costs or ())
                if specified_cost_total >= 0 and sum(int(v) for v in specified_costs.values()) != specified_cost_total:
                    continue
                chosen_indexes.append(i)
                if len(chosen_indexes) >= max_targets:
                    break
            removed = 0
            for idx in chosen_indexes:
                deck_card = owner.deck.pop(idx - removed)
                removed += 1
                card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
                card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
                state.next_instance_id += 1
                card.resting = rest_mode
                card.markers = max(marker_count, 0)
                self._replace_owner_unison_if_needed(state, owner)
                owner.unison_area.append(card)
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="unison", card=card)
                self._emit_effect_event(
                    state,
                    name="card_played",
                    actor_player_id=reg.owner_player_id,
                    payload={
                        "source_instance_id": card.instance_id,
                        "source_card_id": card.card_id,
                        "source_zone": "unison",
                        "played_from": "deck",
                    },
                )
                played_any = True
            if bool(reg.handler_params.get("shuffle_deck_after", False)) and owner.deck:
                random.Random(0).shuffle(owner.deck)
        if life_to_hand > 0 or played_any:
            self._checkpoint(state, "effect_auto_pay_life_look_top_play_up_to_n_matching_unison_with_marker_on_attack")

    def _handle_auto_discard_on_owner_activate_battle_red_extra_switch_self_active_and_optional_copy_bonus_debuff(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_battle":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return

        required_skill_source_zones = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_skill_source_zones", "")).replace("|", ",").split(",")
            if part.strip()
        }
        skill_source_zone = str(event.payload.get("source_zone") or "").strip().lower()
        if required_skill_source_zones and skill_source_zone not in required_skill_source_zones:
            return

        skill_card_id = int(event.payload.get("source_card_id") or -1)
        if skill_card_id <= 0:
            return
        runtime = self._resolve_card_runtime_data(skill_card_id)
        required_skill_card_type = str(reg.handler_params.get("required_skill_card_type", "")).strip().upper()
        if required_skill_card_type and required_skill_card_type not in str(runtime.card_type or "").upper():
            return
        required_skill_allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_skill_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        if required_skill_allowed_colors:
            runtime_colors = {
                part.strip().lower()
                for part in str(runtime.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            if runtime_colors and runtime_colors.isdisjoint(required_skill_allowed_colors):
                return
        required_skill_min_cost = self._resolve_effect_int_param(state, reg, "required_skill_min_cost", default=-1)
        if required_skill_min_cost >= 0:
            runtime_cost = int(runtime.energy_cost or 0)
            if runtime_cost < required_skill_min_cost:
                return

        discard_count = self._resolve_effect_int_param(state, reg, "discard_count", default=1)
        if discard_count <= 0:
            return
        if len(owner.hand) < discard_count:
            return
        discarded: list[CardInstance] = []
        for _ in range(discard_count):
            card = owner.hand.pop(0)
            owner.drop.append(card)
            discarded.append(card)
            self._emit_card_placed_into_drop(state, owner_player_id=owner.player_id, card=card, source_zone="hand")

        if self._can_switch_card_to_active(source):
            source.resting = False

        if any(int(card.card_id) == int(source.card_id) for card in discarded):
            bonus_draw = self._resolve_effect_int_param(state, reg, "bonus_draw", default=0)
            for _ in range(max(bonus_draw, 0)):
                self._draw_one_from_registration(state, reg)
            bonus_power_delta = self._resolve_effect_int_param(state, reg, "bonus_power_delta", default=0)
            if bonus_power_delta != 0:
                targets = self._select_opponent_battle_or_unison_targets(
                    state,
                    reg,
                    max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
                    max_cost=-1,
                    policy=str(reg.handler_params.get("target_policy", "first")),
                )
                for target in targets:
                    self._apply_temporary_power_delta(
                        state,
                        card=target,
                        delta=bonus_power_delta,
                        reason="effect_auto_discard_on_owner_activate_battle_red_extra_switch_self_active_and_optional_copy_bonus_debuff",
                    )
        self._checkpoint(state, "effect_auto_discard_on_owner_activate_battle_red_extra_switch_self_active_and_optional_copy_bonus_debuff")

    def _handle_auto_grant_attack_active_battle_without_barrier_for_turn_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.battle_area:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        candidates = [
            card
            for card in owner.battle_area
            if self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_skill_text_contains="",
                required_card_types={"BATTLE"},
            )
        ]
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            candidates,
            max_targets,
            str(reg.handler_params.get("target_policy", "first") or "first"),
        )
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].temporary_can_attack_active_battles_without_barrier = True
        self._checkpoint(state, "effect_auto_grant_attack_active_battle_without_barrier_for_turn_on_play")

    def _handle_auto_add_up_to_n_from_owner_hand_to_life_on_owner_leader_attack(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if str(event.payload.get("attacker_zone") or "") != "leader":
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.hand:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        if amount <= 0:
            return
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("/", ",").replace("|", ",").split(",") if c.strip()}
        chosen_indexes: list[int] = []
        for i, c in enumerate(owner.hand):
            if allowed_colors:
                colors = {p.strip().lower() for p in str(c.color or "").replace("/", ",").split(",") if p.strip()}
                if colors and colors.isdisjoint(allowed_colors):
                    continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= amount:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            owner.life.append(owner.hand.pop(idx - removed))
            removed += 1
        self._checkpoint(state, "effect_auto_add_up_to_n_from_owner_hand_to_life_on_owner_leader_attack")

