    def _handle_activate_negate_opponent_leader_skills_and_restrict_up_to_n_opponent_rest_cards_switch_active_until_opponent_turn_end(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return
        opponent.leader_area.temporary_skills_negated = True
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets > 0:
            candidates = [
                c for c in [*opponent.battle_area, *opponent.unison_area] if c.resting and self._can_switch_card_to_active(c)
            ]
            for target in candidates[:max_targets]:
                target.temporary_cannot_switch_active = True
        self._checkpoint(
            state,
            "effect_activate_negate_opponent_leader_skills_and_restrict_up_to_n_opponent_rest_cards_switch_active_until_opponent_turn_end",
        )

    def _handle_auto_place_all_opponent_battles_up_to_cost_under_self_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        kept: list[CardInstance] = []
        moved = 0
        for card in list(opponent.battle_area):
            if max_cost >= 0 and int(card.energy_cost or 0) > max_cost:
                kept.append(card)
                continue
            if self._card_currently_has_barrier(card):
                kept.append(card)
                continue
            self._place_card_under_host(source, card)
            moved += 1
        if moved <= 0:
            return
        opponent.battle_area = [card for card in opponent.battle_area if card in kept]
        self._checkpoint(state, "effect_auto_place_all_opponent_battles_up_to_cost_under_self_on_play")

    def _handle_auto_place_up_to_n_opponent_battle_under_owner_leader_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        if max_targets <= 0:
            return
        kept: list[CardInstance] = []
        moved = 0
        for card in list(opponent.battle_area):
            if moved >= max_targets:
                kept.append(card)
                continue
            if max_cost >= 0 and int(card.energy_cost or 0) > max_cost:
                kept.append(card)
                continue
            if card.hidden_mode or self._card_currently_has_barrier(card):
                kept.append(card)
                continue
            self._place_card_under_host(owner.leader_area, card)
            moved += 1
        if moved <= 0:
            return
        opponent.battle_area = [card for card in opponent.battle_area if card in kept]
        self._checkpoint(state, "effect_auto_place_up_to_n_opponent_battle_under_owner_leader_on_play")

    def _handle_auto_add_up_to_n_dragon_ball_from_owner_deck_or_drop_to_hand_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        required_label = str(reg.handler_params.get("required_runtime_labels", "dragon ball") or "dragon ball")
        added = 0
        idx = 0
        while idx < len(owner.drop) and added < max_targets:
            card = owner.drop[idx]
            if not self._card_has_runtime_label(card, required_label):
                idx += 1
                continue
            owner.hand.append(owner.drop.pop(idx))
            added += 1
        deck_looked = False
        idx = 0
        while idx < len(owner.deck) and added < max_targets:
            raw = owner.deck[idx]
            card_id = raw.card_id if isinstance(raw, CardInstance) else int(raw)
            temp = self._create_card_instance(next_instance_id=-(idx + 1), card_id=card_id, owner_id=reg.owner_player_id)
            if not self._card_has_runtime_label(temp, required_label):
                idx += 1
                continue
            owner.deck.pop(idx)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            owner.hand.append(card)
            deck_looked = True
            added += 1
        if added <= 0:
            return
        if deck_looked and bool(reg.handler_params.get("shuffle_deck_after", False)):
            self._checkpoint(state, "deck_shuffle_after_search")
        self._checkpoint(state, "effect_auto_add_up_to_n_dragon_ball_from_owner_deck_or_drop_to_hand_on_play")

    def _handle_auto_choose_bottom_deck_opponent_battles_or_gain_keywords_on_play_without_skills(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if str(event.payload.get("played_via") or "").strip():
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return

        second_branch_min_owner_energy = self._resolve_effect_int_param(state, reg, "second_branch_min_owner_energy", default=-1)
        if second_branch_min_owner_energy >= 0 and len(owner.energy) >= second_branch_min_owner_energy:
            while opponent.battle_area:
                opponent.deck.append(opponent.battle_area.pop(0).card_id)
            for keyword in [part.strip() for part in str(reg.handler_params.get("second_branch_grant_keywords", "")).split(",") if part.strip()]:
                self._append_temporary_keyword(source, keyword, duration="turn")
            self._checkpoint(state, "effect_auto_choose_bottom_deck_opponent_battles_or_gain_keywords_on_play_without_skills")
            return

        first_branch_min_cost = self._resolve_effect_int_param(state, reg, "first_branch_min_cost", default=-1)
        idx = 0
        while idx < len(opponent.battle_area):
            card = opponent.battle_area[idx]
            if first_branch_min_cost >= 0 and int(card.energy_cost or -1) < first_branch_min_cost:
                idx += 1
                continue
            opponent.deck.append(opponent.battle_area.pop(idx).card_id)
        if self._leader_requirement_string_met(state, owner_player_id=reg.owner_player_id, raw_req=None):
            leader = owner.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            leader_colors = {
                part.strip().lower()
                for part in str(leader.color or leader_runtime.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            bonus_leader_allowed_colors = {
                part.strip().lower()
                for part in str(reg.handler_params.get("bonus_leader_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                if part.strip()
            }
            bonus_leader_required_characters = {
                part.strip().lower()
                for part in str(reg.handler_params.get("bonus_leader_required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            }
            leader_traits = {
                part.strip().lower()
                for part in [*tuple(leader_runtime.traits or ()), *tuple(getattr(leader, "traits", ()) or ())]
                if part.strip()
            }
            leader_characters = {
                part.strip().lower()
                for part in [*tuple(leader_runtime.characters or ()), *tuple(getattr(leader, "characters", ()) or ())]
                if part.strip()
            }
            if (
                (not bonus_leader_allowed_colors or not leader_colors.isdisjoint(bonus_leader_allowed_colors))
                and (not bonus_leader_required_characters or not (leader_traits | leader_characters).isdisjoint(bonus_leader_required_characters))
                and owner.deck
            ):
                card_id = int(owner.deck.pop(0))
                card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
                state.next_instance_id += 1
                self._place_card_under_host(owner.leader_area, card)
                self._emit_card_placed_under_card(
                    state,
                    owner_player_id=reg.owner_player_id,
                    host=owner.leader_area,
                    host_zone="leader",
                    card=card,
                    source_zone="deck",
                )
        self._checkpoint(state, "effect_auto_choose_bottom_deck_opponent_battles_or_gain_keywords_on_play_without_skills")

    def _handle_auto_place_all_opponent_battle_and_unison_under_self_and_add_top_deck_to_life_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        host_zone = "unison" if any(card.instance_id == source.instance_id for card in owner.unison_area) else "battle"
        ignores_barrier = bool(reg.handler_params.get("ignores_barrier", False))
        moved = 0

        kept_battle: list[CardInstance] = []
        for card in list(opponent.battle_area):
            if not ignores_barrier and self._card_currently_has_barrier(card):
                kept_battle.append(card)
                continue
            self._place_card_under_host(source, card)
            self._emit_card_placed_under_card(
                state,
                owner_player_id=reg.owner_player_id,
                host=source,
                host_zone=host_zone,
                card=card,
                source_zone="battle",
            )
            moved += 1
        opponent.battle_area = kept_battle

        kept_unison: list[CardInstance] = []
        for card in list(opponent.unison_area):
            if not ignores_barrier and self._card_currently_has_barrier(card):
                kept_unison.append(card)
                continue
            self._place_card_under_host(source, card)
            self._emit_card_placed_under_card(
                state,
                owner_player_id=reg.owner_player_id,
                host=source,
                host_zone=host_zone,
                card=card,
                source_zone="unison",
            )
            moved += 1
        opponent.unison_area = kept_unison

        cards_per_life = self._resolve_effect_int_param(state, reg, "cards_per_life", default=0)
        max_life_cards = self._resolve_effect_int_param(state, reg, "max_life_cards", default=0)
        if moved > 0 and cards_per_life > 0:
            life_to_add = moved // cards_per_life
            if max_life_cards > 0:
                life_to_add = min(life_to_add, max_life_cards)
            for _ in range(min(life_to_add, len(owner.deck))):
                deck_card = owner.deck.pop(0)
                if isinstance(deck_card, CardInstance):
                    owner.life.append(deck_card)
                    continue
                owner.life.append(
                    self._create_card_instance(
                        next_instance_id=state.next_instance_id,
                        card_id=int(deck_card),
                        owner_id=reg.owner_player_id,
                    )
                )
                state.next_instance_id += 1

        if moved <= 0:
            return
        self._checkpoint(state, "effect_auto_place_all_opponent_battle_and_unison_under_self_and_add_top_deck_to_life_on_play")

    def _handle_auto_restrict_self_copies_from_hand_next_turn_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        restricted_card_id = int(reg.handler_params.get("restricted_card_id") or reg.source_card_id or -1)
        if restricted_card_id <= 0:
            return
        state.scheduled_card_play_restrictions.append(
            DelayedCardPlayRestriction(
                owner_player_id=reg.owner_player_id,
                restricted_card_id=restricted_card_id,
            )
        )
        self._checkpoint(state, "effect_auto_restrict_self_copies_from_hand_next_turn_on_play")

    def _handle_auto_restrict_self_copies_and_bottom_deck_green_unison_then_opponent_discard_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        restricted_card_id = int(reg.handler_params.get("restricted_card_id") or -1)
        if restricted_card_id <= 0:
            restricted_card_id = int(reg.source_card_id or -1)
        if restricted_card_id > 0:
            state.active_card_play_restrictions.append(
                DelayedCardPlayRestriction(
                    owner_player_id=reg.owner_player_id,
                    restricted_card_id=restricted_card_id,
                )
            )
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            if restricted_card_id > 0:
                self._checkpoint(state, "effect_auto_restrict_self_copies_and_bottom_deck_green_unison_then_opponent_discard_on_play")
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=3)
        selected_idx = next(
            (
                idx for idx, card in enumerate(owner.drop)
                if "UNISON" in str(getattr(card, "card_type", "") or "").upper()
                and "green" in {part.strip().lower() for part in str(getattr(card, "color", "") or "").replace("/", ",").split(",") if part.strip()}
                and int(getattr(card, "energy_cost", -1) or -1) <= max_cost
                and sum(int(v) for v in dict(getattr(card, "specified_costs", ()) or ()).values()) <= max_cost
            ),
            -1,
        )
        if selected_idx >= 0:
            selected = owner.drop.pop(selected_idx)
            owner.deck.append(selected.card_id)
            if opponent.hand:
                discarded = opponent.hand.pop(0)
                opponent.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=discarded, source_zone="hand")
        self._checkpoint(state, "effect_auto_restrict_self_copies_and_bottom_deck_green_unison_then_opponent_discard_on_play")

    def _handle_auto_remove_self_prevent_leader_damage_and_battle_ko_for_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if not self._effect_requirements_met(state, reg):
            return
        ctx = state.attack_context
        owner = state.players.get(reg.owner_player_id)
        if ctx is None or owner is None:
            return
        if int(ctx.target_player_id) != int(reg.owner_player_id):
            return
        if ctx.target_zone not in {"leader", "battle"}:
            return
        target = self._find_by_instance(owner, ctx.target_zone, ctx.target_instance_id)
        if target is None:
            return
        if not self._card_matches_effect_filters(
            target,
            allowed_colors=set(),
            required_traits=set(),
            required_characters={"gogeta: gt"},
            required_name_contains="",
        ):
            return
        removed = False
        for zone_cards in (owner.battle_area, owner.unison_area):
            for idx, card in enumerate(zone_cards):
                if int(card.instance_id) != int(reg.source_instance_id):
                    continue
                owner.removed_from_game.append(zone_cards.pop(idx))
                removed = True
                break
            if removed:
                break
        if not removed:
            return
        state.battle_no_damage_player_ids.add(reg.owner_player_id)
        if ctx.target_zone == "battle":
            state.battle_ko_protected_instance_ids.add(ctx.target_instance_id)
        self._checkpoint(state, "effect_auto_remove_self_prevent_leader_damage_and_battle_ko_for_battle")

    def _handle_auto_apply_non_leader_attack_rest_tax_warp_self_and_optionally_negate_opponent_strike(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != int(reg.source_instance_id):
            return
        if str(event.payload.get("played_from") or "").strip().lower() != "hand":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        state.non_leader_attack_rest_taxes.append(
            NonLeaderAttackRestTax(
                owner_player_id=reg.owner_player_id,
                affected_player_id=self._opponent_of(reg.owner_player_id),
                rest_count=self._resolve_effect_int_param(state, reg, "rest_count", default=1),
                expires_on_turn_end_player_id=state.active_player,
            )
        )
        self._schedule_delayed_warp(
            state,
            owner_player_id=reg.owner_player_id,
            target_instance_id=reg.source_instance_id,
            trigger_player_id=state.active_player,
        )
        has_yellow_z_battle = any(
            str(card.card_type or "").strip().upper() == "Z-BATTLE"
            and "yellow" in str(card.color or "").strip().lower()
            for card in owner.battle_area
        )
        leader_is_z_leader = bool(getattr(owner.leader_area, "awakened", False)) or str(owner.leader_area.card_type or "").strip().upper().startswith("Z-")
        if leader_is_z_leader or has_yellow_z_battle:
            state.negate_opponent_strike_for_player_ids.add(reg.owner_player_id)
        self._checkpoint(state, "effect_auto_apply_non_leader_attack_rest_tax_warp_self_and_optionally_negate_opponent_strike")

    def _handle_auto_add_life_to_hand_and_buff_owner_leader_on_owner_matching_battle_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        played = self._find_board_card_by_instance(owner, int(event.payload.get("source_instance_id") or -1))
        if played is None:
            return
        played_colors = {
            part.strip().lower()
            for part in str(played.color or "").replace("/", ",").split(",")
            if part.strip()
        }
        if len(played_colors) < 2:
            return
        runtime = self._resolve_card_runtime_data(played.card_id)
        characters = {
            part.strip().lower()
            for part in [*tuple(runtime.characters or ()), *tuple(getattr(played, "characters", ()) or ())]
            if part.strip()
        }
        has_pan = "pan" in characters
        has_gt = any("gt" in part for part in characters)
        if not (has_pan or has_gt):
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta > 0:
            source.markers += marker_delta
        if owner.life:
            owner.hand.append(owner.life.pop(0))
        self._apply_temporary_power_delta(state, card=owner.leader_area, delta=5000, reason="effect_owner_leader_buff_on_matching_battle_play")
        self._checkpoint(state, "effect_auto_add_life_to_hand_and_buff_owner_leader_on_owner_matching_battle_played")

    def _handle_auto_play_self_from_hand_on_owner_matching_battle_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        match = self._match_owner_battle_played_event(state, event, reg)
        if match is None:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source_index = next((i for i, card in enumerate(owner.hand) if int(card.instance_id) == int(reg.source_instance_id)), -1)
