    def _handle_auto_restrict_played_opponent_battle_attack_for_turn_if_cost_greater_than_current_energy(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        match = self._match_owner_opponent_battle_played_event(state, event, reg)
        if match is None:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent, live_played, probe = match
        target = live_played or probe
        target_cost = int(target.energy_cost or -1)
        if target_cost <= len(opponent.energy):
            return
        state.attack_restricted_instance_ids.add(int(target.instance_id))
        self._checkpoint(state, "effect_auto_restrict_played_opponent_battle_attack_for_turn_if_cost_greater_than_current_energy")

    def _handle_auto_power_reduce_up_to_n_played_opponent_battle_for_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        match = self._match_owner_opponent_battle_played_event(state, event, reg)
        if match is None:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        required_name_under_either_leader = str(reg.handler_params.get("required_name_under_either_leader", "")).strip().upper()
        if required_name_under_either_leader:
            def _leader_has_name(leader: CardInstance) -> bool:
                for card_id in tuple(leader.stacked_card_ids or ()):
                    runtime_name = str(self._resolve_card_runtime_data(int(card_id)).card_name or "").upper()
                    if required_name_under_either_leader in runtime_name:
                        return True
                return False
            if not (_leader_has_name(owner.leader_area) or _leader_has_name(opponent.leader_area)):
                return
        _opp, _live, probe = match
        target = next((card for card in opponent.battle_area if int(card.instance_id) == int(probe.instance_id)), None)
        if target is None:
            return
        power_delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if power_delta == 0:
            return
        self._apply_temporary_power_delta(state, card=target, delta=power_delta, reason="effect_auto_power_reduce_up_to_n_played_opponent_battle_for_turn")
        self._checkpoint(state, "effect_auto_power_reduce_up_to_n_played_opponent_battle_for_turn")

    def _handle_auto_combo_mono_blue_boujack_brigade_from_energy_then_add_top_deck_to_energy_on_opponent_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if event.actor_player_id != self._opponent_of(reg.owner_player_id):
            return
        if str(event.payload.get("attacker_zone") or "").strip().lower() != "battle":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        energy_idx = next(
            (
                i
                for i, card in enumerate(owner.energy)
                if self._card_matches_effect_filters(
                    card,
                    allowed_colors={"blue"},
                    required_traits={"boujack brigade"},
                    required_characters=set(),
                    required_name_contains="",
                )
                and len({part.strip().lower() for part in str(card.color or "").replace("/", ",").split(",") if part.strip()}) == 1
            ),
            -1,
        )
        if energy_idx < 0:
            return
        combo_card = owner.energy.pop(energy_idx)
        combo_card.comboed_from = "energy"
        owner.combo_area.append(combo_card)
        self._emit_effect_event(
            state,
            name="card_comboed",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": combo_card.instance_id,
                "source_card_id": combo_card.card_id,
                "source_zone": "combo",
                "comboed_from": "energy",
            },
        )
        if owner.deck:
            top_id = owner.deck.pop(0)
            energy_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=top_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            owner.energy.append(energy_card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="energy", card=energy_card)
            self._emit_effect_event(
                state,
                name="card_added_to_energy",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": energy_card.instance_id,
                    "source_card_id": energy_card.card_id,
                    "source_zone": "energy",
                    "added_from": "deck",
                },
            )
        self._checkpoint(state, "effect_auto_combo_mono_blue_boujack_brigade_from_energy_then_add_top_deck_to_energy_on_opponent_attack")

    def _handle_auto_buff_played_battle_and_draw_if_power_at_least(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if event.actor_player_id != reg.owner_player_id:
            return
        if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        target = self._find_by_instance(owner, "battle", int(event.payload.get("source_instance_id") or -1))
        if target is None:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        threshold = self._resolve_effect_int_param(state, reg, "draw_if_power_at_least", default=-1)
        before_power = int(target.power or 0)
        if delta:
            self._apply_temporary_power_delta(state, card=target, delta=delta, reason="effect_owner_battle_played_battle_buff")
        after_power = int(target.power or 0)
        if threshold >= 0 and before_power < threshold <= after_power and owner.deck:
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_buff_played_battle_and_draw_if_power_at_least")

    def _handle_auto_power_reduce_up_to_n_opponent_cards_for_turn_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta == 0:
            return
        target_scope = str(reg.handler_params.get("target_scope", "battle")).strip().lower()
        if target_scope in {"battle_or_unison", "board"}:
            candidates = [*opponent.battle_area, *opponent.unison_area]
            if not bool(reg.handler_params.get("ignores_barrier", False)):
                candidates = [card for card in candidates if not self._card_currently_has_barrier(card)]
            if not candidates:
                return
            indexes = self._choose_effect_target_indexes(
                state,
                reg,
                candidates,
                max_targets,
                str(reg.handler_params.get("target_policy", "first")),
            )
            targets = [candidates[idx] for idx in indexes]
        else:
            targets = self._select_opponent_battle_targets(
                state,
                reg,
                max_targets=max_targets,
                max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
                policy=str(reg.handler_params.get("target_policy", "first")),
            )
        if not targets:
            return
        for target in targets:
            self._apply_temporary_power_delta(
                state,
                card=target,
                delta=delta,
                reason="effect_auto_power_reduce_for_turn",
            )
        self._checkpoint(state, "effect_auto_power_reduce_up_to_n_opponent_cards_for_turn_on_play")

    def _handle_auto_reduce_up_to_n_opponent_cards_power_by_owner_energy_color_count_on_play_or_added_to_energy(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_added_to_energy":
            if event.name != "card_added_to_energy":
                return
            required_added_from = str(reg.handler_params.get("requires_added_from_zones", "")).strip().lower()
            if required_added_from and str(event.payload.get("added_from") or "").strip().lower() != required_added_from:
                return
        else:
            if event.name != "card_played":
                return
            required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
            if required_from and str(event.payload.get("played_from") or "").strip().lower() != required_from:
                return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        needs_other_multicolor = bool(reg.handler_params.get("requires_other_multicolor_energy", False))
        if needs_other_multicolor:
            source_zone = str(event.payload.get("source_zone") or reg.source_zone or "").strip().lower()
            has_other_multicolor = False
            for energy in owner.energy:
                if source_zone == "energy" and int(energy.instance_id) == int(reg.source_instance_id):
                    continue
                colors = {
                    part.strip().lower()
                    for part in str(energy.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
                if "black" in colors and len(colors) >= 2:
                    has_other_multicolor = True
                    break
            if not has_other_multicolor:
                return
        candidates = [*opponent.battle_area, *opponent.unison_area]
        if not candidates:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta == 0:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            candidates,
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        for idx in indexes:
            self._apply_temporary_power_delta(
                state,
                card=candidates[idx],
                delta=delta,
                reason="effect_auto_reduce_up_to_n_opponent_cards_power_by_owner_energy_color_count_on_play_or_added_to_energy",
            )
        self._checkpoint(state, "effect_auto_reduce_up_to_n_opponent_cards_power_by_owner_energy_color_count_on_play_or_added_to_energy")

    def _handle_auto_switch_up_to_n_opponent_battle_rest_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_placed_into_drop":
            if event.name != "card_placed_into_drop":
                return
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            required_from = {
                part.strip().lower()
                for part in str(reg.handler_params.get("requires_placed_from_zones", "")).replace("|", ",").split(",")
                if part.strip()
            }
            placed_from = str(event.payload.get("source_zone") or "").strip().lower()
            if required_from and placed_from not in required_from:
                return
        else:
            if event.name != "card_played":
                return
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_battle_rest_on_play")

    def _handle_auto_switch_up_to_n_opponent_unison_rest_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        min_source_markers = self._resolve_effect_int_param(state, reg, "min_source_markers", default=0)
        if min_source_markers > 0 and int(getattr(source, "markers", 0) or 0) < min_source_markers:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0 or not opponent.unison_area:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            list(opponent.unison_area),
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        for idx in indexes:
            target = opponent.unison_area[idx]
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_unison_rest_on_play")

    def _handle_auto_add_up_to_n_matching_from_top_deck_to_energy_rest_then_bottom_deck_owner_energy_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        look_count = min(self._resolve_effect_int_param(state, reg, "look_count", default=5), len(owner.deck))
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        chosen_indexes: list[int] = []
        for i in range(look_count):
            deck_card = owner.deck[i]
            card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
            probe = self._create_card_instance(next_instance_id=-(reg.owner_player_id * 100000 + i + 1), card_id=card_id, owner_id=reg.owner_player_id)
            if not self._card_matches_effect_filters(
                probe,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains="",
            ):
                continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= max_targets:
                break
        removed = 0
        moved = 0
        for idx in chosen_indexes:
            deck_card = owner.deck.pop(idx - removed)
            removed += 1
            card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            card.resting = True
            owner.energy.append(card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="energy", card=card)
            moved += 1
        if moved <= 0:
            return
        if owner.energy:
            bottom_idx = 0
            chosen_energy = owner.energy.pop(bottom_idx)
            owner.deck.append(chosen_energy.card_id)
        self._checkpoint(state, "effect_auto_add_up_to_n_matching_from_top_deck_to_energy_rest_then_bottom_deck_owner_energy_on_play")

    def _handle_auto_negate_up_to_n_opponent_rest_battle_skills_for_turn_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        min_source_markers = self._resolve_effect_int_param(state, reg, "min_source_markers", default=0)
        if min_source_markers > 0 and int(getattr(source, "markers", 0) or 0) < min_source_markers:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        candidates = [card for card in opponent.battle_area if card.resting and (max_cost < 0 or int(card.energy_cost or 0) <= max_cost)]
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            candidates,
            self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].temporary_skills_negated = True
        self._checkpoint(state, "effect_auto_negate_up_to_n_opponent_rest_battle_skills_for_turn_on_play")

    def _handle_auto_negate_up_to_n_opponent_battle_skills_for_turn_on_play_or_self_switch(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name == "card_played":
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif event.name == "card_switched_to_active":
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if not bool(event.payload.get("by_skill") or False):
                return
            if state.active_player != reg.owner_player_id:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        candidates = [card for card in opponent.battle_area if max_cost < 0 or int(card.energy_cost or 0) <= max_cost]
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            candidates,
            self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        for idx in indexes:
            candidates[idx].temporary_skills_negated = True
        self._checkpoint(state, "effect_auto_negate_up_to_n_opponent_battle_skills_for_turn_on_play_or_self_switch")

    def _handle_auto_opponent_discards_n_from_hand_on_play_or_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name not in {"card_played", "card_comboed"}:
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if event.name == "card_played" and required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        required_comboed_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if event.name == "card_comboed" and required_comboed_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_comboed_from:
                return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None or not opponent.hand:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(min(amount, len(opponent.hand))):
            opponent.drop.append(opponent.hand.pop(0))
        self._checkpoint(state, "effect_auto_opponent_discards_n_from_hand_on_play_or_combo")

    def _handle_auto_opponent_discards_n_from_hand_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        if str(event.payload.get("attacker_zone") or "").strip().lower() != "battle":
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None or not opponent.hand:
            return
        discard_count = self._resolve_effect_int_param(state, reg, "discard_count", default=1)
        moved = 0
        while moved < discard_count and opponent.hand:
            discarded = opponent.hand.pop(0)
            opponent.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=discarded, source_zone="hand")
            moved += 1
        self._checkpoint(state, "effect_auto_opponent_discards_n_from_hand_on_attack")

    def _handle_auto_play_up_to_n_named_from_owner_deck_rest_on_play_or_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name not in {"card_played", "card_comboed"}:
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if event.name == "card_played" and required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        required_comboed_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if event.name == "card_comboed" and required_comboed_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_comboed_from:
                return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        max_look = self._resolve_effect_int_param(state, reg, "max_look", default=-1)
        rest_mode = bool(reg.handler_params.get("resting", True))
        played = 0
        idx = 0
        looked = 0
        while idx < len(owner.deck) and played < max_targets and (max_look < 0 or looked < max_look):
            deck_card = owner.deck[idx]
            card_id = deck_card.card_id if isinstance(deck_card, CardInstance) else int(deck_card)
            runtime = self._resolve_card_runtime_data(card_id)
            runtime_name = str(runtime.card_name or "").upper()
            if required_name_contains and required_name_contains not in runtime_name:
                idx += 1
                looked += 1
                continue
            owner.deck.pop(idx)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            card.resting = rest_mode
            owner.battle_area.append(card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "deck",
                    "played_via": "effect",
                },
            )
            played += 1
            looked += 1
        if played > 0:
            self._checkpoint(state, "effect_auto_play_up_to_n_named_from_owner_deck_rest_on_play_or_combo")

    def _handle_auto_play_matching_from_owner_deck_on_top_of_self_active_on_attack_ko(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "battle_end":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        if not bool(event.payload.get("target_battle_koed", False)):
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        target_instance_id = int(event.payload.get("target_instance_id") or -1)
        koed_card = next((card for card in opponent.drop if int(card.instance_id) == target_instance_id), None)
        if koed_card is None:
            return
        if self._resolve_effect_int_param(state, reg, "required_target_min_cost", default=-1) > int(koed_card.energy_cost or 0):
            return
        owner = state.players.get(reg.owner_player_id)
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id) if owner is not None else None
        if owner is None or source is None:
            return
        played = self._play_up_to_n_matching_cards_from_owner_deck_on_top_of_host(
            state,
            owner_player_id=reg.owner_player_id,
            host=source,
            host_zone=reg.source_zone,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            allowed_colors={
                part.strip().lower()
                for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                if part.strip()
            },
            required_traits={
                part.strip().lower()
                for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_characters={
                part.strip().lower()
                for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
            min_cost=self._resolve_effect_int_param(state, reg, "min_cost", default=-1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            resting_override=False,
        )
        if played:
            self._checkpoint(state, "effect_auto_play_matching_from_owner_deck_on_top_of_self_active_on_attack_ko")

    def _handle_auto_look_top_add_saiyan_or_unison_to_hand_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id) if owner is not None else None
        if owner is None or source is None or not owner.deck:
            return
        if int(source.power or 0) < self._resolve_effect_int_param(state, reg, "min_source_power", default=0):
            return
        max_look = self._resolve_effect_int_param(state, reg, "max_look", default=5)
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=5)
        unison_specified_cost = self._resolve_effect_int_param(state, reg, "unison_specified_cost", default=3)
        looked = owner.deck[: max(max_look, 0)]
        chosen_index: int | None = None
        for idx, card_id in enumerate(looked):
            runtime = self._resolve_card_runtime_data(card_id)
            temp = CardInstance(
                instance_id=0,
                card_id=card_id,
                owner_id=reg.owner_player_id,
                card_type=str(runtime.card_type or ""),
                color=str(runtime.color or ""),
                power=int(runtime.power or 0),
                energy_cost=int(runtime.energy_cost or 0),
                traits=tuple(runtime.traits or ()),
                characters=tuple(runtime.characters or ()),
                skill_text_raw=str(runtime.skill_text_raw or ""),
                keywords=tuple(runtime.keywords or ()),
            )
            if self._card_matches_effect_filters(
                temp,
                allowed_colors={"red"},
                required_traits={"saiyan"},
                required_characters=set(),
                required_name_contains="",
                required_card_types={"BATTLE"},
            ) and int(runtime.energy_cost or 0) <= max_cost:
                chosen_index = idx
                break
            if self._card_matches_effect_filters(
                temp,
                allowed_colors={"red"},
                required_traits=set(),
                required_characters=set(),
                required_name_contains="",
                required_card_types={"UNISON"},
            ) and int(getattr(temp, "markers", 0) or 0) == 0 and int(runtime.energy_cost or 0) == unison_specified_cost:
                chosen_index = idx
                break
        if chosen_index is None:
            if owner.deck:
                random.Random(0).shuffle(owner.deck)
            self._checkpoint(state, "effect_auto_look_top_add_saiyan_or_unison_to_hand_on_attack")
            return
        owner.hand.append(self._create_card_instance(next_instance_id=state.next_instance_id, card_id=owner.deck.pop(chosen_index), owner_id=reg.owner_player_id))
        state.next_instance_id += 1
        if owner.deck:
            random.Random(0).shuffle(owner.deck)
        self._checkpoint(state, "effect_auto_look_top_add_saiyan_or_unison_to_hand_on_attack")

    def _handle_auto_buff_self_for_battle_per_under_card(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
            return
        owner = state.players.get(reg.owner_player_id)
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id) if owner is not None else None
        if source is None:
            return
        per_card = self._resolve_effect_int_param(state, reg, "power_per_card", default=10000)
        count = len(tuple(getattr(source, "stacked_card_ids", ()) or ()))
        if count <= 0 or per_card == 0:
            return
        self._apply_battle_temporary_power_delta(
            state,
            card=source,
            delta=count * per_card,
            reason="effect_auto_buff_self_for_battle_per_under_card",
        )
        self._checkpoint(state, "effect_auto_buff_self_for_battle_per_under_card")

    def _handle_auto_add_up_to_n_matching_from_owner_drop_to_energy_rest_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.drop:
            return
        required_color = str(reg.handler_params.get("energy_mono_color", "") or "").strip().lower()
        if required_color and not self._owner_energy_is_all_mono_color(owner, required_color):
            return
        chosen_index = next(
            (
                i
                for i, card in enumerate(owner.drop)
                if self._card_matches_effect_filters(
                    card,
                    allowed_colors={
                        part.strip().lower()
                        for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                        if part.strip()
                    },
                    required_traits={
                        part.strip().lower()
                        for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
                        if part.strip()
                    },
                    required_characters={
                        part.strip().lower()
                        for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
                        if part.strip()
                    },
                    required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
                    required_card_types={
                        part.strip().upper()
                        for part in str(reg.handler_params.get("required_card_type", "")).replace("|", ",").split(",")
                        if part.strip()
                    }
                    or None,
                )
            ),
            -1,
        )
        if chosen_index < 0:
            return
        card = owner.drop.pop(chosen_index)
        card.resting = True
        owner.energy.append(card)
        self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="energy", card=card)
        self._emit_effect_event(
            state,
            name="card_added_to_energy",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": card.instance_id,
                "source_card_id": card.card_id,
                "source_zone": "energy",
                "added_from": "drop",
            },
        )
        self._checkpoint(state, "effect_auto_add_up_to_n_matching_from_owner_drop_to_energy_rest_on_play")

    def _handle_auto_use_under_host_combo_switch_host_active_and_restrict_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name not in {"attack_declared", "blocker_activated"}:
            return
        owner = state.players.get(reg.owner_player_id)
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id) if owner is not None else None
        if owner is None or source is None:
            return
        required_host_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("host_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        host = next(
            (
                card
                for card in owner.battle_area
                if required_host_characters.intersection(
                    {
                        part.strip().lower()
                        for part in [*tuple(card.characters or ()), *tuple(self._resolve_card_runtime_data(card.card_id).characters or ())]
                        if part.strip()
                    }
                )
            ),
            None,
        )
        if host is None or not source.stacked_card_ids:
            return
        under_card_id = int(source.stacked_card_ids[-1])
        combo_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=under_card_id, owner_id=reg.owner_player_id)
        state.next_instance_id += 1
        combo_card.temporary_skills_negated = True
        owner.combo_area.append(combo_card)
        source.stacked_card_ids = tuple(source.stacked_card_ids[:-1])
        host.resting = False
        state.attack_restricted_instance_ids.add(host.instance_id)
        self._checkpoint(state, "effect_auto_use_under_host_combo_switch_host_active_and_restrict_attack")

    def _handle_auto_use_under_chosen_owner_battle_combo_switch_it_active_and_restrict_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name not in {"attack_declared", "blocker_activated"}:
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        required_host_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("host_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_host_skill_text = str(reg.handler_params.get("host_required_skill_text_contains", "")).strip().lower()
        host = next(
            (
                card
                for card in owner.battle_area
                if int(card.instance_id) != int(reg.source_instance_id)
                and card.stacked_card_ids
                and required_host_characters.intersection(
                    {
                        part.strip().lower()
                        for part in [*tuple(card.characters or ()), *tuple(self._resolve_card_runtime_data(card.card_id).characters or ())]
                        if part.strip()
                    }
                )
                and (
                    not required_host_skill_text
                    or required_host_skill_text in str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "").lower()
                )
            ),
            None,
        )
        if host is None:
            return
        under_card_id = int(host.stacked_card_ids[-1])
        combo_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=under_card_id, owner_id=reg.owner_player_id)
        state.next_instance_id += 1
        combo_card.temporary_skills_negated = True
        owner.combo_area.append(combo_card)
        host.stacked_card_ids = tuple(host.stacked_card_ids[:-1])
        host.resting = False
        state.attack_restricted_instance_ids.add(host.instance_id)
        self._checkpoint(state, "effect_auto_use_under_chosen_owner_battle_combo_switch_it_active_and_restrict_attack")

    def _handle_auto_grant_servant_to_up_to_n_opponent_battle_until_next_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_attacks":
            if event.name != "attack_declared":
                return
            if int(event.payload.get("attacker_instance_id") or -1) != int(reg.source_instance_id):
                return
        else:
            if event.name != "card_played":
                return
            if int(event.payload.get("source_instance_id") or -1) != int(reg.source_instance_id):
                return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        trigger_player_id = self._opponent_of(reg.owner_player_id) if bool(reg.handler_params.get("until_opponent_next_turn", True)) else reg.owner_player_id
        for target in targets:
            self._append_temporary_keyword(target, "Servant", duration="delayed")
            state.delayed_keyword_clears.append(
                DelayedKeywordClear(
                    owner_player_id=target.owner_id,
                    target_instance_id=target.instance_id,
                    trigger_player_id=trigger_player_id,
                    keyword="Servant",
                    created_turn_number=state.turn_number,
                    require_next_turn=True,
                )
            )
        self._checkpoint(state, "effect_auto_grant_servant_to_up_to_n_opponent_battle_until_next_turn")

    def _handle_auto_place_green_extra_from_owner_hand_under_leader_then_draw_n_on_self_left_battle_area(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_left_battle_area":
            return
        if not self._effect_requirements_met(state, reg):
            return
        match = self._match_owner_battle_left_event(state, event, reg)
        if match is None:
            return
        owner, _left_probe = match
        leader = owner.leader_area
        hand_index = next(
            (
                idx
                for idx, card in enumerate(owner.hand)
                if str(card.card_type or "").upper() in {"EXTRA", "Z-EXTRA"}
                and "green" in {part.strip().lower() for part in str(card.color or "").replace("/", ",").split(",") if part.strip()}
            ),
            -1,
        )
        if hand_index < 0:
            return
        placed = owner.hand.pop(hand_index)
        leader.stacked_card_ids = tuple(leader.stacked_card_ids or ()) + (placed.card_id,)
        self._register_leader_under_card_effects(state, player_id=owner.player_id)
        self._emit_effect_event(
            state,
            name="card_placed_under_card",
            actor_player_id=owner.player_id,
            payload={
                "source_instance_id": placed.instance_id,
                "source_card_id": placed.card_id,
                "source_zone": "under",
                "placed_from": "hand",
                "owner_player_id": owner.player_id,
                "placed_card_owner_player_id": owner.player_id,
                "host_instance_id": leader.instance_id,
                "host_card_id": leader.card_id,
                "host_zone": "leader",
                "host_owner_player_id": owner.player_id,
                "placed_by": "skill",
            },
        )
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        self._checkpoint(state, "effect_auto_place_green_extra_from_owner_hand_under_leader_then_draw_n_on_self_left_battle_area")

    def _handle_auto_buff_self_and_grant_skill_removal_protection_until_next_opponent_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        power_delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if power_delta:
            self._apply_temporary_power_delta(state, card=source, delta=power_delta, reason="effect_auto_buff_self_and_grant_skill_removal_protection_until_next_opponent_turn")
        self._append_temporary_keyword(source, "skill_removal_protection", duration="delayed")
        state.delayed_keyword_clears.append(
            DelayedKeywordClear(
                owner_player_id=reg.owner_player_id,
                target_instance_id=source.instance_id,
                trigger_player_id=self._opponent_of(reg.owner_player_id),
                keyword="skill_removal_protection",
                require_next_turn=True,
            )
        )
        self._checkpoint(state, "effect_auto_buff_self_and_grant_skill_removal_protection_until_next_opponent_turn")

    def _handle_auto_discard_from_owner_hand_then_opponent_discards_on_owner_card_placed_into_drop(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_placed_into_drop":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        required_from = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_source_zones", "")).replace("|", ",").split(",")
            if part.strip()
        }
        placed_from = str(event.payload.get("source_zone") or "").strip().lower()
        if required_from and placed_from not in required_from:
            return
        if not owner.hand:
            return
        discarded = owner.hand.pop(0)
        owner.drop.append(discarded)
        self._emit_card_placed_into_drop(state, owner_player_id=owner.player_id, card=discarded, source_zone="hand")
        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(min(max(amount, 0), len(opponent.hand))):
            opp_discard = opponent.hand.pop(0)
            opponent.drop.append(opp_discard)
            self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=opp_discard, source_zone="hand")
        self._checkpoint(state, "effect_auto_discard_from_owner_hand_then_opponent_discards_on_owner_card_placed_into_drop")

    def _handle_auto_add_top_n_from_owner_deck_to_life_on_owner_card_placed_into_drop(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_placed_into_drop":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        required_from = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_source_zones", "")).replace("|", ",").split(",")
            if part.strip()
        }
        placed_from = str(event.payload.get("source_zone") or "").strip().lower()
        if required_from and placed_from not in required_from:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=0)
        added = 0
        while owner.deck and added < max(amount, 0):
            card_id = owner.deck.pop(0)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=owner.player_id)
            state.next_instance_id += 1
            owner.life.insert(0, card)
            added += 1
        if added > 0:
            self._checkpoint(state, "effect_auto_add_top_n_from_owner_deck_to_life_on_owner_card_placed_into_drop")

    def _handle_auto_optional_drop_villainous_and_self_gain_power_and_keyword_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        chosen: tuple[int, str, int] | None = None
        for player_id, player in state.players.items():
            for zone_name, zone_cards in (("battle", player.battle_area), ("unison", player.unison_area)):
                for idx, card in enumerate(zone_cards):
                    runtime = self._resolve_card_runtime_data(card.card_id)
                    blob = f"{runtime.card_name}\n{runtime.skill_text_raw}\n{' '.join(runtime.keywords or ())}".lower()
                    if "villainous" not in blob:
                        continue
                    chosen = (player_id, zone_name, idx)
                    break
                if chosen is not None:
                    break
            if chosen is not None:
                break
        if chosen is None:
            return
        chosen_owner_id, chosen_zone, chosen_idx = chosen
        chosen_owner = state.players[chosen_owner_id]
        zone_cards = chosen_owner.battle_area if chosen_zone == "battle" else chosen_owner.unison_area
        moved = zone_cards.pop(chosen_idx)
        chosen_owner.drop.append(moved)
        self._emit_card_placed_into_drop(state, owner_player_id=chosen_owner.player_id, card=moved, source_zone=chosen_zone)
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        if delta:
            self._apply_temporary_power_delta(state, card=source, delta=delta, reason="effect_auto_optional_drop_villainous")
        keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if keyword:
            self._append_temporary_keyword(source, keyword, duration="turn")
        self._checkpoint(state, "effect_auto_optional_drop_villainous_and_self_gain_power_and_keyword_on_play")

    def _handle_auto_play_up_to_n_yellow_trunks_future_from_owner_deck_or_drop_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        bottom_deck_hand = int(reg.handler_params.get("bottom_deck_hand_before", 0) or 0)
        for _ in range(min(bottom_deck_hand, len(owner.hand))):
            owner.deck.append(owner.hand.pop(0).card_id)
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        used_deck = False
        chosen_card: CardInstance | None = None
        for i, raw in enumerate(owner.deck):
            card_id = raw.card_id if isinstance(raw, CardInstance) else int(raw)
            probe = self._create_card_instance(next_instance_id=0, card_id=card_id, owner_id=reg.owner_player_id)
            if not self._card_matches_effect_filters(
                probe,
                allowed_colors={"yellow"},
                required_traits=set(),
                required_characters={"trunks: future"},
                required_name_contains="",
                required_card_types={"BATTLE"},
            ):
                continue
            if max_cost >= 0 and int(probe.energy_cost or -1) > max_cost:
                continue
            owner.deck.pop(i)
            chosen_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            used_deck = True
            break
        if chosen_card is None:
            for i, card in enumerate(owner.drop):
                if not self._card_matches_effect_filters(
                    card,
                    allowed_colors={"yellow"},
                    required_traits=set(),
                    required_characters={"trunks: future"},
                    required_name_contains="",
                    required_card_types={"BATTLE"},
                ):
                    continue
                if max_cost >= 0 and int(card.energy_cost or -1) > max_cost:
                    continue
                chosen_card = owner.drop.pop(i)
                break
        if chosen_card is None:
            return
        chosen_card.resting = False
        owner.battle_area.append(chosen_card)
        self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=chosen_card)
        self._emit_effect_event(
            state,
            name="card_played",
            actor_player_id=reg.owner_player_id,
            payload={
                "source_instance_id": chosen_card.instance_id,
                "source_card_id": chosen_card.card_id,
                "source_zone": "battle",
                "played_from": "deck" if used_deck else "drop",
                "played_via": "skill",
            },
        )
        if used_deck and owner.deck:
            random.Random(0).shuffle(owner.deck)
        self._checkpoint(state, "effect_auto_play_up_to_n_yellow_trunks_future_from_owner_deck_or_drop_on_play")

    def _handle_auto_add_skillless_cost2_from_owner_deck_or_drop_to_hand_then_optional_play_from_hand_rest(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name not in {"card_played", "battle_end"}:
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        if event.name == "card_played":
            if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if str(event.payload.get("played_from") or "").strip().lower() != "hand":
                return
        else:
            source = next((card for card in owner.combo_area if int(card.instance_id) == int(reg.source_instance_id)), None)
            if source is None or str(getattr(source, "comboed_from", "") or "").strip().lower() != "hand":
                return
        if not self._effect_requirements_met(state, reg):
            return
        selected_drop_idx = next(
            (
                idx
                for idx, card in enumerate(owner.drop)
                if str(getattr(card, "card_type", "") or "").upper() == "BATTLE"
                and int(getattr(card, "energy_cost", -1) or -1) == 2
                and self._card_is_skillless(card)
            ),
            -1,
        )
        added_card: CardInstance | None = None
        if selected_drop_idx >= 0:
            added_card = owner.drop.pop(selected_drop_idx)
            owner.hand.append(added_card)
        else:
            deck_idx = next(
                (
                    idx
                    for idx, raw in enumerate(owner.deck)
                    if (
                        lambda probe: str(probe.card_type or "").upper() == "BATTLE"
                        and int(getattr(probe, "energy_cost", -1) or -1) == 2
                        and self._card_is_skillless(probe)
                    )(self._create_card_instance(next_instance_id=-(idx + 1), card_id=(raw.card_id if isinstance(raw, CardInstance) else int(raw)), owner_id=reg.owner_player_id))
                ),
                -1,
            )
            if deck_idx >= 0:
                raw = owner.deck.pop(deck_idx)
                card_id = raw.card_id if isinstance(raw, CardInstance) else int(raw)
                added_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
                state.next_instance_id += 1
                owner.hand.append(added_card)
        if added_card is None:
            return
        if state.active_player != reg.owner_player_id:
            play_idx = next(
                (
                    idx
                    for idx, card in enumerate(owner.hand)
                    if str(getattr(card, "card_type", "") or "").upper() == "BATTLE"
                    and int(getattr(card, "energy_cost", -1) or -1) == 2
                    and self._card_is_skillless(card)
                ),
                -1,
            )
            if play_idx >= 0:
                played = owner.hand.pop(play_idx)
                played.resting = True
                owner.battle_area.append(played)
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=played)
                self._emit_effect_event(
                    state,
                    name="card_played",
                    actor_player_id=reg.owner_player_id,
                    payload={
                        "source_instance_id": played.instance_id,
                        "source_card_id": played.card_id,
                        "source_zone": "battle",
                        "played_from": "hand",
                        "played_via": "effect",
                    },
                )
        self._checkpoint(state, "effect_auto_add_skillless_cost2_from_owner_deck_or_drop_to_hand_then_optional_play_from_hand_rest")

    def _handle_auto_switch_up_to_n_owner_opponent_battle_rest_on_owner_opponent_counter_activated(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "counter_skill_activated":
            return
        if event.actor_player_id in {None, reg.owner_player_id}:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None or not opponent.battle_area:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            list(opponent.battle_area),
            self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        for idx in indexes:
            target = opponent.battle_area[idx]
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
        self._checkpoint(state, "effect_auto_switch_up_to_n_owner_opponent_battle_rest_on_owner_opponent_counter_activated")

    def _handle_auto_switch_up_to_n_opponent_board_rest(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if reg.trigger == "self_played":
            if event.name != "card_played" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_attacks":
            if event.name != "attack_declared" or int(event.payload.get("attacker_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_aegis_activated":
            if event.name != "aegis_activated" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_added_to_z_energy":
            if event.name != "card_added_to_z_energy" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
        elif reg.trigger == "self_placed_under_by_union":
            if event.name != "card_placed_under_card" or int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
                return
            if str(event.payload.get("placed_by") or "").strip().lower() != "union":
                return
        elif reg.trigger == "owner_card_placed_under_owner_card":
            if event.name != "card_placed_under_card":
                return
            if int(event.payload.get("host_owner_player_id") or -1) != reg.owner_player_id:
                return
            required_host_zone = str(reg.handler_params.get("required_host_zone", "")).strip().lower()
            host_zone = str(event.payload.get("host_zone") or "").strip().lower()
            if required_host_zone and host_zone != required_host_zone:
                return
            owner = state.players.get(reg.owner_player_id)
            if owner is None:
                return
            host_instance_id = int(event.payload.get("host_instance_id") or -1)
            host = self._find_by_instance(owner, host_zone, host_instance_id)
            if host is None:
                return
            host_name_contains = str(reg.handler_params.get("host_name_contains", "")).strip().upper()
            host_name = str(self._resolve_card_runtime_data(host.card_id).card_name or host.card_name or "").upper()
            if host_name_contains and host_name_contains not in host_name:
                return
        elif reg.trigger == "owner_opponent_battle_played":
            if self._match_owner_opponent_battle_played_event(state, event, reg) is None:
                return
        else:
            return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_or_unison_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
            prefer_attacker=bool(reg.handler_params.get("prefer_attacker", False)),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
            else:
                self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_board_rest")

    def _handle_auto_add_top_deck_to_energy_rest_and_bottom_deck_up_to_n_opponent_battle_on_play(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_played":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if owner is None or opponent is None:
            return
        if owner.deck:
            top_id = owner.deck.pop(0)
            energy_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=top_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            energy_card.resting = True
            owner.energy.append(energy_card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="energy", card=energy_card)
        selected = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        target_ids = {card.instance_id for card in selected}
        if target_ids:
            idx = 0
            while idx < len(opponent.battle_area):
                card = opponent.battle_area[idx]
                if card.instance_id not in target_ids:
                    idx += 1
                    continue
                opponent.deck.append(opponent.battle_area.pop(idx).card_id)
        self._checkpoint(state, "effect_auto_add_top_deck_to_energy_rest_and_bottom_deck_up_to_n_opponent_battle_on_play")

    def _handle_auto_negate_skills_and_restrict_up_to_n_opponent_battle_on_attack(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "attack_declared":
            return
        if event.actor_player_id in {None, reg.owner_player_id}:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta < 0 and source.card_type in {"UNISON", "Z-UNISON"} and source.markers < abs(marker_delta):
            return
        if marker_delta != 0 and source.card_type in {"UNISON", "Z-UNISON"}:
            source.markers += marker_delta
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_negate_battle_card_skills(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.temporary_skills_negated = True
            else:
                self._checkpoint(state, "counter_effect_attacker_skill_negation_prevented")
            state.attack_restricted_instance_ids.add(target.instance_id)
        self._checkpoint(state, "effect_auto_negate_skills_and_restrict_up_to_n_opponent_battle_on_attack")

    def _handle_auto_place_up_to_n_from_owner_drop_under_named_owner_battle_on_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if not self._effect_requirements_met(state, reg):
            return
        match = self._match_owner_combo_event(state, event, reg)
        if match is None:
            return
        owner, _live_combo_card, _combo_probe = match
        if not self._pay_owner_combo_skill_cost_if_needed(state, event, reg, owner):
            return
        host_name = str(reg.handler_params.get("host_name_contains", "")).strip().upper()
        host = next(
            (
                card
                for card in owner.battle_area
                if host_name in str(self._resolve_card_runtime_data(card.card_id).card_name or "").upper()
            ),
            None,
        )
        if host is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        drop_candidates = [
            card
            for card in owner.drop
            if self._card_matches_effect_filters(
                card,
                allowed_colors={part.strip() for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").split(",") if part.strip()},
                required_traits={part.strip() for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",") if part.strip()},
                required_characters={part.strip() for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",") if part.strip()},
                required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
            )
        ]
        if not drop_candidates:
            return
        indexes = self._choose_effect_target_indexes(state, reg, drop_candidates, max_targets, str(reg.handler_params.get("target_policy", "first")))
        if not indexes:
            return
        selected_ids = {drop_candidates[idx].instance_id for idx in indexes}
        idx = 0
        while idx < len(owner.drop):
            card = owner.drop[idx]
            if card.instance_id not in selected_ids:
                idx += 1
                continue
            self._place_card_under_host(host, owner.drop.pop(idx))
        self._checkpoint(state, "effect_auto_place_up_to_n_from_owner_drop_under_named_owner_battle_on_combo")

    def _build_owner_battle_played_event_probe(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        event: EffectEvent,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        owner = state.players.get(owner_player_id)
        if owner is None:
            return None
        played_instance_id = int(event.payload.get("source_instance_id") or -1)
        live_played_card: CardInstance | None = None
        if played_instance_id > 0:
            live_played_card = self._find_board_card_by_instance(owner, played_instance_id)
            if live_played_card is None:
                found = self._find_card_on_any_board_by_instance(state, instance_id=played_instance_id)
                if found is not None:
                    _zone_name, live_played_card = found
        if live_played_card is not None:
            return owner, live_played_card, live_played_card
        played_card_id = int(event.payload.get("source_card_id") or 0)
        source_card_name = str(event.payload.get("source_card_name") or "").strip()
        if played_card_id <= 0 and not source_card_name:
            return None
        played_runtime = self._resolve_card_runtime_data(played_card_id) if played_card_id > 0 else None
        played_probe = CardInstance(
            instance_id=played_instance_id if played_instance_id > 0 else 0,
            card_id=played_card_id,
            owner_id=int(event.payload.get("owner_player_id") or owner_player_id or 0),
            card_type=str((played_runtime.card_type if played_runtime is not None else None) or "BATTLE"),
            color=str((played_runtime.color if played_runtime is not None else None) or "") or None,
            power=int((played_runtime.power if played_runtime is not None else None) or 0),
            energy_cost=(played_runtime.energy_cost if played_runtime is not None else None),
            skill_text_raw=str((played_runtime.skill_text_raw if played_runtime is not None else None) or ""),
            traits=tuple((played_runtime.traits if played_runtime is not None else ()) or ()),
            characters=tuple((played_runtime.characters if played_runtime is not None else ()) or ()),
            keywords=tuple((played_runtime.keywords if played_runtime is not None else ()) or ()),
            has_counter=bool((played_runtime.has_counter if played_runtime is not None else False)),
            has_activate_main=bool((played_runtime.has_activate_main if played_runtime is not None else False)),
            has_activate_battle=bool((played_runtime.has_activate_battle if played_runtime is not None else False)),
            has_auto=bool((played_runtime.has_auto if played_runtime is not None else False)),
            has_permanent=bool((played_runtime.has_permanent if played_runtime is not None else False)),
            has_draw=bool((played_runtime.has_draw if played_runtime is not None else False)),
            has_barrier=bool((played_runtime.has_barrier if played_runtime is not None else False)),
        )
        played_probe.card_name = source_card_name or str((played_runtime.card_name if played_runtime is not None else None) or "")
        return owner, None, played_probe

    def _match_owner_battle_played_event(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        if event.name != "card_played":
            return None
        if str(event.payload.get("source_zone") or "").strip().lower() != "battle":
            return None
        played_from = str(event.payload.get("played_from") or "").strip().lower()
        event_owner_player_id = int(event.payload.get("owner_player_id") or -1)
        if event.actor_player_id != reg.owner_player_id:
            if not (played_from == "token" and event_owner_player_id == reg.owner_player_id):
                return None
        elif int(event.payload.get("source_instance_id") or -1) == reg.source_instance_id:
            return None
        match = self._build_owner_battle_played_event_probe(state, owner_player_id=reg.owner_player_id, event=event)
        if match is None:
            return None
        owner, live_played_card, played_probe = match
        required_played_from = str(reg.handler_params.get("event_required_played_from", "")).strip().lower()
        if required_played_from and played_from != required_played_from:
            return None
        required_played_via = str(reg.handler_params.get("event_requires_played_via", "")).strip().lower()
        if required_played_via:
            played_via = str(event.payload.get("played_via") or "").strip().lower()
            if played_via != required_played_via:
                return None
        required_created_by_source_card_type = str(reg.handler_params.get("event_required_created_by_source_card_type", "")).strip().upper()
        if required_created_by_source_card_type:
            actual_created_by_source_card_type = str(event.payload.get("created_by_source_card_type") or "").strip().upper()
            if actual_created_by_source_card_type != required_created_by_source_card_type:
                return None
        required_created_by_source_zone = str(reg.handler_params.get("event_required_created_by_source_zone", "")).strip().lower()
        if required_created_by_source_zone:
            actual_created_by_source_zone = str(event.payload.get("created_by_source_zone") or "").strip().lower()
            if actual_created_by_source_zone != required_created_by_source_zone:
                return None
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_keywords = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_keywords", "")).replace("|", ",").split(",")
            if part.strip()
        }
        excluded_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_excluded_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("event_required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("event_required_card_type", "")).replace("|", ",").split(",")
            if part.strip()
        }
        if not self._card_matches_effect_filters(
            played_probe,
            allowed_colors=allowed_colors,
            required_traits=required_traits,
            required_characters=required_characters,
            required_name_contains=required_name_contains,
            required_card_types=required_card_types,
        ):
            return None
        if bool(reg.handler_params.get("event_requires_multicolor", False)):
            played_colors = {
                part.strip().lower()
                for part in str(getattr(played_probe, "color", "") or "").replace("/", ",").split(",")
                if part.strip()
            }
            if len(played_colors) < 2:
                return None
        event_min_cost = self._resolve_effect_int_param(state, reg, "event_min_energy_cost", default=-1)
        event_max_cost = self._resolve_effect_int_param(state, reg, "event_max_energy_cost", default=-1)
        event_exact_cost = self._resolve_effect_int_param(state, reg, "event_exact_energy_cost", default=-1)
        played_cost = int(played_probe.energy_cost or -1)
        if event_exact_cost >= 0 and played_cost != event_exact_cost:
            return None
        if event_min_cost >= 0 and played_cost < event_min_cost:
            return None
        if event_max_cost >= 0 and played_cost > event_max_cost:
            return None
        if bool(reg.handler_params.get("event_requires_all_characters", False)) and required_characters:
            runtime = self._resolve_card_runtime_data(played_probe.card_id)
            runtime_characters = {
                part.strip().lower()
                for part in [*tuple(runtime.characters or ()), *tuple(getattr(played_probe, "characters", ()) or ())]
                if part.strip()
            }
            if not required_characters.issubset(runtime_characters):
                return None
        return owner, live_played_card, played_probe

    def _handle_auto_place_up_to_n_from_owner_combo_under_owner_leader_on_owner_matching_battle_played(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if not self._effect_requirements_met(state, reg):
            return
        match = self._match_owner_battle_played_event(state, event, reg)
        if match is None:
            return
        owner, _live_played_card, _played_probe = match
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        combo_candidates = [
            card
            for card in owner.combo_area
            if self._card_matches_effect_filters(
                card,
                allowed_colors={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                    if part.strip()
                },
                required_traits={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
                    if part.strip()
                },
                required_characters={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
                    if part.strip()
                },
                required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
                required_card_types={
                    part.strip().upper()
                    for part in str(reg.handler_params.get("required_card_type", "")).replace("|", ",").split(",")
                    if part.strip()
                },
            )
        ]
        if not combo_candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            combo_candidates,
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        selected_ids = {combo_candidates[idx].instance_id for idx in indexes}
        idx = 0
        while idx < len(owner.combo_area):
            card = owner.combo_area[idx]
            if card.instance_id not in selected_ids:
                idx += 1
                continue
            moved = owner.combo_area.pop(idx)
            self._place_card_under_host(owner.leader_area, moved)
            self._emit_card_placed_under_card(
                state,
                owner_player_id=reg.owner_player_id,
                host=owner.leader_area,
                host_zone="leader",
                card=moved,
                source_zone="combo",
            )
        self._checkpoint(state, "effect_auto_place_up_to_n_from_owner_combo_under_owner_leader_on_owner_matching_battle_played")

    def _handle_auto_place_up_to_n_from_owner_drop_under_owner_leader_on_owner_matching_battle_left(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if not self._effect_requirements_met(state, reg):
            return
        match = self._match_owner_battle_left_event(state, event, reg)
        if match is None:
            return
        owner, _left_probe = match
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        drop_candidates = [
            card
            for card in owner.drop
            if self._card_matches_effect_filters(
                card,
                allowed_colors={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                    if part.strip()
                },
                required_traits={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
                    if part.strip()
                },
                required_characters={
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
                    if part.strip()
                },
                required_name_contains=str(reg.handler_params.get("required_name_contains", "")).strip().upper(),
                required_card_types={
                    part.strip().upper()
                    for part in str(reg.handler_params.get("required_card_type", "")).replace("|", ",").split(",")
                    if part.strip()
                },
            )
        ]
        if not drop_candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            drop_candidates,
            max_targets,
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        selected_ids = {drop_candidates[idx].instance_id for idx in indexes}
        idx = 0
        while idx < len(owner.drop):
            card = owner.drop[idx]
            if card.instance_id not in selected_ids:
                idx += 1
                continue
            moved = owner.drop.pop(idx)
            self._place_card_under_host(owner.leader_area, moved)
            self._emit_card_placed_under_card(
                state,
                owner_player_id=reg.owner_player_id,
                host=owner.leader_area,
                host_zone="leader",
                card=moved,
                source_zone="drop",
            )
        self._checkpoint(state, "effect_auto_place_up_to_n_from_owner_drop_under_owner_leader_on_owner_matching_battle_left")

    def _handle_auto_return_cards_warped_by_source_skill_to_owner_hand_on_owner_matching_battle_left(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if not self._effect_requirements_met(state, reg):
            return
        if event.name != "card_left_battle_area":
            return
        if int(event.payload.get("owner_player_id") or -1) != reg.owner_player_id:
            return
        if int(event.payload.get("source_instance_id") or -1) != int(reg.source_instance_id):
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        moved = self._return_cards_marked_by_source_skill_from_warp_to_hand(
            state,
            affected_player_id=opponent_id,
            source_instance_id=reg.source_instance_id,
        )
        if moved <= 0:
            return
        self._checkpoint(state, "effect_auto_return_cards_warped_by_source_skill_to_owner_hand_on_owner_matching_battle_left")

    def _handle_auto_choose_play_up_to_n_from_owner_deck_or_hand_or_secondary_on_self_left_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_left_battle_area":
            return
        if int(event.payload.get("source_instance_id") or -1) != int(reg.source_instance_id):
            return
        if not self._effect_requirements_met(state, reg):
            return
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_skill_text_contains = str(reg.handler_params.get("required_skill_text_contains", "")).strip().lower()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_card_type", "")).replace("|", ",").split(",")
            if part.strip()
        }
        played = self._play_up_to_n_matching_cards_from_owner_deck_or_hand(
            state,
            owner_player_id=reg.owner_player_id,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            allowed_colors=allowed_colors,
            required_traits=required_traits,
            required_characters=required_characters,
            required_name_contains=required_name_contains,
            required_skill_text_contains=required_skill_text_contains,
            required_card_types=required_card_types,
            min_cost=self._resolve_effect_int_param(state, reg, "min_cost", default=-1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
        )
        if played:
            self._checkpoint(state, "effect_auto_choose_play_up_to_n_from_owner_deck_or_hand_or_secondary_on_self_left_battle")
            return
        secondary_amount = self._resolve_effect_int_param(state, reg, "secondary_amount", default=1)
        if secondary_amount <= 0:
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        secondary_mode = str(reg.handler_params.get("secondary_mode", "")).strip().lower()
        if secondary_mode == "draw":
            drew = 0
            for _ in range(secondary_amount):
                if not owner.deck:
                    break
                self._draw_one(state, reg.owner_player_id)
                drew += 1
            if drew <= 0:
                return
            self._checkpoint(state, "effect_auto_choose_play_up_to_n_from_owner_deck_or_hand_or_secondary_on_self_left_battle")
            return
        if secondary_mode == "opponent_discard":
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            if opponent is None or not opponent.hand:
                return
            discarded_any = False
            for _ in range(min(secondary_amount, len(opponent.hand))):
                discarded = opponent.hand.pop(0)
                opponent.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=opponent.player_id, card=discarded, source_zone="hand")
                discarded_any = True
            if not discarded_any:
                return
            self._checkpoint(state, "effect_auto_choose_play_up_to_n_from_owner_deck_or_hand_or_secondary_on_self_left_battle")

    def _build_owner_combo_event_probe(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        event: EffectEvent,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        owner = state.players.get(owner_player_id)
        if owner is None:
            return None
        combo_instance_id = int(event.payload.get("source_instance_id") or -1)
        live_combo_card = next((card for card in owner.combo_area if card.instance_id == combo_instance_id), None)
        if live_combo_card is not None:
            return owner, live_combo_card, live_combo_card
        combo_card_id = int(event.payload.get("source_card_id") or 0)
        if combo_card_id <= 0:
            return None
        combo_runtime = self._resolve_card_runtime_data(combo_card_id)
        combo_probe = CardInstance(
            instance_id=combo_instance_id if combo_instance_id > 0 else 0,
            card_id=combo_card_id,
            owner_id=owner_player_id,
            card_type=str(combo_runtime.card_type or "BATTLE"),
            color=str(combo_runtime.color or "") or None,
            power=int(combo_runtime.power or 0),
            energy_cost=combo_runtime.energy_cost,
            skill_text_raw=str(combo_runtime.skill_text_raw or ""),
            traits=tuple(combo_runtime.traits or ()),
            characters=tuple(combo_runtime.characters or ()),
            keywords=tuple(combo_runtime.keywords or ()),
            has_counter=bool(combo_runtime.has_counter),
            has_activate_main=bool(combo_runtime.has_activate_main),
            has_activate_battle=bool(combo_runtime.has_activate_battle),
            has_auto=bool(combo_runtime.has_auto),
            has_permanent=bool(combo_runtime.has_permanent),
            has_draw=bool(combo_runtime.has_draw),
            has_barrier=bool(combo_runtime.has_barrier),
        )
        return owner, None, combo_probe

    def _card_is_skillless(self, card: CardInstance) -> bool:
        keywords = {str(k).strip().lower() for k in (card.keywords or ()) if str(k).strip()}
        if "skill-less" in keywords or "skill less" in keywords:
            return True
        runtime = self._resolve_card_runtime_data(card.card_id)
        runtime_keywords = {str(k).strip().lower() for k in (runtime.keywords or ()) if str(k).strip()}
        if "skill-less" in runtime_keywords or "skill less" in runtime_keywords:
            return True
        raw_skill_text = str(getattr(card, "skill_text_raw", "") or runtime.skill_text_raw or "").strip().lower()
        if raw_skill_text in {"", "-"}:
            return True
        return not any(
            (
                bool(runtime.has_counter),
                bool(runtime.has_activate_main),
                bool(runtime.has_activate_battle),
                bool(runtime.has_auto),
                bool(runtime.has_permanent),
                bool(runtime.has_draw),
                bool(runtime.has_awaken),
                bool(runtime.keywords),
            )
        )

    def _match_owner_combo_event(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> tuple[PlayerState, CardInstance | None, CardInstance] | None:
        if event.name != "card_comboed" or event.actor_player_id != reg.owner_player_id:
            return None
        match = self._build_owner_combo_event_probe(state, owner_player_id=reg.owner_player_id, event=event)
        if match is None:
            return None
        owner, live_combo_card, combo_probe = match
        required_from = str(reg.handler_params.get("event_requires_comboed_from", "")).strip().lower()
        if required_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_from:
                return None
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_keywords = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_required_keywords", "")).replace("|", ",").split(",")
            if part.strip()
        }
        excluded_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("event_excluded_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("event_required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("event_required_card_type", "")).replace("|", ",").split(",")
            if part.strip()
        }
        if not self._card_matches_effect_filters(
            combo_probe,
            allowed_colors=allowed_colors,
            required_traits=required_traits,
            required_characters=required_characters,
            required_name_contains=required_name_contains,
            required_card_types=required_card_types,
        ):
            return None
        event_min_cost = self._resolve_effect_int_param(state, reg, "event_min_energy_cost", default=-1)
        event_max_cost = self._resolve_effect_int_param(state, reg, "event_max_energy_cost", default=-1)
        event_exact_cost = self._resolve_effect_int_param(state, reg, "event_exact_energy_cost", default=-1)
        combo_cost = int(combo_probe.energy_cost or -1)
        if event_exact_cost >= 0 and combo_cost != event_exact_cost:
            return None
        if event_min_cost >= 0 and combo_cost < event_min_cost:
            return None
        if event_max_cost >= 0 and combo_cost > event_max_cost:
            return None
        if bool(reg.handler_params.get("event_requires_skill_less", False)) and not self._card_is_skillless(combo_probe):
            return None
        return owner, live_combo_card, combo_probe

