    def _handle_activate_deal_damage_to_opponent_per_owner_matching_battle_colors_and_optionally_win(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_owner_battle_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        total_colors = 0
        for card in owner.battle_area:
            runtime = self._resolve_card_runtime_data(card.card_id)
            card_traits = {
                part.strip().lower()
                for part in tuple(runtime.traits or card.traits or ())
                if part.strip()
            }
            card_characters = {
                part.strip().lower()
                for part in tuple(runtime.characters or card.characters or ())
                if part.strip()
            }
            if required_traits and (card_traits | card_characters).isdisjoint(required_traits):
                continue
            colors = {
                part.strip().lower()
                for part in str(runtime.color or card.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            total_colors += len(colors)
        colors_per_damage = self._resolve_effect_int_param(state, reg, "colors_per_damage", default=1)
        damage_per = self._resolve_effect_int_param(state, reg, "damage_per", default=1)
        max_damage = self._resolve_effect_int_param(state, reg, "max_damage", default=-1)
        damage_amount = 0
        if colors_per_damage > 0 and damage_per > 0:
            damage_amount = (total_colors // colors_per_damage) * damage_per
            if max_damage >= 0:
                damage_amount = min(damage_amount, max_damage)
        if damage_amount > 0:
            self._deal_damage_to_player(state, self._opponent_of(reg.owner_player_id), damage_amount)
        win_threshold = self._resolve_effect_int_param(state, reg, "win_if_owner_in_play_matching_count_at_least", default=-1)
        if win_threshold >= 0:
            win_required_traits = {
                part.strip().lower()
                for part in str(reg.handler_params.get("win_required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            }
            win_requires_multicolor = bool(reg.handler_params.get("win_requires_multicolor", False))
            in_play_count = 0
            for zone_card in [*owner.battle_area, *owner.unison_area]:
                runtime = self._resolve_card_runtime_data(zone_card.card_id)
                card_traits = {
                    part.strip().lower()
                    for part in tuple(runtime.traits or zone_card.traits or ())
                    if part.strip()
                }
                card_characters = {
                    part.strip().lower()
                    for part in tuple(runtime.characters or zone_card.characters or ())
                    if part.strip()
                }
                if win_required_traits and (card_traits | card_characters).isdisjoint(win_required_traits):
                    continue
                colors = {
                    part.strip().lower()
                    for part in str(runtime.color or zone_card.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
                if win_requires_multicolor and len(colors) < 2:
                    continue
                in_play_count += 1
            if in_play_count >= win_threshold:
                state.winner_id = reg.owner_player_id
        self._checkpoint(state, "effect_activate_deal_damage_to_opponent_per_owner_matching_battle_colors_and_optionally_win")

    def _handle_activate_draw_n_and_place_up_to_n_from_owner_deck_or_drop_under_owner_leader(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=0)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)

        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            self._checkpoint(state, "effect_activate_draw_n_and_place_up_to_n_from_owner_deck_or_drop_under_owner_leader")
            return

        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_card_type", "")).replace("|", ",").split(",")
            if part.strip()
        }
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        source_pool = str(reg.handler_params.get("source_pool", "deck_or_drop")).strip().lower()
        pools: list[str] = []
        if source_pool in {"deck", "deck_or_drop"}:
            pools.append("deck")
        if source_pool in {"drop", "deck_or_drop"}:
            pools.append("drop")

        moved = 0
        for pool in pools:
            while moved < max_targets:
                chosen_card: CardInstance | None = None
                placed_from = pool
                if pool == "deck":
                    chosen_index = -1
                    for i, card_id in enumerate(owner.deck):
                        candidate = self._create_card_instance(next_instance_id=0, card_id=int(card_id), owner_id=reg.owner_player_id)
                        if max_cost >= 0 and int(candidate.energy_cost or 0) > max_cost:
                            continue
                        if not self._card_matches_effect_filters(
                            candidate,
                            allowed_colors=allowed_colors,
                            required_traits=required_traits,
                            required_characters=required_characters,
                            required_name_contains=required_name_contains,
                            required_card_types=required_card_types,
                        ):
                            continue
                        chosen_index = i
                        break
                    if chosen_index < 0:
                        break
                    card_id = int(owner.deck.pop(chosen_index))
                    chosen_card = self._create_card_instance(
                        next_instance_id=state.next_instance_id,
                        card_id=card_id,
                        owner_id=reg.owner_player_id,
                    )
                    state.next_instance_id += 1
                else:
                    chosen_index = -1
                    for i, card in enumerate(owner.drop):
                        if max_cost >= 0 and int(card.energy_cost or 0) > max_cost:
                            continue
                        if not self._card_matches_effect_filters(
                            card,
                            allowed_colors=allowed_colors,
                            required_traits=required_traits,
                            required_characters=required_characters,
                            required_name_contains=required_name_contains,
                            required_card_types=required_card_types,
                        ):
                            continue
                        chosen_index = i
                        break
                    if chosen_index < 0:
                        break
                    chosen_card = owner.drop.pop(chosen_index)

                self._place_card_under_host(owner.leader_area, chosen_card)
                self._emit_card_placed_under_card(
                    state,
                    owner_player_id=reg.owner_player_id,
                    host=owner.leader_area,
                    host_zone="leader",
                    card=chosen_card,
                    source_zone=placed_from,
                )
                moved += 1

        self._checkpoint(state, "effect_activate_draw_n_and_place_up_to_n_from_owner_deck_or_drop_under_owner_leader")

    def _handle_activate_draw_n_discard_n_and_place_up_to_n_from_owner_drop_under_owner_leader_then_switch_self_active_on_turn_end(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return

        amount = self._resolve_effect_int_param(state, reg, "amount", default=1)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)

        discard_count = self._resolve_effect_int_param(state, reg, "discard_count", default=0)
        for _ in range(max(discard_count, 0)):
            if not owner.hand:
                break
            discarded = owner.hand.pop(0)
            owner.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=reg.owner_player_id, card=discarded, source_zone="hand")

        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta != 0 and source.card_type in {"UNISON", "Z-UNISON"}:
            source.markers += marker_delta

        leader_runtime = self._resolve_card_runtime_data(owner.leader_area.card_id)
        leader_colors = {
            part.strip().lower()
            for part in str(owner.leader_area.color or leader_runtime.color or "").replace("/", ",").split(",")
            if part.strip()
        }
        allowed_bonus_leader_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("bonus_leader_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        leader_traits = {part.strip().lower() for part in (leader_runtime.traits or owner.leader_area.traits or ()) if part.strip()}
        leader_characters = {part.strip().lower() for part in (leader_runtime.characters or owner.leader_area.characters or ()) if part.strip()}
        leader_name = str(leader_runtime.card_name or getattr(owner.leader_area, "card_name", "") or "").upper()
        bonus_leader_required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("bonus_leader_required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        bonus_leader_required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("bonus_leader_required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        bonus_leader_required_name_contains = str(reg.handler_params.get("bonus_leader_required_name_contains", "")).strip().upper()

        bonus_leader_ok = True
        if allowed_bonus_leader_colors and leader_colors.isdisjoint(allowed_bonus_leader_colors):
            bonus_leader_ok = False
        if bool(reg.handler_params.get("bonus_leader_requires_mono")) and len(leader_colors) != 1:
            bonus_leader_ok = False
        if bonus_leader_required_traits and leader_traits.isdisjoint(bonus_leader_required_traits):
            bonus_leader_ok = False
        if bonus_leader_required_characters and leader_characters.isdisjoint(bonus_leader_required_characters):
            bonus_leader_ok = False
        if bonus_leader_required_name_contains and bonus_leader_required_name_contains not in leader_name:
            bonus_leader_ok = False

        if bonus_leader_ok:
            max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
            if max_targets > 0:
                allowed_colors = {
                    part.strip().lower()
                    for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                    if part.strip()
                }
                required_traits = {
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
                    if part.strip()
                }
                required_characters = {
                    part.strip().lower()
                    for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
                    if part.strip()
                }
                required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
                required_card_type = str(reg.handler_params.get("required_card_type", "")).strip().upper()
                candidates = [
                    (idx, card)
                    for idx, card in enumerate(owner.drop)
                    if self._card_matches_effect_filters(
                        card,
                        allowed_colors=allowed_colors,
                        required_traits=required_traits,
                        required_characters=required_characters,
                        required_name_contains=required_name_contains,
                        required_card_types={required_card_type} if required_card_type else None,
                    )
                ]
                chosen_indexes = self._choose_effect_target_indexes(
                    state,
                    reg,
                    [card for _, card in candidates],
                    max_targets,
                    str(reg.handler_params.get("target_policy", "first")),
                ) if candidates else []
                removed = 0
                for chosen in chosen_indexes:
                    source_idx, _ = candidates[chosen]
                    moved = owner.drop.pop(source_idx - removed)
                    removed += 1
                    self._place_card_under_host(owner.leader_area, moved)
                    self._emit_card_placed_under_card(
                        state,
                        owner_player_id=reg.owner_player_id,
                        host=owner.leader_area,
                        host_zone="leader",
                        card=moved,
                        source_zone="drop",
                    )
            self._schedule_delayed_active_switch(
                state,
                owner_player_id=reg.owner_player_id,
                target_instance_id=source.instance_id,
                trigger_player_id=state.active_player,
            )

        self._checkpoint(state, "effect_activate_draw_n_discard_n_and_place_up_to_n_from_owner_drop_under_owner_leader_then_switch_self_active_on_turn_end")

    def _handle_activate_place_up_to_n_opponent_battle_under_source_host_and_switch_host_active_on_turn_end(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if str(event.payload.get("source_zone") or "") != "battle_under":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source_entry = self._find_battle_under_entry(owner, source_instance_id=int(event.payload.get("source_instance_id") or -1))
        if source_entry is None:
            return
        _flat_index, host, _under_index, _source = source_entry
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if opponent is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        kept: list[CardInstance] = []
        moved = 0
        for target in list(opponent.battle_area):
            if moved >= max_targets:
                kept.append(target)
                continue
            if target.hidden_mode or self._card_currently_has_barrier(target):
                kept.append(target)
                continue
            self._place_card_under_host(host, target)
            moved += 1
        if moved <= 0:
            return
        opponent.battle_area = [target for target in opponent.battle_area if target in kept]
        self._register_battle_under_card_effects(state, player_id=reg.owner_player_id)
        self._schedule_delayed_active_switch(
            state,
            owner_player_id=reg.owner_player_id,
            target_instance_id=host.instance_id,
            trigger_player_id=state.active_player,
        )
        self._checkpoint(state, "effect_activate_place_up_to_n_opponent_battle_under_source_host_and_switch_host_active_on_turn_end")

    def _handle_activate_draw_n_and_ko_up_to_n_opponent_battle_by_source_host_power(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source_entry = self._find_battle_under_entry(owner, source_instance_id=int(event.payload.get("source_instance_id") or -1))
        if source_entry is None:
            return
        _flat_index, host, _under_index, _source = source_entry
        draw_count = self._resolve_effect_int_param(state, reg, "amount", default=0)
        for _ in range(max(draw_count, 0)):
            self._draw_one_from_registration(state, reg)
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets > 0:
            opponent_id = self._opponent_of(reg.owner_player_id)
            opponent = state.players.get(opponent_id)
            if opponent is not None:
                host_power = int(getattr(host, "power", 0) or 0)
                candidates = [card for card in opponent.battle_area if int(card.power or 0) <= host_power]
                if candidates:
                    indexes = self._choose_effect_target_indexes(
                        state,
                        reg,
                        candidates,
                        max_targets,
                        str(reg.handler_params.get("target_policy", "first")),
                    )
                    target_ids = {candidates[idx].instance_id for idx in indexes}
                    for tid in list(target_ids):
                        self._ko_card(state, opponent_id, "battle", tid)
        self._checkpoint(state, "effect_activate_draw_n_and_ko_up_to_n_opponent_battle_by_source_host_power")

    def _handle_activate_schedule_opponent_non_leader_skill_draw_replacement_next_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        exists = any(
            int(row.owner_player_id) == int(reg.owner_player_id)
            and int(row.affected_player_id) == int(opponent_id)
            and int(row.expires_on_turn_end_player_id) == int(opponent_id)
            for row in state.active_skill_draw_replacements
        )
        if not exists:
            state.active_skill_draw_replacements.append(
                DelayedSkillDrawReplacement(
                    owner_player_id=reg.owner_player_id,
                    affected_player_id=opponent_id,
                    expires_on_turn_end_player_id=opponent_id,
                )
            )
        if bool(reg.handler_params.get("restrict_activate_self_copies_next_turn", False)):
            signature = self._handler_params_signature(reg.handler_params)
            exists_activate = any(
                int(row.owner_player_id) == int(reg.owner_player_id)
                and int(row.restricted_card_id) == int(reg.source_card_id)
                and str(row.trigger) == str(reg.trigger)
                and str(row.handler_id) == str(reg.handler_id)
                and tuple(row.handler_params_signature) == signature
                for row in state.scheduled_activate_skill_restrictions
            )
            if not exists_activate:
                state.scheduled_activate_skill_restrictions.append(
                    DelayedActivateSkillRestriction(
                        owner_player_id=reg.owner_player_id,
                        restricted_card_id=reg.source_card_id,
                        trigger=str(reg.trigger),
                        handler_id=str(reg.handler_id),
                        handler_params_signature=signature,
                    )
                )
        self._checkpoint(state, "effect_activate_schedule_opponent_non_leader_skill_draw_replacement_next_turn")

    def _handle_activate_play_up_to_n_from_owner_z_deck_or_z_energy(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        allowed_colors = {c.strip() for c in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",") if c.strip()}
        required_traits = {t.strip() for t in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",") if t.strip()}
        required_characters = {t.strip() for t in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",") if t.strip()}
        negate_skills = bool(reg.handler_params.get("negate_skills", False))

        remaining = max_targets

        def _matches_runtime(runtime: CardRuntimeData) -> bool:
            if max_cost >= 0 and (runtime.energy_cost is None or runtime.energy_cost != max_cost):
                return False
            runtime_colors = {p.strip().lower() for p in str(runtime.color or "").replace("/", ",").split(",") if p.strip()}
            runtime_traits = {part.strip().lower() for part in (runtime.traits or ()) if part.strip()}
            runtime_characters = {part.strip().lower() for part in (runtime.characters or ()) if part.strip()}
            if allowed_colors and runtime_colors.isdisjoint(allowed_colors):
                return False
            if required_traits and runtime_traits.isdisjoint(required_traits):
                return False
            if required_characters and runtime_characters.isdisjoint(required_characters):
                return False
            return True

        for idx, row in list(enumerate(owner.z_deck)):
            if remaining <= 0:
                break
            if not row.face_up:
                continue
            runtime = self._resolve_card_runtime_data(row.card_id)
            if not _matches_runtime(runtime):
                continue
            owner.z_deck.pop(idx)
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=row.card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            if negate_skills:
                card.keywords = ()
                card.counter_modes = ()
                card.has_counter = False
                card.has_counter_attack = False
                card.has_counter_battle_card_attack = False
                card.has_counter_play = False
                card.has_counter_counter = False
                card.has_activate_main = False
                card.has_activate_battle = False
                card.has_auto = False
                card.has_permanent = False
                card.has_draw = False
                card.max_draw = None
                card.auto_once_per_turn = False
                card.auto_draw_on_play = False
                card.auto_draw_on_attack = False
                card.has_barrier = False
            owner.battle_area.append(card)
            if not negate_skills:
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "z_deck",
                },
            )
            remaining -= 1

        idx = 0
        while remaining > 0 and idx < len(owner.z_energy):
            card = owner.z_energy[idx]
            runtime = self._resolve_card_runtime_data(card.card_id)
            if not _matches_runtime(runtime):
                idx += 1
                continue
            card = owner.z_energy.pop(idx)
            if negate_skills:
                card.keywords = ()
                card.counter_modes = ()
                card.has_counter = False
                card.has_counter_attack = False
                card.has_counter_battle_card_attack = False
                card.has_counter_play = False
                card.has_counter_counter = False
                card.has_activate_main = False
                card.has_activate_battle = False
                card.has_auto = False
                card.has_permanent = False
                card.has_draw = False
                card.max_draw = None
                card.auto_once_per_turn = False
                card.auto_draw_on_play = False
                card.auto_draw_on_attack = False
                card.has_barrier = False
            owner.battle_area.append(card)
            if not negate_skills:
                self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "z_energy",
                },
            )
            remaining -= 1

        if remaining < max_targets:
            self._checkpoint(state, "effect_activate_play_up_to_n_from_owner_z_deck_or_z_energy")

    def _handle_activate_buff_owner_battle_cards(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "skill_activated":
            return
        if not self._effect_requirements_met(state, reg):
            return
        if reg.trigger == "self_activate_extra_from_hand":
            required_skill_kind = "activate_extra_from_hand"
        elif reg.trigger == "self_activate_battle":
            required_skill_kind = "activate_battle"
        else:
            required_skill_kind = "activate_main"
        if str(event.payload.get("skill_kind") or "") != required_skill_kind:
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        amount = self._resolve_effect_int_param(state, reg, "amount", default=0)
        for _ in range(max(amount, 0)):
            self._draw_one_from_registration(state, reg)
        marker_delta = self._resolve_effect_int_param(state, reg, "marker_delta", default=0)
        if marker_delta != 0 and source.card_type in {"UNISON", "Z-UNISON"}:
            source.markers += marker_delta
        raw_colors = str(reg.handler_params.get("allowed_colors", ""))
        allowed_colors = {c.strip() for c in raw_colors.replace("|", ",").replace("/", ",").split(",") if c.strip()}
        raw_traits = str(reg.handler_params.get("required_traits", ""))
        required_traits = {t.strip() for t in raw_traits.replace("|", ",").split(",") if t.strip()}
        raw_all_traits = str(reg.handler_params.get("required_all_traits", ""))
        required_all_traits = {t.strip() for t in raw_all_traits.replace("|", ",").split(",") if t.strip()}
        raw_characters = str(reg.handler_params.get("required_characters", ""))
        required_characters = {t.strip() for t in raw_characters.replace("|", ",").split(",") if t.strip()}
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_skill_text_contains = str(reg.handler_params.get("required_skill_text_contains", "")).strip().lower()
        target_scope = str(reg.handler_params.get("target_scope", "owner_battle")).strip().lower()
        pool = list(owner.battle_area)
        if target_scope == "owner_cards":
            pool = [owner.leader_area] + list(owner.battle_area) + list(owner.unison_area)
        candidates = [
            card
            for card in pool
            if self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_all_traits=required_all_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_skill_text_contains=required_skill_text_contains,
            )
        ]
        if not candidates:
            return
        policy = str(reg.handler_params.get("target_policy", "first")).strip().lower()
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=0)
        if policy == "all":
            max_targets = len(candidates)
        elif max_targets <= 0:
            max_targets = 1
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        if not indexes:
            return
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=0)
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        grant_keywords = [
            part.strip()
            for part in str(reg.handler_params.get("grant_keywords", "")).replace("|", ",").split(",")
            if part.strip()
        ]
        keyword_duration = str(reg.handler_params.get("keyword_duration", "turn")).strip().lower()
        for idx in indexes:
            target = candidates[idx]
            if delta:
                self._apply_temporary_power_delta(state, card=target, delta=delta, reason="effect_activate_owner_battle_buff")
            for keyword in ([grant_keyword] if grant_keyword else []) + grant_keywords:
                if keyword_duration == "opponent_turn":
                    self._append_temporary_keyword(target, keyword, duration="delayed")
                    state.delayed_keyword_clears.append(
                        DelayedKeywordClear(
                            owner_player_id=reg.owner_player_id,
                            target_instance_id=target.instance_id,
                            trigger_player_id=self._opponent_of(reg.owner_player_id),
                            keyword=keyword,
                        )
                    )
                elif keyword_duration == "battle":
                    self._append_temporary_keyword(target, keyword, duration="battle")
                else:
                    self._append_temporary_keyword(target, keyword, duration="turn")
        if bool(reg.handler_params.get("restrict_activate_self_copies_next_turn", False)):
            state.scheduled_activate_skill_restrictions.append(
                DelayedActivateSkillRestriction(
                    owner_player_id=reg.owner_player_id,
                    restricted_card_id=reg.source_card_id,
                    trigger=str(reg.trigger),
                    handler_id=str(reg.handler_id),
                    handler_params_signature=self._handler_params_signature(reg.handler_params),
                )
            )
        self._checkpoint(state, "effect_activate_buff_owner_battle_cards")

    def _handle_activate_combo_up_to_n_from_owner_hand(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_battle":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        exact_combo_cost = self._resolve_effect_int_param(state, reg, "exact_combo_cost", default=-1)
        selected_indexes: list[int] = []
        for idx, card in enumerate(owner.hand):
            if "BATTLE" not in str(getattr(card, "card_type", "")).upper():
                continue
            if exact_combo_cost >= 0 and int(getattr(card, "combo_cost", -1) or -1) != exact_combo_cost:
                continue
            if not self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_card_types={"BATTLE"},
            ):
                continue
            selected_indexes.append(idx)
            if len(selected_indexes) >= max_targets:
                break
        if not selected_indexes:
            return
        removed = 0
        for idx in selected_indexes:
            combo_card = owner.hand.pop(idx - removed)
            removed += 1
            combo_card.comboed_from = "hand"
            owner.combo_area.append(combo_card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="combo", card=combo_card)
            self._emit_effect_event(
                state,
                name="card_comboed",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": combo_card.instance_id,
                    "source_card_id": combo_card.card_id,
                    "source_zone": "combo",
                    "comboed_from": "hand",
                },
            )
        if bool(reg.handler_params.get("negate_self_skill_for_game", False)):
            source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
            if source is not None:
                source.temporary_keyword_skills_negated = True
                source.temporary_skills_negated = True
        self._checkpoint(state, "effect_activate_combo_up_to_n_from_owner_hand")

