    def _handle_auto_restrict_up_to_n_opponent_battle_skills_while_self_in_battle_on_field_extra_placed(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "field_extra_placed":
            return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=-1,
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        opponent_id = self._opponent_of(reg.owner_player_id)
        for target in targets:
            if not self._add_permanent_skill_activation_restriction(
                state,
                owner_player_id=opponent_id,
                restricted_card_id=target.card_id,
                restricted_instance_id=target.instance_id,
                source_instance_id=reg.source_instance_id,
                scope="any",
            ):
                continue
            state.effect_registry.append(
                EffectRegistration(
                    effect_id=state.next_effect_id,
                    owner_player_id=reg.owner_player_id,
                    source_instance_id=reg.source_instance_id,
                    source_card_id=reg.source_card_id,
                    source_zone="battle",
                    trigger="self_left_battle_area",
                    handler_id="auto_clear_target_skill_activation_restriction_on_self_left_battle",
                    handler_params={
                        "target_owner_player_id": opponent_id,
                        "target_instance_id": target.instance_id,
                    },
                    source_skill_text=reg.source_skill_text,
                    source_card_number=reg.source_card_number,
                )
            )
            state.next_effect_id += 1
        self._checkpoint(state, "effect_auto_restrict_up_to_n_opponent_battle_skills_while_self_in_battle_on_field_extra_placed")

    def _handle_auto_grant_keyword_to_up_to_n_owner_battle_while_self_in_battle_on_field_extra_placed(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "field_extra_placed":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        grant_keyword = str(reg.handler_params.get("grant_keyword", "") or "").strip()
        if not grant_keyword:
            return
        required_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "") or "").strip().upper()
        candidates = [
            card
            for card in owner.battle_area
            if self._card_matches_effect_filters(
                card,
                allowed_colors=required_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
            )
        ]
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, str(reg.handler_params.get("target_policy", "first")))
        if not indexes:
            return
        for idx in indexes:
            target = candidates[idx]
            if grant_keyword not in tuple(target.delayed_temporary_keywords or ()):
                target.delayed_temporary_keywords = tuple(list(target.delayed_temporary_keywords or ()) + [grant_keyword])
            state.effect_registry.append(
                EffectRegistration(
                    effect_id=state.next_effect_id,
                    owner_player_id=reg.owner_player_id,
                    source_instance_id=reg.source_instance_id,
                    source_card_id=reg.source_card_id,
                    source_zone="battle",
                    trigger="self_left_battle_area",
                    handler_id="auto_clear_target_keyword_on_self_left_battle",
                    handler_params={
                        "target_owner_player_id": reg.owner_player_id,
                        "target_instance_id": target.instance_id,
                        "grant_keyword": grant_keyword,
                    },
                    source_skill_text=reg.source_skill_text,
                    source_card_number=reg.source_card_number,
                )
            )
            state.next_effect_id += 1
        self._checkpoint(state, "effect_auto_grant_keyword_to_up_to_n_owner_battle_while_self_in_battle_on_field_extra_placed")

    def _handle_auto_clear_target_keyword_on_self_left_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_left_battle_area":
            return
        owner = state.players.get(int(reg.handler_params.get("target_owner_player_id") or reg.owner_player_id))
        if owner is None:
            return
        target_instance_id = int(reg.handler_params.get("target_instance_id") or -1)
        target = self._find_board_card_by_instance(owner, target_instance_id)
        if target is None:
            return
        keyword = str(reg.handler_params.get("grant_keyword", "") or "").strip().lower()
        if not keyword:
            return
        filtered = tuple(item for item in tuple(target.delayed_temporary_keywords or ()) if str(item).strip().lower() != keyword)
        if filtered != target.delayed_temporary_keywords:
            target.delayed_temporary_keywords = filtered
            self._checkpoint(state, "effect_auto_clear_target_keyword_on_self_left_battle")

    def _handle_auto_clear_target_skill_activation_restriction_on_self_left_battle(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_left_battle_area":
            return
        target_owner_player_id = int(reg.handler_params.get("target_owner_player_id") or self._opponent_of(reg.owner_player_id))
        target_instance_id = int(reg.handler_params.get("target_instance_id") or -1)
        filtered = [
            row
            for row in state.permanent_skill_activation_restrictions
            if not (
                int(row.owner_player_id) == target_owner_player_id
                and int(getattr(row, "restricted_instance_id", -1) or -1) == target_instance_id
                and int(getattr(row, "source_instance_id", -1) or -1) == reg.source_instance_id
            )
        ]
        if len(filtered) != len(state.permanent_skill_activation_restrictions):
            state.permanent_skill_activation_restrictions = filtered
            self._checkpoint(state, "effect_auto_clear_target_skill_activation_restriction_on_self_left_battle")

    def _handle_auto_rest_self_on_owner_opponent_skill_play_overcost_battle_reduce_power(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        actor_id = event.actor_player_id
        if actor_id in {None, reg.owner_player_id}:
            return
        if str(event.payload.get("source_zone") or "") != "battle":
            return
        played_from = str(event.payload.get("played_from") or "").strip().lower()
        if played_from in {"", "hand"}:
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(actor_id)
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None or source.resting:
            return
        target_instance = int(event.payload.get("source_instance_id") or -1)
        target = self._find_by_instance(opponent, "battle", target_instance)
        if target is None:
            return
        target_cost = target.energy_cost
        if target_cost is None:
            target_cost = self._resolve_card_runtime_data(target.card_id).energy_cost
        if int(target_cost or 0) <= len(opponent.energy):
            return
        source.resting = True
        delta = self._resolve_effect_int_param(state, reg, "power_delta", default=-10000)
        if delta == 0:
            return
        self._modify_card_power(state, card=target, delta=delta, reason="effect_power_reduce")
        self._run_confirmative_rule_processing(state)
        self._checkpoint(state, "effect_auto_rest_self_on_owner_opponent_skill_play_overcost_battle_reduce_power")

    def _handle_auto_rest_self_on_owner_opponent_skill_play_overcost_battle_switch_target_rest(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        actor_id = event.actor_player_id
        if actor_id in {None, reg.owner_player_id}:
            return
        if str(event.payload.get("source_zone") or "") != "battle":
            return
        played_from = str(event.payload.get("played_from") or "").strip().lower()
        if played_from in {"", "hand"}:
            return
        owner = state.players.get(reg.owner_player_id)
        opponent = state.players.get(actor_id)
        if owner is None or opponent is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None or source.resting:
            return
        target_instance = int(event.payload.get("source_instance_id") or -1)
        target = self._find_by_instance(opponent, "battle", target_instance)
        if target is None:
            return
        target_cost = target.energy_cost
        if target_cost is None:
            target_cost = self._resolve_card_runtime_data(target.card_id).energy_cost
        if int(target_cost or 0) <= len(opponent.energy):
            return
        source.resting = True
        if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
            target.resting = True
        else:
            self._checkpoint(state, "effect_opponent_rest_prevented_by_protection")
        self._checkpoint(state, "effect_auto_rest_self_on_owner_opponent_skill_play_overcost_battle_switch_target_rest")

    def _handle_auto_play_up_to_n_from_owner_deck_on_play(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_played":
            return
        if not self._effect_requirements_met(state, reg):
            return
        required_from = str(reg.handler_params.get("requires_played_from", "")).strip().lower()
        if required_from:
            played_from = str(event.payload.get("played_from") or "").strip().lower()
            if played_from != required_from:
                return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.deck:
            return
        discard_from_hand_before = self._resolve_effect_int_param(state, reg, "discard_from_hand_before", default=0)
        if discard_from_hand_before > 0:
            if len(owner.hand) < discard_from_hand_before:
                return
            for _ in range(discard_from_hand_before):
                discarded = owner.hand.pop(0)
                owner.drop.append(discarded)
                self._emit_card_placed_into_drop(state, owner_player_id=owner.player_id, card=discarded, source_zone="hand")
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_power = self._resolve_effect_int_param(state, reg, "max_power", default=-1)
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("|", ",").replace("/", ",").split(",") if c.strip()}
        raw_traits = str(reg.handler_params.get("required_traits", "")).strip().lower()
        required_traits = {t.strip() for t in raw_traits.replace("|", ",").split(",") if t.strip()}
        raw_characters = str(reg.handler_params.get("required_characters", "")).strip().lower()
        required_characters = {t.strip() for t in raw_characters.replace("|", ",").split(",") if t.strip()}
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_card_type", "BATTLE")).replace("|", ",").split(",")
            if part.strip()
        }
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        chosen_indexes: list[int] = []
        for i, card_id in enumerate(owner.deck):
            runtime = self._resolve_card_runtime_data(card_id)
            temp_card = CardInstance(
                instance_id=0,
                card_id=card_id,
                owner_id=reg.owner_player_id,
                card_type=str(runtime.card_type or ""),
                color=str(runtime.color or ""),
                power=int(runtime.power or 0),
                traits=tuple(runtime.traits or ()),
                characters=tuple(runtime.characters or ()),
                skill_text_raw=str(runtime.skill_text_raw or ""),
            )
            setattr(temp_card, "card_name", str(runtime.card_name or ""))
            if not self._card_matches_effect_filters(
                temp_card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_card_types=required_card_types or {"BATTLE"},
                min_power=-1,
            ):
                continue
            if max_power >= 0 and int(runtime.power or 0) > max_power:
                continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= max_targets:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            card_id = owner.deck.pop(idx - removed)
            removed += 1
            card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=reg.owner_player_id)
            state.next_instance_id += 1
            card.resting = rest_mode
            owner.battle_area.append(card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "deck",
                },
            )
        if bool(reg.handler_params.get("shuffle_deck_after", False)) and owner.deck:
            random.Random(0).shuffle(owner.deck)
        self._checkpoint(state, "effect_auto_play_up_to_n_from_owner_deck_on_play")

    def _handle_auto_play_up_to_n_from_owner_hand_on_self_combo(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_from:
                return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.hand:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        max_cost = self._resolve_effect_int_param(state, reg, "max_cost", default=-1)
        exact_combo_cost = self._resolve_effect_int_param(state, reg, "exact_combo_cost", default=-1)
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("|", ",").replace("/", ",").split(",") if c.strip()}
        raw_traits = str(reg.handler_params.get("required_traits", "")).strip().lower()
        required_traits = {t.strip() for t in raw_traits.replace("|", ",").split(",") if t.strip()}
        raw_characters = str(reg.handler_params.get("required_characters", "")).strip().lower()
        required_characters = {t.strip() for t in raw_characters.replace("|", ",").split(",") if t.strip()}
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        rest_mode = bool(reg.handler_params.get("rest_mode", False))
        chosen_indexes: list[int] = []
        for i, c in enumerate(owner.hand):
            if "BATTLE" not in (c.card_type or "").upper():
                continue
            if max_cost >= 0 and (c.energy_cost is None or c.energy_cost > max_cost):
                continue
            if exact_combo_cost >= 0 and int(getattr(c, "combo_cost", -1) or -1) != exact_combo_cost:
                continue
            if not self._card_matches_effect_filters(
                c,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
            ):
                continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= max_targets:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            card = owner.hand.pop(idx - removed)
            removed += 1
            card.resting = rest_mode
            owner.battle_area.append(card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone="battle", card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": "battle",
                    "played_from": "hand",
                },
            )
        self._checkpoint(state, "effect_auto_play_up_to_n_from_owner_hand_on_self_combo")

    def _handle_auto_switch_up_to_n_opponent_battle_rest_on_self_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_from and str(event.payload.get("comboed_from") or "").strip().lower() != required_from:
            return
        if not self._effect_requirements_met(state, reg):
            return
        targets = self._select_opponent_battle_targets(
            state,
            reg,
            max_targets=self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            max_cost=self._resolve_effect_int_param(state, reg, "max_cost", default=-1),
            policy=str(reg.handler_params.get("target_policy", "first")),
        )
        if not targets:
            return
        for target in targets:
            if self._opponent_skill_can_switch_card_to_rest(state, acting_player_id=reg.owner_player_id, target_card=target):
                target.resting = True
        self._checkpoint(state, "effect_auto_switch_up_to_n_opponent_battle_rest_on_self_combo")

    def _handle_auto_grant_keyword_to_owner_battle_on_self_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_from and str(event.payload.get("comboed_from") or "").strip().lower() != required_from:
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        allowed_colors = {
            part.strip().lower()
            for part in str(reg.handler_params.get("allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        required_traits = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_traits", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        candidates = [
            card
            for card in owner.battle_area
            if self._card_matches_effect_filters(
                card,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=required_characters,
                required_name_contains=required_name_contains,
                required_card_types={"BATTLE"},
            )
        ]
        if not candidates:
            return
        indexes = self._choose_effect_target_indexes(
            state,
            reg,
            candidates,
            self._resolve_effect_int_param(state, reg, "max_targets", default=1),
            str(reg.handler_params.get("target_policy", "first")),
        )
        if not indexes:
            return
        grant_keyword = str(reg.handler_params.get("grant_keyword", "")).strip()
        if not grant_keyword:
            return
        for idx in indexes:
            self._append_temporary_keyword(candidates[idx], grant_keyword, duration="battle")
        self._checkpoint(state, "effect_auto_grant_keyword_to_owner_battle_on_self_combo")

    def _handle_auto_switch_up_to_n_owner_energy_active_on_combo(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "card_comboed":
            return
        if int(event.payload.get("source_instance_id") or -1) != reg.source_instance_id:
            return
        required_from = str(reg.handler_params.get("requires_comboed_from", "")).strip().lower()
        if required_from:
            comboed_from = str(event.payload.get("comboed_from") or "").strip().lower()
            if comboed_from != required_from:
                return
        if not self._effect_requirements_met(state, reg):
            return
        if not self._pay_self_combo_skill_cost_if_needed(state, event, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        raw_colors = str(reg.handler_params.get("allowed_colors", "")).strip().lower()
        allowed_colors = {c.strip() for c in raw_colors.replace("/", ",").replace("|", ",").split(",") if c.strip()}
        requires_multicolor = bool(reg.handler_params.get("requires_multicolor", False))
        candidates = [c for c in owner.energy if c.resting]
        if allowed_colors:
            filtered: list[CardInstance] = []
            for c in candidates:
                colors = {p.strip().lower() for p in str(c.color or "").replace("/", ",").split(",") if p.strip()}
                if colors and colors.isdisjoint(allowed_colors):
                    continue
                filtered.append(c)
            candidates = filtered
        if requires_multicolor:
            candidates = [c for c in candidates if "/" in str(c.color or "")]
        if not candidates:
            return
        activated = 0
        for c in candidates:
            if activated >= max_targets:
                break
            if not self._can_switch_card_to_active(c):
                continue
            c.resting = False
            activated += 1
        if activated > 0:
            self._checkpoint(state, "effect_auto_switch_up_to_n_owner_energy_active_on_combo")

