    def _handle_auto_play_up_to_n_named_from_owner_drop_on_self_ko(self, state: GameState, event: EffectEvent, reg: EffectRegistration) -> None:
        if event.name != "card_koed":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None or not owner.drop:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        required_name_contains = str(reg.handler_params.get("required_name_contains", "")).strip().upper()
        chosen_indexes: list[int] = []
        for i, c in enumerate(owner.drop):
            runtime = self._resolve_card_runtime_data(c.card_id)
            runtime_name = str(runtime.card_name or "").upper()
            if required_name_contains and required_name_contains not in runtime_name:
                continue
            chosen_indexes.append(i)
            if len(chosen_indexes) >= max_targets:
                break
        if not chosen_indexes:
            return
        removed = 0
        for idx in chosen_indexes:
            card = owner.drop.pop(idx - removed)
            removed += 1
            target_zone = "battle"
            if "UNISON" in (card.card_type or "").upper():
                target_zone = "unison"
                self._replace_owner_unison_if_needed(state, owner)
                owner.unison_area.append(card)
            else:
                owner.battle_area.append(card)
            self._register_card_effects(state, player_id=reg.owner_player_id, source_zone=target_zone, card=card)
            self._emit_effect_event(
                state,
                name="card_played",
                actor_player_id=reg.owner_player_id,
                payload={
                    "source_instance_id": card.instance_id,
                    "source_card_id": card.card_id,
                    "source_zone": target_zone,
                    "played_from": "drop",
                },
            )
        self._checkpoint(state, "effect_auto_play_up_to_n_named_from_owner_drop_on_self_ko")

    def _handle_activate_copy_battle_power_to_self_for_turn(
        self,
        state: GameState,
        event: EffectEvent,
        reg: EffectRegistration,
    ) -> None:
        if event.name != "skill_activated":
            return
        if str(event.payload.get("skill_kind") or "") != "activate_main":
            return
        if not self._effect_requirements_met(state, reg):
            return
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None:
            return
        max_targets = self._resolve_effect_int_param(state, reg, "max_targets", default=1)
        if max_targets <= 0:
            return
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        candidates = [card for card in owner.battle_area if card.instance_id != source.instance_id]
        if opponent is not None:
            candidates.extend(opponent.battle_area)
        if not bool(reg.handler_params.get("ignores_barrier", False)):
            candidates = [card for card in candidates if not self._card_currently_has_barrier(card)]
        if not candidates:
            return
        policy = str(reg.handler_params.get("target_policy", "first"))
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        if not indexes:
            return
        target = candidates[indexes[0]]
        delta = int(target.power) - int(source.power)
        self._apply_temporary_power_delta(
            state,
            card=source,
            delta=delta,
            reason="activate_copy_battle_power_to_self_for_turn",
        )
        self._checkpoint(state, "effect_activate_copy_battle_power_to_self_for_turn")

    def _select_opponent_battle_targets(
        self,
        state: GameState,
        reg: EffectRegistration,
        *,
        max_targets: int,
        max_cost: int,
        max_power: int = -1,
        policy: str,
    ) -> list[CardInstance]:
        if max_targets <= 0:
            return []
        opponent_id = self._opponent_of(reg.owner_player_id)
        candidates = list(state.players[opponent_id].battle_area)
        if max_cost >= 0:
            candidates = [c for c in candidates if (c.energy_cost or 0) <= max_cost]
        if max_power >= 0:
            candidates = [c for c in candidates if int(c.power or 0) <= max_power]
        if bool(reg.handler_params.get("requires_cost_greater_than_opponent_current_energy", False)):
            opponent_energy = len(state.players[opponent_id].energy)
            candidates = [c for c in candidates if int(c.energy_cost or 0) > opponent_energy]
        if bool(reg.handler_params.get("requires_cost_at_least_opponent_current_energy", False)):
            opponent_energy = len(state.players[opponent_id].energy)
            candidates = [c for c in candidates if int(c.energy_cost or 0) >= opponent_energy]
        if bool(reg.handler_params.get("rest_mode_only", False)):
            candidates = [c for c in candidates if c.resting]
        if not bool(reg.handler_params.get("ignores_barrier", False)):
            candidates = [c for c in candidates if not self._card_currently_has_barrier(c)]
        if not candidates:
            return []
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        return [candidates[i] for i in indexes]

    def _select_opponent_battle_or_unison_targets(
        self,
        state: GameState,
        reg: EffectRegistration,
        *,
        max_targets: int,
        max_cost: int,
        policy: str,
        prefer_attacker: bool = False,
    ) -> list[CardInstance]:
        if max_targets <= 0:
            return []
        opponent_id = self._opponent_of(reg.owner_player_id)
        opponent = state.players[opponent_id]
        candidates: list[CardInstance] = []
        ctx = state.attack_context
        if prefer_attacker and ctx is not None and ctx.attacker_player_id == opponent_id:
            preferred = self._find_by_instance(opponent, ctx.attacker_zone, ctx.attacker_instance_id)
            if preferred is not None and preferred.card_type not in {"LEADER", "Z-LEADER"}:
                candidates.append(preferred)
        for zone_card in [*opponent.battle_area, *opponent.unison_area]:
            if all(existing.instance_id != zone_card.instance_id for existing in candidates):
                candidates.append(zone_card)
        target_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("target_card_types", reg.handler_params.get("target_card_type", ""))).replace("|", ",").split(",")
            if part.strip()
        }
        if target_card_types:
            candidates = [c for c in candidates if str(c.card_type or "").upper() in target_card_types]
        if max_cost >= 0:
            candidates = [c for c in candidates if int(c.energy_cost or 0) <= max_cost]
        if not bool(reg.handler_params.get("ignores_barrier", False)):
            candidates = [c for c in candidates if not self._card_currently_has_barrier(c)]
        if not candidates:
            return []
        indexes = self._choose_effect_target_indexes(state, reg, candidates, max_targets, policy)
        return [candidates[i] for i in indexes]

    def _select_opponent_battle_targets_up_to_total_cost(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        total_cost_budget: int,
        prefer_attacker: bool = False,
    ) -> list[CardInstance]:
        if total_cost_budget < 0:
            return []
        opponent_id = self._opponent_of(owner_player_id)
        candidates = [c for c in state.players[opponent_id].battle_area if not self._card_currently_has_barrier(c)]
        if not candidates:
            return []
        ordered: list[CardInstance] = []
        if prefer_attacker and state.attack_context is not None and state.attack_context.attacker_zone == "battle":
            attacker_id = state.attack_context.attacker_instance_id
            attacker = next((c for c in candidates if c.instance_id == attacker_id), None)
            if attacker is not None:
                ordered.append(attacker)
        remaining = [c for c in candidates if c.instance_id not in {card.instance_id for card in ordered}]
        remaining.sort(key=lambda card: (int(card.energy_cost or 0), card.instance_id))
        ordered.extend(remaining)
        selected: list[CardInstance] = []
        spent = 0
        for card in ordered:
            cost = int(card.energy_cost or 0)
            if spent + cost > total_cost_budget:
                continue
            selected.append(card)
            spent += cost
        return selected

    def _select_opponent_battle_targets_up_to_total_power(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        total_power_budget: int,
    ) -> list[CardInstance]:
        if total_power_budget < 0:
            return []
        opponent_id = self._opponent_of(owner_player_id)
        candidates = [c for c in state.players[opponent_id].battle_area if not self._card_currently_has_barrier(c)]
        if not candidates:
            return []
        candidates.sort(key=lambda card: (int(card.power or 0), int(card.energy_cost or 0), card.instance_id))
        best_power = -1
        best_size = -1
        best_indexes: tuple[int, ...] = ()
        for size in range(1, len(candidates) + 1):
            for subset_indexes in combinations(range(len(candidates)), size):
                total_power = sum(max(int(candidates[idx].power or 0), 0) for idx in subset_indexes)
                if total_power > total_power_budget:
                    continue
                tie_break = tuple(-candidates[idx].instance_id for idx in subset_indexes)
                current_tie_break = tuple(-candidates[idx].instance_id for idx in best_indexes)
                if (
                    total_power > best_power
                    or (total_power == best_power and size > best_size)
                    or (total_power == best_power and size == best_size and tie_break > current_tie_break)
                ):
                    best_power = total_power
                    best_size = size
                    best_indexes = subset_indexes
        if best_power < 0:
            return []
        chosen_indexes = set(best_indexes)
        return [card for idx, card in enumerate(candidates) if idx in chosen_indexes]

    def _select_opponent_cards(
        self,
        state: GameState,
        *,
        owner_player_id: int,
        max_targets: int,
        policy: str,
        prefer_attacker: bool = False,
    ) -> list[CardInstance]:
        if max_targets <= 0:
            return []
        opponent_id = self._opponent_of(owner_player_id)
        opponent = state.players.get(opponent_id)
        if opponent is None:
            return []
        candidates: list[CardInstance] = []
        ctx = state.attack_context
        if prefer_attacker and ctx is not None and ctx.attacker_player_id == opponent_id:
            preferred = self._find_by_instance(opponent, ctx.attacker_zone, ctx.attacker_instance_id)
            if preferred is not None:
                candidates.append(preferred)
        leader = opponent.leader_area
        if all(existing.instance_id != leader.instance_id for existing in candidates):
            candidates.append(leader)
        for zone_card in [*opponent.battle_area, *opponent.unison_area]:
            if all(existing.instance_id != zone_card.instance_id for existing in candidates):
                candidates.append(zone_card)
        if not candidates:
            return []
        indexes = self._choose_effect_target_indexes(
            state,
            EffectRegistration(
                effect_id=0,
                owner_player_id=owner_player_id,
                source_instance_id=0,
                source_card_id=0,
                source_zone="",
                trigger="counter_attack",
                handler_id="counter_select_opponent_cards",
                handler_params={},
            ),
            candidates,
            max_targets,
            policy,
        )
        return [candidates[i] for i in indexes]

    def _effect_requirements_met(self, state: GameState, reg: EffectRegistration) -> bool:
        owner = state.players[reg.owner_player_id]
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        if source is None and str(reg.source_zone or "").strip().lower() in {"battle", "unison"}:
            found = self._find_card_on_any_board_by_instance(state, instance_id=reg.source_instance_id)
            if found is not None:
                _found_zone, source = found
        if source is not None and self._card_skills_are_negated(source):
            return False
        required_source_zone = str(reg.handler_params.get("required_source_zone", "")).strip().lower()
        if required_source_zone and str(reg.source_zone or "").strip().lower() != required_source_zone:
            return False
        normalized_source_zone = str(reg.source_zone or "").strip().lower()
        if normalized_source_zone in {"leader_under", "battle_under"}:
            host_card: CardInstance | None = None
            if normalized_source_zone == "leader_under":
                host_card = owner.leader_area
            else:
                battle_under_entry = self._find_battle_under_entry(owner, source_instance_id=reg.source_instance_id)
                if battle_under_entry is None:
                    return False
                _flat_index, host_card, _under_index, _source_card = battle_under_entry
            under_host_allowed_colors = {
                part.strip().lower()
                for part in str(reg.handler_params.get("under_host_allowed_colors", "")).replace("|", ",").replace("/", ",").split(",")
                if part.strip()
            }
            under_host_required_traits = {
                part.strip()
                for part in str(reg.handler_params.get("under_host_required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            }
            under_host_name_contains = str(reg.handler_params.get("under_host_name_contains", "")).strip().upper()
            under_host_required_characters = {
                part.strip()
                for part in str(reg.handler_params.get("under_host_required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            }
            if host_card is None:
                return False
            if (
                under_host_allowed_colors
                or under_host_required_traits
                or under_host_name_contains
                or under_host_required_characters
            ) and not self._card_matches_effect_filters(
                host_card,
                allowed_colors=under_host_allowed_colors,
                required_traits=under_host_required_traits,
                required_characters=under_host_required_characters,
                required_name_contains=under_host_name_contains,
            ):
                return False
        min_source_stacked_cards = self._resolve_effect_int_param(state, reg, "min_source_stacked_cards", default=-1)
        if source is not None and min_source_stacked_cards >= 0 and len(getattr(source, "stacked_card_ids", ())) < min_source_stacked_cards:
            return False
        min_source_markers = self._resolve_effect_int_param(state, reg, "min_source_markers", default=-1)
        if source is not None and min_source_markers >= 0 and int(getattr(source, "markers", 0) or 0) < min_source_markers:
            return False
        required_source_stacked_opponent_owned_at_least = self._resolve_effect_int_param(
            state,
            reg,
            "required_source_stacked_opponent_owned_at_least",
            default=-1,
        )
        if required_source_stacked_opponent_owned_at_least >= 0:
            if source is None:
                return False
            if self._count_stacked_cards_owned_by_player(source, self._opponent_of(reg.owner_player_id)) < required_source_stacked_opponent_owned_at_least:
                return False
        if not self._leader_requirement_string_met(
            state,
            owner_player_id=reg.owner_player_id,
            raw_req=reg.handler_params.get("requires_leader"),
        ):
            return False
        raw_req = reg.handler_params.get("requires_leader")
        leader_ok = True
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        if isinstance(raw_req, str) and raw_req.strip():
            req = raw_req.lower()
            leader_colors = {part.strip().lower() for part in str(leader.color or "").replace("/", ",").split(",") if part.strip()}
            required_colors = {color for color in ("red", "blue", "green", "yellow", "black") if color in req}
            if required_colors and leader_colors.isdisjoint(required_colors):
                leader_ok = False
            required_from_angle = {part.strip().lower() for part in re.findall(r"<([^>]+)>", req) if part.strip()}
            required_from_guillemets = {part.strip().lower() for part in re.findall(r"≪([^≫]+)≫", req) if part.strip()}
            if required_from_angle or required_from_guillemets:
                leader_traits = {part.strip().lower() for part in (leader_runtime.traits or ()) if part.strip()}
                leader_characters = {part.strip().lower() for part in (leader_runtime.characters or ()) if part.strip()}
                if not leader_traits and getattr(leader, "traits", ()):
                    leader_traits = {part.strip().lower() for part in (leader.traits or ()) if part.strip()}
                if not leader_characters and getattr(leader, "characters", ()):
                    leader_characters = {part.strip().lower() for part in (leader.characters or ()) if part.strip()}
                if required_from_angle and (leader_traits | leader_characters).isdisjoint(required_from_angle):
                    leader_ok = False
                if required_from_guillemets and leader_traits.isdisjoint(required_from_guillemets):
                    leader_ok = False
        if not leader_ok:
            return False
        required_leader_traits_raw = str(reg.handler_params.get("required_leader_traits", "")).strip().lower()
        if required_leader_traits_raw:
            required_leader_traits = {
                part.strip()
                for part in required_leader_traits_raw.replace("|", ",").split(",")
                if part.strip()
            }
            leader_traits = {part.strip().lower() for part in (leader_runtime.traits or ()) if part.strip()}
            leader_characters = {part.strip().lower() for part in (leader_runtime.characters or ()) if part.strip()}
            if not leader_traits and getattr(leader, "traits", ()):
                leader_traits = {part.strip().lower() for part in (leader.traits or ()) if part.strip()}
            if not leader_characters and getattr(leader, "characters", ()):
                leader_characters = {part.strip().lower() for part in (leader.characters or ()) if part.strip()}
            if (leader_traits | leader_characters).isdisjoint(required_leader_traits):
                return False
        if bool(reg.handler_params.get("requires_leader_front_side_up", False)) and bool(getattr(leader, "awakened", False)):
            return False
        required_leader_back_name_contains = str(reg.handler_params.get("required_leader_back_name_contains", "")).strip().upper()
        if required_leader_back_name_contains:
            leader_back_runtime = self._resolve_card_runtime_data(leader.card_id, side="back")
            back_name = str(leader_back_runtime.card_name or "").upper()
            if required_leader_back_name_contains not in back_name:
                return False
        leader_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("leader_allowed_colors", "")).strip().lower().replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        leader_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("leader_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        leader_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("leader_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        leader_required_name_contains = str(reg.handler_params.get("leader_required_name_contains", "")).strip().upper()
        if leader_allowed_colors or leader_required_traits or leader_required_characters or leader_required_name_contains:
            leader_colors = {
                part.strip().lower()
                for part in str(leader.color or leader_runtime.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            leader_traits = {part.strip().lower() for part in (leader_runtime.traits or ()) if part.strip()}
            leader_characters = {part.strip().lower() for part in (leader_runtime.characters or ()) if part.strip()}
            if not leader_colors and getattr(leader, "color", ""):
                leader_colors = {
                    part.strip().lower()
                    for part in str(leader.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
            if not leader_traits and getattr(leader, "traits", ()):
                leader_traits = {part.strip().lower() for part in (leader.traits or ()) if part.strip()}
            if not leader_characters and getattr(leader, "characters", ()):
                leader_characters = {part.strip().lower() for part in (leader.characters or ()) if part.strip()}
            leader_name = str(leader_runtime.card_name or getattr(leader, "card_name", "") or "").upper()
            if leader_allowed_colors and leader_colors.isdisjoint(leader_allowed_colors):
                return False
            if leader_required_traits and (leader_traits | leader_characters).isdisjoint(leader_required_traits):
                return False
            if leader_required_characters and (leader_traits | leader_characters).isdisjoint(leader_required_characters):
                return False
            if leader_required_name_contains and leader_required_name_contains not in leader_name:
                return False
        min_owner_energy = self._resolve_effect_int_param(state, reg, "min_owner_energy", default=-1)
        if min_owner_energy < 0:
            min_owner_energy = self._resolve_effect_int_param(state, reg, "owner_energy_at_least", default=-1)
        if min_owner_energy >= 0 and len(owner.energy) < min_owner_energy:
            return False
        required_owner_hand_count_at_least = self._resolve_effect_int_param(state, reg, "required_owner_hand_count_at_least", default=-1)
        if required_owner_hand_count_at_least >= 0 and len(owner.hand) < required_owner_hand_count_at_least:
            return False
        min_owner_z_energy = self._resolve_effect_int_param(state, reg, "min_owner_z_energy", default=-1)
        if min_owner_z_energy >= 0 and len(owner.z_energy) < min_owner_z_energy:
            return False
        required_owner_z_energy_characters = {
            part.strip().lower()
            for part in str(reg.handler_params.get("required_owner_z_energy_characters", "")).replace("|", ",").split(",")
            if part.strip()
        }
        if required_owner_z_energy_characters:
            matched = False
            for card in owner.z_energy:
                runtime = self._resolve_card_runtime_data(card.card_id)
                z_chars = {part.strip().lower() for part in (runtime.characters or ()) if part.strip()}
                if not z_chars and getattr(card, "characters", ()):
                    z_chars = {part.strip().lower() for part in tuple(card.characters or ()) if part.strip()}
                z_traits = {part.strip().lower() for part in (runtime.traits or ()) if part.strip()}
                if not z_traits and getattr(card, "traits", ()):
                    z_traits = {part.strip().lower() for part in tuple(card.traits or ()) if part.strip()}
                if not (z_chars | z_traits).isdisjoint(required_owner_z_energy_characters):
                    matched = True
                    break
            if not matched:
                return False
        min_opponent_energy = self._resolve_effect_int_param(state, reg, "min_opponent_energy", default=-1)
        if min_opponent_energy >= 0:
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            if opponent is None or len(opponent.energy) < min_opponent_energy:
                return False
        min_owner_matching_energy = self._resolve_effect_int_param(state, reg, "min_owner_matching_energy", default=-1)
        if min_owner_matching_energy >= 0:
            allowed_energy_colors = {
                part.strip().lower()
                for part in str(reg.handler_params.get("required_energy_colors", "")).replace("|", ",").replace("/", ",").split(",")
                if part.strip()
            }
            requires_multicolor_energy = bool(reg.handler_params.get("requires_multicolor_energy", False))
            matching_energy = 0
            for energy in owner.energy:
                colors = {
                    part.strip().lower()
                    for part in str(energy.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
                if allowed_energy_colors and colors.isdisjoint(allowed_energy_colors):
                    continue
                if requires_multicolor_energy and len(colors) < 2:
                    continue
                matching_energy += 1
            if matching_energy < min_owner_matching_energy:
                return False
        min_any_player_energy = self._resolve_effect_int_param(state, reg, "min_any_player_energy", default=-1)
        if min_any_player_energy >= 0:
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            opponent_energy = len(opponent.energy) if opponent is not None else 0
            if max(len(owner.energy), opponent_energy) < min_any_player_energy:
                return False
        min_total_players_energy = self._resolve_effect_int_param(state, reg, "min_total_players_energy", default=-1)
        if min_total_players_energy >= 0:
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            opponent_energy = len(opponent.energy) if opponent is not None else 0
            if len(owner.energy) + opponent_energy < min_total_players_energy:
                return False
        max_owner_life = self._resolve_effect_int_param(state, reg, "max_owner_life", default=-1)
        if max_owner_life >= 0 and len(owner.life) > max_owner_life:
            return False
        if bool(reg.handler_params.get("requires_owner_life_less_or_equal_opponent", False)):
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            if opponent is None or len(owner.life) > len(opponent.life):
                return False
        min_owner_drop = self._resolve_effect_int_param(state, reg, "min_owner_drop", default=-1)
        if min_owner_drop >= 0 and len(owner.drop) < min_owner_drop:
            return False
        min_opponent_drop = self._resolve_effect_int_param(state, reg, "min_opponent_drop", default=-1)
        if min_opponent_drop >= 0:
            opponent = state.players.get(self._opponent_of(reg.owner_player_id))
            if opponent is None or len(opponent.drop) < min_opponent_drop:
                return False
        min_owner_hidden_mode_battle = self._resolve_effect_int_param(state, reg, "min_owner_hidden_mode_battle", default=-1)
        if min_owner_hidden_mode_battle >= 0:
            hidden_count = sum(1 for card in owner.battle_area if card.hidden_mode)
            if hidden_count < min_owner_hidden_mode_battle:
                return False
        if bool(reg.handler_params.get("requires_no_owner_battle_with_source_card_id", False)):
            if any(int(card.card_id) == int(reg.source_card_id) for card in owner.battle_area):
                return False
        if bool(reg.handler_params.get("requires_no_owner_battle", False)) and owner.battle_area:
            return False
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        if bool(reg.handler_params.get("requires_no_opponent_battle", False)) and opponent is not None and opponent.battle_area:
            return False
        if bool(reg.handler_params.get("requires_no_owner_unison", False)) and owner.unison_area:
            return False
        if bool(reg.handler_params.get("requires_no_owner_field_extra", False)):
            has_owner_field_extra = False
            for card in owner.battle_area:
                if str(card.card_type or "").upper() not in {"EXTRA", "Z-EXTRA"}:
                    continue
                keywords = {
                    str(part).strip().lower()
                    for part in (
                        tuple(card.keywords or ())
                        or tuple(self._resolve_card_runtime_data(card.card_id).keywords or ())
                    )
                    if str(part).strip()
                }
                if "field" in keywords:
                    has_owner_field_extra = True
                    break
            if has_owner_field_extra:
                return False
        owner_battle_only_matching = bool(reg.handler_params.get("required_owner_battle_only_matching", False))
        owner_battle_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_allowed_colors", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_required_name_contains = str(reg.handler_params.get("required_owner_battle_required_name_contains", "")).strip().upper()
        owner_battle_required_skill_text_contains = str(reg.handler_params.get("required_owner_battle_skill_text_contains", "")).strip().lower()
        owner_battle_required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_battle_required_card_types", "")).strip().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_allowed_costs = {
            int(part.strip())
            for part in str(reg.handler_params.get("required_owner_battle_allowed_costs", "")).strip().replace("|", ",").split(",")
            if part.strip().isdigit()
        }
        owner_battle_min_cost = self._resolve_effect_int_param(state, reg, "required_owner_battle_min_cost", default=-1)
        owner_battle_max_cost = self._resolve_effect_int_param(state, reg, "required_owner_battle_max_cost", default=-1)
        owner_battle_require_mono_color = bool(reg.handler_params.get("required_owner_battle_require_mono_color", False))
        owner_battle_exclude_source_instance = bool(reg.handler_params.get("required_owner_battle_exclude_source_instance", False))
        owner_battle_without_source_name_under = bool(reg.handler_params.get("required_owner_battle_without_source_name_under", False))
        source_name_upper = str(
            self._resolve_card_runtime_data(reg.source_card_id).card_name
            or getattr(source, "card_name", "")
            or ""
        ).strip().upper()
        if (
            owner_battle_only_matching
            or owner_battle_allowed_colors
            or owner_battle_required_traits
            or owner_battle_required_characters
            or owner_battle_required_name_contains
            or owner_battle_required_skill_text_contains
            or owner_battle_required_card_types
            or owner_battle_allowed_costs
            or owner_battle_min_cost >= 0
            or owner_battle_max_cost >= 0
            or owner_battle_require_mono_color
            or owner_battle_exclude_source_instance
            or owner_battle_without_source_name_under
        ):
            if not owner.battle_area:
                return False
            for card in owner.battle_area:
                if owner_battle_exclude_source_instance and int(card.instance_id) == int(reg.source_instance_id):
                    continue
                matches = self._card_matches_effect_filters(
                    card,
                    allowed_colors=owner_battle_allowed_colors,
                    required_traits=owner_battle_required_traits,
                    required_characters=owner_battle_required_characters,
                    required_name_contains=owner_battle_required_name_contains,
                    required_skill_text_contains=owner_battle_required_skill_text_contains,
                    required_card_types=owner_battle_required_card_types,
                )
                if matches and owner_battle_allowed_costs and int(card.energy_cost or -1) not in owner_battle_allowed_costs:
                    matches = False
                if matches and owner_battle_min_cost >= 0 and int(card.energy_cost or -1) < owner_battle_min_cost:
                    matches = False
                if matches and owner_battle_max_cost >= 0 and int(card.energy_cost or -1) > owner_battle_max_cost:
                    matches = False
                if matches and owner_battle_require_mono_color:
                    colors = {
                        part.strip().lower()
                        for part in str(card.color or "").replace("/", ",").split(",")
                        if part.strip()
                    }
                    if len(colors) != 1:
                        matches = False
                if matches and owner_battle_without_source_name_under and source_name_upper:
                    for card_id in tuple(card.stacked_card_ids or ()):
                        stacked_name = str(self._resolve_card_runtime_data(int(card_id)).card_name or "").strip().upper()
                        if stacked_name == source_name_upper:
                            matches = False
                            break
                if owner_battle_only_matching and not matches:
                    return False
                if not owner_battle_only_matching and matches:
                    break
            else:
                return False
        owner_battle_or_z_energy_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_or_z_energy_allowed_colors", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_or_z_energy_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_or_z_energy_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_or_z_energy_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_or_z_energy_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_or_z_energy_required_name_contains = str(
            reg.handler_params.get("required_owner_battle_or_z_energy_required_name_contains", "")
        ).strip().upper()
        if (
            owner_battle_or_z_energy_allowed_colors
            or owner_battle_or_z_energy_required_traits
            or owner_battle_or_z_energy_required_characters
            or owner_battle_or_z_energy_required_name_contains
        ):
            zones_to_scan = [*owner.battle_area, *owner.z_energy]
            if not zones_to_scan:
                return False
            if not any(
                self._card_matches_effect_filters(
                    card,
                    allowed_colors=owner_battle_or_z_energy_allowed_colors,
                    required_traits=owner_battle_or_z_energy_required_traits,
                    required_characters=owner_battle_or_z_energy_required_characters,
                    required_name_contains=owner_battle_or_z_energy_required_name_contains,
                )
                for card in zones_to_scan
            ):
                return False
        owner_leader_under_count_at_least = int(reg.handler_params.get("required_owner_leader_under_count_at_least", 0) or 0)
        owner_leader_under_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_leader_under_allowed_colors", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_leader_under_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_leader_under_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_leader_under_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_leader_under_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_leader_under_required_name_contains = str(
            reg.handler_params.get("required_owner_leader_under_required_name_contains", "")
        ).strip().upper()
        owner_leader_under_required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_leader_under_required_card_types", "")).strip().replace("|", ",").split(",")
            if part.strip()
        }
        if (
            owner_leader_under_count_at_least > 0
            or owner_leader_under_allowed_colors
            or owner_leader_under_required_traits
            or owner_leader_under_required_characters
            or owner_leader_under_required_name_contains
            or owner_leader_under_required_card_types
        ):
            matching = 0
            for index, card_id in enumerate(tuple(owner.leader_area.stacked_card_ids or ())):
                candidate = self._create_card_instance(
                    next_instance_id=-(owner.player_id * 100000 + index + 1),
                    card_id=int(card_id),
                    owner_id=owner.player_id,
                )
                if not self._card_matches_effect_filters(
                    candidate,
                    allowed_colors=owner_leader_under_allowed_colors,
                    required_traits=owner_leader_under_required_traits,
                    required_characters=owner_leader_under_required_characters,
                    required_name_contains=owner_leader_under_required_name_contains,
                    required_card_types=owner_leader_under_required_card_types,
                ):
                    continue
                matching += 1
                if matching >= max(owner_leader_under_count_at_least, 1):
                    break
            if matching < max(owner_leader_under_count_at_least, 1):
                return False
        owner_battle_under_count_at_least = int(reg.handler_params.get("required_owner_battle_under_count_at_least", 0) or 0)
        owner_battle_under_host_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_under_host_allowed_colors", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_under_host_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_under_host_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_under_host_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_battle_under_host_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_battle_under_host_required_name_contains = str(
            reg.handler_params.get("required_owner_battle_under_host_required_name_contains", "")
        ).strip().upper()
        owner_battle_under_host_required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_battle_under_host_required_card_types", "")).strip().replace("|", ",").split(",")
            if part.strip()
        }
        if (
            owner_battle_under_count_at_least > 0
            or owner_battle_under_host_allowed_colors
            or owner_battle_under_host_required_traits
            or owner_battle_under_host_required_characters
            or owner_battle_under_host_required_name_contains
            or owner_battle_under_host_required_card_types
        ):
            if not self._owner_battle_hosts_with_under_cards(
                state,
                owner_player_id=reg.owner_player_id,
                required_count=max(owner_battle_under_count_at_least, 1),
                allowed_colors=owner_battle_under_host_allowed_colors,
                required_traits=owner_battle_under_host_required_traits,
                required_characters=owner_battle_under_host_required_characters,
                required_name_contains=owner_battle_under_host_required_name_contains,
                required_card_types=owner_battle_under_host_required_card_types,
            ):
                return False
        owner_combo_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_allowed_colors", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_combo_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_combo_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_combo_allowed_colors_each = [
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_allowed_colors_each", "")).strip().lower().split("|")
            if part.strip()
        ]
        owner_combo_required_traits_each = [
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_required_traits_each", "")).strip().lower().split("|")
            if part.strip()
        ]
        owner_combo_required_characters_each = [
            part.strip()
            for part in str(reg.handler_params.get("required_owner_combo_required_characters_each", "")).strip().lower().split("|")
            if part.strip()
        ]
        owner_combo_required_name_contains_each = [
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_combo_required_name_contains_each", "")).strip().split("|")
            if part.strip()
        ]
        owner_combo_required_card_types_each = [
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_combo_required_card_type_each", "")).strip().split("|")
            if part.strip()
        ]
        owner_combo_required_name_contains = str(reg.handler_params.get("required_owner_combo_required_name_contains", "")).strip().upper()
        owner_combo_required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_combo_required_card_type", "")).strip().replace("|", ",").split(",")
            if part.strip()
        }
        owner_combo_requires_skill_less = bool(reg.handler_params.get("required_owner_combo_requires_skill_less", False))
        if (
            owner_combo_allowed_colors
            or owner_combo_required_traits
            or owner_combo_required_characters
            or owner_combo_allowed_colors_each
            or owner_combo_required_traits_each
            or owner_combo_required_characters_each
            or owner_combo_required_name_contains_each
            or owner_combo_required_card_types_each
            or owner_combo_required_name_contains
            or owner_combo_required_card_types
            or owner_combo_requires_skill_less
        ):
            if not owner.combo_area:
                return False
            if not any(
                self._card_matches_effect_filters(
                    card,
                    allowed_colors=owner_combo_allowed_colors,
                    required_traits=owner_combo_required_traits,
                    required_characters=owner_combo_required_characters,
                    required_name_contains=owner_combo_required_name_contains,
                    required_card_types=owner_combo_required_card_types,
                )
                and (
                    not owner_combo_requires_skill_less
                    or self._card_is_skillless(card)
                )
                for card in owner.combo_area
            ):
                return False
            if any(
                not any(
                    self._card_matches_effect_filters(
                        card,
                        allowed_colors={required_color},
                        required_traits=set(),
                        required_characters=set(),
                        required_name_contains="",
                        required_card_types=None,
                    )
                    for card in owner.combo_area
                )
                for required_color in owner_combo_allowed_colors_each
            ):
                return False
            if any(
                not any(
                    self._card_matches_effect_filters(
                        card,
                        allowed_colors=set(),
                        required_traits={required_trait},
                        required_characters=set(),
                        required_name_contains="",
                        required_card_types=None,
                    )
                    for card in owner.combo_area
                )
                for required_trait in owner_combo_required_traits_each
            ):
                return False
            if any(
                not any(
                    self._card_matches_effect_filters(
                        card,
                        allowed_colors=set(),
                        required_traits=set(),
                        required_characters={required_character},
                        required_name_contains="",
                        required_card_types=None,
                    )
                    for card in owner.combo_area
                )
                for required_character in owner_combo_required_characters_each
            ):
                return False
            if any(
                not any(
                    self._card_matches_effect_filters(
                        card,
                        allowed_colors=set(),
                        required_traits=set(),
                        required_characters=set(),
                        required_name_contains=required_name,
                        required_card_types=None,
                    )
                    for card in owner.combo_area
                )
                for required_name in owner_combo_required_name_contains_each
            ):
                return False
            if any(
                not any(
                    self._card_matches_effect_filters(
                        card,
                        allowed_colors=set(),
                        required_traits=set(),
                        required_characters=set(),
                        required_name_contains="",
                        required_card_types={required_card_type},
                    )
                    for card in owner.combo_area
                )
                for required_card_type in owner_combo_required_card_types_each
            ):
                return False
        if bool(reg.handler_params.get("requires_owner_combo_empty", False)) and owner.combo_area:
            return False
        owner_attacker_allowed_colors = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_attacker_allowed_colors", "")).strip().lower().replace("|", ",").replace("/", ",").split(",")
            if part.strip()
        }
        owner_attacker_required_traits = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_attacker_required_traits", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_attacker_required_characters = {
            part.strip()
            for part in str(reg.handler_params.get("required_owner_attacker_required_characters", "")).strip().lower().replace("|", ",").split(",")
            if part.strip()
        }
        owner_attacker_required_name_contains = str(reg.handler_params.get("required_owner_attacker_required_name_contains", "")).strip().upper()
        owner_attacker_required_skill_text_contains = str(reg.handler_params.get("required_owner_attacker_skill_text_contains", "")).strip().lower()
        owner_attacker_required_card_types = {
            part.strip().upper()
            for part in str(reg.handler_params.get("required_owner_attacker_required_card_types", "")).strip().replace("|", ",").split(",")
            if part.strip()
        }
        if (
            owner_attacker_allowed_colors
            or owner_attacker_required_traits
            or owner_attacker_required_characters
            or owner_attacker_required_name_contains
            or owner_attacker_required_skill_text_contains
            or owner_attacker_required_card_types
        ):
            ctx = state.attack_context
            if ctx is None or ctx.attacker_player_id != reg.owner_player_id:
                return False
            attacker = self._find_by_instance(owner, ctx.attacker_zone, ctx.attacker_instance_id)
            if attacker is None:
                return False
            if not self._card_matches_effect_filters(
                attacker,
                allowed_colors=owner_attacker_allowed_colors,
                required_traits=owner_attacker_required_traits,
                required_characters=owner_attacker_required_characters,
                required_name_contains=owner_attacker_required_name_contains,
                required_skill_text_contains=owner_attacker_required_skill_text_contains,
                required_card_types=owner_attacker_required_card_types,
            ):
                return False
        if bool(reg.handler_params.get("requires_source_in_battle", False)):
            ctx = state.attack_context
            if ctx is None:
                return False
            source_in_battle = (
                (ctx.attacker_player_id == reg.owner_player_id and ctx.attacker_zone == reg.source_zone and ctx.attacker_instance_id == reg.source_instance_id)
                or (ctx.target_player_id == reg.owner_player_id and ctx.target_zone == reg.source_zone and ctx.target_instance_id == reg.source_instance_id)
            )
            if not source_in_battle:
                return False
        required_attack_target_zone = str(reg.handler_params.get("required_attack_target_zone", "")).strip().lower()
        if required_attack_target_zone:
            ctx = state.attack_context
            if ctx is None or str(ctx.target_zone or "").strip().lower() != required_attack_target_zone:
                return False
        owner_battle_name_in_battle = str(reg.handler_params.get("required_owner_battle_name_in_battle", "")).strip().upper()
        if owner_battle_name_in_battle:
            ctx = state.attack_context
            if ctx is None:
                return False
            battle_cards: list[CardInstance] = []
            if ctx.attacker_player_id == reg.owner_player_id:
                attacker = self._find_by_instance(owner, ctx.attacker_zone, ctx.attacker_instance_id)
                if attacker is not None:
                    battle_cards.append(attacker)
            if ctx.target_player_id == reg.owner_player_id:
                target = self._find_by_instance(owner, ctx.target_zone, ctx.target_instance_id)
                if target is not None:
                    battle_cards.append(target)
            if not any(owner_battle_name_in_battle in str(card.card_name or "").upper() for card in battle_cards):
                return False
        mono = reg.handler_params.get("requires_mono_energy")
        if isinstance(mono, str) and mono.strip():
            required = mono.strip().lower()
            for e in owner.energy:
                color = (e.color or "").strip().lower()
                if color and color != required:
                    return False
        if bool(reg.handler_params.get("requires_owner_turn", False)) and state.active_player != reg.owner_player_id:
            return False
        if bool(reg.handler_params.get("requires_opponent_turn", False)) and state.active_player == reg.owner_player_id:
            return False
        return True

    def _activate_effect_requirements_met(
        self,
        state: GameState,
        *,
        player_id: int,
        source: CardInstance,
        source_zone: str,
        source_kind: str,
    ) -> bool:
        trigger = f"self_activate_{source_kind}"
        rules = [rule for rule in self._effect_rules.get(source.card_id, ()) if rule.trigger == trigger]
        if not rules:
            return not self._is_activate_skill_restricted(state, player_id=player_id, card_id=source.card_id)
        for rule in rules:
            reg = EffectRegistration(
                effect_id=0,
                owner_player_id=player_id,
                source_instance_id=source.instance_id,
                source_card_id=source.card_id,
                source_zone=source_zone,
                trigger=rule.trigger,
                handler_id=rule.handler_id,
                handler_params=dict(rule.handler_params),
                source_card_number=str(source.card_number or ""),
                once_per_turn=rule.once_per_turn,
                limit_per_turn=rule.limit_per_turn,
                limit_scope=rule.limit_scope,
            )
            if self._is_registration_permanently_negated(state, reg):
                continue
            if self._is_registration_activate_skill_restricted(state, reg):
                continue
            if self._effect_requirements_met(state, reg):
                return True
        return False

    def _public_activate_matching_registrations(
        self,
        state: GameState,
        *,
        player_id: int,
        source: CardInstance,
        source_zone: str,
        source_kind: str,
    ) -> list[EffectRegistration]:
        trigger = f"self_activate_{source_kind}"
        return sorted(
            [
                reg
                for reg in state.effect_registry
                if reg.owner_player_id == player_id
                and reg.source_instance_id == source.instance_id
                and reg.source_zone == source_zone
                and reg.trigger == trigger
                and not self._is_registration_permanently_negated(state, reg)
                and not self._is_registration_activate_skill_restricted(state, reg)
                and self._effect_requirements_met(state, reg)
            ],
            key=lambda row: int(row.effect_id),
        )

    def _public_activate_energy_cost(
        self,
        state: GameState,
        *,
        player_id: int,
        source: CardInstance,
        source_zone: str,
        source_kind: str,
        effect_choice: int | None = None,
    ) -> int:
        regs = self._public_activate_matching_registrations(
            state,
            player_id=player_id,
            source=source,
            source_zone=source_zone,
            source_kind=source_kind,
        )
        if regs:
            selected: EffectRegistration | None = None
            if effect_choice is not None:
                selected = next((reg for reg in regs if int(reg.effect_id) == int(effect_choice)), None)
            if selected is None and len(regs) == 1:
                selected = regs[0]
            if selected is not None:
                return int(selected.handler_params.get("activate_total_cost", 0) or 0)
            return 0
        trigger = f"self_activate_{source_kind}"
        matching_rules = [
            rule
            for rule in self._effect_rules.get(source.card_id, ())
            if rule.trigger == trigger
            and not self._is_registration_permanently_negated(
                state,
                EffectRegistration(
                    effect_id=0,
                    owner_player_id=player_id,
                    source_instance_id=source.instance_id,
                    source_card_id=source.card_id,
                    source_zone=source_zone,
                    trigger=rule.trigger,
                    handler_id=rule.handler_id,
                    handler_params=dict(rule.handler_params),
                    source_card_number=str(source.card_number or ""),
                    once_per_turn=rule.once_per_turn,
                    limit_per_turn=rule.limit_per_turn,
                    limit_scope=rule.limit_scope,
                ),
            )
            and not self._is_registration_activate_skill_restricted(
                state,
                EffectRegistration(
                    effect_id=0,
                    owner_player_id=player_id,
                    source_instance_id=source.instance_id,
                    source_card_id=source.card_id,
                    source_zone=source_zone,
                    trigger=rule.trigger,
                    handler_id=rule.handler_id,
                    handler_params=dict(rule.handler_params),
                    source_card_number=str(source.card_number or ""),
                    once_per_turn=rule.once_per_turn,
                    limit_per_turn=rule.limit_per_turn,
                    limit_scope=rule.limit_scope,
                ),
            )
            and self._effect_requirements_met(
                state,
                EffectRegistration(
                    effect_id=0,
                    owner_player_id=player_id,
                    source_instance_id=source.instance_id,
                    source_card_id=source.card_id,
                    source_zone=source_zone,
                    trigger=rule.trigger,
                    handler_id=rule.handler_id,
                    handler_params=dict(rule.handler_params),
                    source_card_number=str(source.card_number or ""),
                    once_per_turn=rule.once_per_turn,
                    limit_per_turn=rule.limit_per_turn,
                    limit_scope=rule.limit_scope,
                ),
            )
        ]
        if len(matching_rules) == 1:
            return int(matching_rules[0].handler_params.get("activate_total_cost", 0) or 0)
        return 0

    def _public_activate_effect_choices(
        self,
        state: GameState,
        *,
        player_id: int,
        source: CardInstance,
        source_zone: str,
        source_kind: str,
    ) -> list[int | None]:
        regs = self._public_activate_matching_registrations(
            state,
            player_id=player_id,
            source=source,
            source_zone=source_zone,
            source_kind=source_kind,
        )
        if not regs:
            return [None]
        if len(regs) == 1:
            return [None]
        return [int(reg.effect_id) for reg in regs]

    def _effective_hand_energy_cost(self, state: GameState, *, player_id: int, card: CardInstance) -> int:
        base_cost = int(card.energy_cost or 0)
        override_cost = self._counter_hand_energy_cost_override(state, player_id=player_id, card=card)
        if override_cost is not None:
            base_cost = override_cost
        reduction = self._hand_cost_reduction_amount(state, player_id=player_id, card=card)
        if card.card_type in {"EXTRA", "Z-EXTRA"}:
            reduction += self._matching_activate_extra_cost_reduction_amount(state, player_id=player_id, source=card)
        return max(base_cost - reduction, 0)

    def _counter_hand_energy_cost_override(self, state: GameState, *, player_id: int, card: CardInstance) -> int | None:
        text = str(card.skill_text_raw or "")
        lower = text.lower()
        m = re.search(
            r"activate this card's \[counter\] skill from your hand by paying \((\d+)\) instead of its energy cost",
            lower,
        )
        if m is None:
            return None
        owner = state.players[player_id]
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        if not self._text_hand_cost_reduction_requirements_met(
            text,
            state=state,
            owner=owner,
            leader=leader,
            leader_runtime=leader_runtime,
        ):
            return None
        try:
            return int(m.group(1))
        except ValueError:
            return None

    def _can_pay_alternate_counter_hand_cost(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        spec = self._resolve_skill_cost_spec(card.card_id, "counter_alternate_from_hand")
        if spec is not None:
            if (
                len(tuple(spec.steps)) == 1
                and str(getattr(tuple(spec.steps)[0], "kind", "") or "") == "send_owner_leader_under_to_drop"
            ):
                return self._can_pay_send_owner_leader_under_to_drop_cost(player, tuple(spec.steps)[0])
            if (
                len(tuple(spec.steps)) == 1
                and str(getattr(tuple(spec.steps)[0], "kind", "") or "") == "send_owner_battle_under_to_drop"
            ):
                return self._can_pay_send_owner_battle_under_to_drop_cost(state, player, tuple(spec.steps)[0])
            try:
                return SkillCostDsl.can_pay(player, card, spec, opponent=state.players[self._opponent_of(player.player_id)])
            except Exception:
                return False
        text = str(card.skill_text_raw or "")
        if not text:
            return False
        leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
        if self._text_counter_can_rest_hidden_mode_battle_instead_of_energy_cost(card):
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=player.leader_area,
                leader_runtime=leader_runtime,
            ):
                return False
            return any(target.hidden_mode and not target.resting for target in player.battle_area)
        if self._text_counter_can_add_life_to_hand_instead_of_energy_cost(card):
            sparking_threshold = self._parse_sparking_threshold(text) or getattr(card, "sparking_threshold", None)
            if sparking_threshold is not None and len(player.drop) < int(sparking_threshold):
                return False
            return bool(player.life)
        if self._text_counter_can_activate_for_free_with_mono_blue_and_bottom_deck_other_hand(card):
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=player.leader_area,
                leader_runtime=leader_runtime,
            ):
                return False
            if len(player.hand) <= 1:
                return False
            color_names = {
                part.strip().lower()
                for energy in player.energy
                for part in str(getattr(energy, "color", "") or "").replace("/", ",").split(",")
                if part.strip()
            }
            return bool(color_names) and color_names == {"blue"}
        if self._text_counter_can_activate_for_free_with_red_unison_markers(card):
            return any(
                "red" in str(unison.color or "").lower()
                and int(getattr(unison, "markers", 0) or 0) >= 2
                for unison in player.unison_area
            )
        if self._text_counter_can_activate_for_free_with_green_unison(card):
            return any("green" in str(unison.color or "").lower() for unison in player.unison_area)
        if self._text_counter_can_activate_for_free_with_yellow_unison(card):
            return any("yellow" in str(unison.color or "").lower() for unison in player.unison_area)
        if self._text_counter_can_activate_for_free_with_green_gogeta_br_and_son_goku_vegeta_br_in_z_energy(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=leader,
                leader_runtime=leader_runtime,
            ):
                return False
            z_names = {
                str(self._resolve_card_runtime_data(z.card_id).card_name or getattr(z, "card_name", "") or "").strip().lower()
                for z in player.z_energy
            }
            return any("son goku: br" in name for name in z_names) and any("vegeta: br" in name for name in z_names)
        if self._text_counter_can_activate_for_free_with_red_android_13_z_leader_and_low_life(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=leader,
                leader_runtime=leader_runtime,
            ):
                return False
            leader_is_z_leader = bool(getattr(leader, "awakened", False)) or str(getattr(leader, "card_type", "")).upper().startswith("Z-")
            return leader_is_z_leader
        return False

    def _can_activate_counter_from_energy(self, state: GameState, *, player_id: int, card: CardInstance) -> bool:
        text = str(card.skill_text_raw or "")
        lower = text.lower()
        if "activate this card's [counter] skill from your energy by paying its energy cost" not in lower:
            return False
        player = state.players[player_id]
        leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
        if not self._text_hand_cost_reduction_requirements_met(
            text,
            state=state,
            owner=player,
            leader=player.leader_area,
            leader_runtime=leader_runtime,
        ):
            return False
        if "discarding 1 card from your hand" in lower:
            return bool(player.hand)
        return True

    def _pay_alternate_counter_hand_cost(self, state: GameState, player: PlayerState, card: CardInstance) -> bool:
        spec = self._resolve_skill_cost_spec(card.card_id, "counter_alternate_from_hand")
        if spec is not None:
            if (
                len(tuple(spec.steps)) == 1
                and str(getattr(tuple(spec.steps)[0], "kind", "") or "") == "send_owner_leader_under_to_drop"
            ):
                metadata = self._pay_send_owner_leader_under_to_drop_cost(state, player, tuple(spec.steps)[0])
                self._emit_drop_event_from_skill_cost_metadata(state, player=player, metadata=metadata)
                self._checkpoint(state, "counter_alternate_cost_leader_under_to_drop")
                return True
            if (
                len(tuple(spec.steps)) == 1
                and str(getattr(tuple(spec.steps)[0], "kind", "") or "") == "send_owner_battle_under_to_drop"
            ):
                self._pay_send_owner_battle_under_to_drop_cost(state, player, tuple(spec.steps)[0])
                self._checkpoint(state, "counter_alternate_cost_owner_battle_under_to_drop")
                return True
            try:
                metadata = SkillCostDsl.pay(player, card, spec, opponent=state.players[self._opponent_of(player.player_id)])
            except Exception:
                return False
            alt_kind = str(metadata.get("alternate_cost_kind") or "")
            if alt_kind == "rest_owner_hidden_mode_battle":
                self._checkpoint(state, "counter_alternate_cost_hidden_battle_rested")
            elif alt_kind == "add_life_to_hand":
                self._checkpoint(state, "counter_alternate_cost_life_to_hand")
            return True
        text = str(card.skill_text_raw or "")
        if self._text_counter_can_rest_hidden_mode_battle_instead_of_energy_cost(card):
            leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=player.leader_area,
                leader_runtime=leader_runtime,
            ):
                return False
            target = next((battle for battle in player.battle_area if battle.hidden_mode and not battle.resting), None)
            if target is None:
                return False
            target.resting = True
            self._checkpoint(state, "counter_alternate_cost_hidden_battle_rested")
            return True
        if self._text_counter_can_add_life_to_hand_instead_of_energy_cost(card):
            sparking_threshold = self._parse_sparking_threshold(text) or getattr(card, "sparking_threshold", None)
            if sparking_threshold is not None and len(player.drop) < int(sparking_threshold):
                return False
            if not player.life:
                return False
            chosen_index = self._choose_life_card_index(player, 0)
            player.hand.append(player.life.pop(chosen_index))
            self._checkpoint(state, "counter_alternate_cost_life_to_hand")
            return True
        if self._text_counter_can_activate_for_free_with_mono_blue_and_bottom_deck_other_hand(card):
            leader_runtime = self._resolve_card_runtime_data(player.leader_area.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=player.leader_area,
                leader_runtime=leader_runtime,
            ):
                return False
            if len(player.hand) <= 1:
                return False
            color_names = {
                part.strip().lower()
                for energy in player.energy
                for part in str(getattr(energy, "color", "") or "").replace("/", ",").split(",")
                if part.strip()
            }
            if not color_names or color_names != {"blue"}:
                return False
            discard_idx = next(
                (idx for idx, hand_card in enumerate(player.hand) if int(hand_card.instance_id) != int(card.instance_id)),
                -1,
            )
            if discard_idx < 0:
                return False
            player.deck.append(player.hand.pop(discard_idx).card_id)
            self._checkpoint(state, "counter_alternate_cost_bottom_deck_other_hand_blue_free")
            return True
        if self._text_counter_can_activate_for_free_with_red_unison_markers(card):
            if not any(
                "red" in str(unison.color or "").lower()
                and int(getattr(unison, "markers", 0) or 0) >= 2
                for unison in player.unison_area
            ):
                return False
            self._checkpoint(state, "counter_alternate_cost_red_unison_markers_free")
            return True
        if self._text_counter_can_activate_for_free_with_green_unison(card):
            if not any("green" in str(unison.color or "").lower() for unison in player.unison_area):
                return False
            self._checkpoint(state, "counter_alternate_cost_green_unison_free")
            return True
        if self._text_counter_can_activate_for_free_with_yellow_unison(card):
            if not any("yellow" in str(unison.color or "").lower() for unison in player.unison_area):
                return False
            self._checkpoint(state, "counter_alternate_cost_yellow_unison_free")
            return True
        if self._text_counter_can_activate_for_free_with_green_gogeta_br_and_son_goku_vegeta_br_in_z_energy(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=leader,
                leader_runtime=leader_runtime,
            ):
                return False
            z_names = {
                str(self._resolve_card_runtime_data(z.card_id).card_name or getattr(z, "card_name", "") or "").strip().lower()
                for z in player.z_energy
            }
            if not (any("son goku: br" in name for name in z_names) and any("vegeta: br" in name for name in z_names)):
                return False
            self._checkpoint(state, "counter_alternate_cost_green_gogeta_br_z_energy_free")
            return True
        if self._text_counter_can_activate_for_free_with_red_android_13_z_leader_and_low_life(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=leader,
                leader_runtime=leader_runtime,
            ):
                return False
            leader_is_z_leader = bool(getattr(leader, "awakened", False)) or str(getattr(leader, "card_type", "")).upper().startswith("Z-")
            if not leader_is_z_leader:
                return False
            self._checkpoint(state, "counter_alternate_cost_red_android_13_z_leader_free")
            return True
        if self._text_counter_can_activate_for_free_with_lord_slug_and_low_life(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            if not self._text_hand_cost_reduction_requirements_met(
                text,
                state=state,
                owner=player,
                leader=leader,
                leader_runtime=leader_runtime,
            ):
                return False
            if len(player.life) > 3:
                return False
            self._checkpoint(state, "counter_alternate_cost_lord_slug_low_life_free")
            return True
        if self._text_counter_can_activate_for_free_with_blue_nonleaders_under_leader(card):
            leader_under = list(player.leader_area.stacked_card_ids or ())
            moved = 0
            idx = 0
            while idx < len(leader_under) and moved < 2:
                card_id = int(leader_under[idx])
                runtime = self._resolve_card_runtime_data(card_id)
                colors = {
                    part.strip().lower()
                    for part in str(runtime.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
                if "blue" not in colors or str(runtime.card_type or "").strip().upper() == "LEADER":
                    idx += 1
                    continue
                leader_under.pop(idx)
                moved_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=player.player_id)
                state.next_instance_id += 1
                player.drop.append(moved_card)
                self._emit_card_placed_into_drop(state, owner_player_id=player.player_id, card=moved_card, source_zone="leader_under")
                moved += 1
            if moved < 2:
                return False
            player.leader_area.stacked_card_ids = tuple(leader_under)
            self._register_leader_under_card_effects(state, player_id=player.player_id)
            self._checkpoint(state, "counter_alternate_cost_blue_leader_under_to_drop")
            return True
        if self._text_counter_can_activate_for_free_with_green_super17_z_leader_and_discard(card):
            leader = player.leader_area
            leader_runtime = self._resolve_card_runtime_data(leader.card_id)
            leader_is_z_leader = bool(getattr(leader, "awakened", False)) or str(getattr(leader, "card_type", "")).upper().startswith("Z-")
            leader_characters = {
                part.strip().lower()
                for part in (
                    *(getattr(leader, "characters", ()) or ()),
                    *(leader_runtime.characters or ()),
                )
                if part and part.strip()
            }
            leader_colors = {
                part.strip().lower()
                for part in str(getattr(leader, "color", "") or leader_runtime.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            if not leader_is_z_leader or "green" not in leader_colors or "super 17" not in leader_characters:
                return False
            discard_idx = next(
                (idx for idx, hand_card in enumerate(player.hand) if int(hand_card.instance_id) != int(card.instance_id)),
                -1,
            )
            if discard_idx < 0:
                return False
            discarded = player.hand.pop(discard_idx)
            player.drop.append(discarded)
            self._emit_card_placed_into_drop(state, owner_player_id=player.player_id, card=discarded, source_zone="hand")
            self._checkpoint(state, "counter_alternate_cost_green_super17_z_leader_discard")
            return True
        return False

    def _hand_cost_reduction_amount(self, state: GameState, *, player_id: int, card: CardInstance) -> int:
        text = str(card.skill_text_raw or "")
        if not text:
            return 0
        relevant_text = self._extract_hand_cost_reduction_text(text)
        owner = state.players[player_id]
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        if not self._text_hand_cost_reduction_requirements_met(
            relevant_text,
            state=state,
            owner=owner,
            leader=leader,
            leader_runtime=leader_runtime,
        ):
            return 0
        dynamic_reduction = self._parse_dynamic_hand_cost_reduction_amount(state, owner, card, relevant_text)
        if dynamic_reduction > 0:
            return dynamic_reduction
        reduction = self._parse_hand_cost_reduction_amount(relevant_text)
        if reduction > 0:
            return reduction
        return 0

    @staticmethod
    def _extract_hand_cost_reduction_text(skill_text: object) -> str:
        text = str(skill_text or "")
        fragments = [
            fragment.strip()
            for fragment in re.split(r"[.\n]", text)
            if "reduce the energy cost of this card in your hand" in fragment.lower()
        ]
        if fragments:
            return ". ".join(fragments)
        return text

    @staticmethod
    def _parse_hand_cost_reduction_amount(skill_text: object) -> int:
        text = str(skill_text or "").lower()
        match = re.search(r"reduce the energy cost of this card in your hand by (\d+)", text)
        if match is None:
            return 0
        try:
            return int(match.group(1))
        except ValueError:
            return 0

    def _parse_dynamic_hand_cost_reduction_amount(self, state: GameState, owner: PlayerState, card: CardInstance, skill_text: object) -> int:
        text = str(skill_text or "").lower()
        opponent_energy_match = re.search(
            r"reduce (?:this card(?:'s)?|the) energy cost(?: of this card in your hand)? by (\d+) for each card in your opponent's energy",
            text,
        )
        if opponent_energy_match is not None:
            try:
                per_card = int(opponent_energy_match.group(1))
            except ValueError:
                return 0
            if per_card <= 0:
                return 0
            opponent = state.players.get(self._opponent_of(owner.player_id))
            return (len(opponent.energy) if opponent is not None else 0) * per_card
        match = re.search(
            r"reduce (?:this card(?:'s)?|the) energy cost(?: of this card in your hand)? by (\d+) for each (.+?) in your battle area, energy area, and drop area",
            text,
        )
        if match is None:
            return 0
        try:
            per_card = int(match.group(1))
        except ValueError:
            return 0
        if per_card <= 0:
            return 0
        descriptor = match.group(2).strip().lower()
        allowed_colors = {
            part.strip()
            for part in re.findall(r"\b(red|blue|green|yellow|black|white)\b", descriptor)
            if part.strip()
        }
        required_type = ""
        if "extra" in descriptor:
            required_type = "EXTRA"
        elif "battle" in descriptor:
            required_type = "BATTLE"
        elif "unison" in descriptor:
            required_type = "UNISON"
        zones = [*owner.battle_area, *owner.energy, *owner.drop]
        matching = 0
        for zone_card in zones:
            runtime = self._resolve_card_runtime_data(zone_card.card_id)
            zone_type = str(zone_card.card_type or runtime.card_type or "").upper()
            zone_colors = {
                part.strip().lower()
                for part in str(zone_card.color or runtime.color or "").replace("/", ",").split(",")
                if part.strip()
            }
            if required_type and required_type not in zone_type:
                continue
            if allowed_colors and zone_colors.isdisjoint(allowed_colors):
                continue
            matching += 1
        return matching * per_card

    def _text_hand_cost_reduction_requirements_met(
        self,
        skill_text: object,
        *,
        state: GameState,
        owner: PlayerState,
        leader: CardInstance,
        leader_runtime: CardRuntimeData,
    ) -> bool:
        text = str(skill_text or "").lower()
        leader_color = (leader.color or "").strip().lower()
        if "if your leader card is a white" in text or "if your leader card is white" in text:
            if leader_color != "white":
                return False
        if "if your leader card is a red" in text or "if your leader card is red" in text:
            if leader_color != "red":
                return False
        if "if your leader card is a blue" in text or "if your leader card is blue" in text:
            if leader_color != "blue":
                return False
        if "if your leader card is a green" in text or "if your leader card is green" in text:
            if leader_color != "green":
                return False
        if "if your leader card is a yellow" in text or "if your leader card is yellow" in text:
            if leader_color != "yellow":
                return False
        if "if your leader card is a black" in text or "if your leader card is black" in text:
            if leader_color != "black":
                return False
        if "if your leader card is mono-blue" in text or "if your leader card is mono blue" in text:
            if leader_color != "blue" or "/" in str(leader.color or ""):
                return False
        if "if your leader card is mono-red" in text or "if your leader card is mono red" in text:
            if leader_color != "red" or "/" in str(leader.color or ""):
                return False
        if "if your leader card is mono-green" in text or "if your leader card is mono green" in text:
            if leader_color != "green" or "/" in str(leader.color or ""):
                return False
        if "if your leader card is mono-yellow" in text or "if your leader card is mono yellow" in text:
            if leader_color != "yellow" or "/" in str(leader.color or ""):
                return False
        if "if your leader card is mono-black" in text or "if your leader card is mono black" in text:
            if leader_color != "black" or "/" in str(leader.color or ""):
                return False
        if "if your leader card is mono-white" in text or "if your leader card is mono white" in text:
            if leader_color != "white" or "/" in str(leader.color or ""):
                return False
        if "if your leader is a white" in text and leader_color != "white":
            return False
        if "if your leader is a red" in text and leader_color != "red":
            return False
        if "if your leader is a blue" in text and leader_color != "blue":
            return False
        if "if your leader is a green" in text and leader_color != "green":
            return False
        if "if your leader is a yellow" in text and leader_color != "yellow":
            return False
        if "if your leader is a black" in text and leader_color != "black":
            return False
        if "during your opponent's turn" in text or "it's your opponent's turn" in text or "it is your opponent's turn" in text:
            is_opponent_turn = (
                state.attack_context.attacker_player_id != owner.player_id
                if state.attack_context is not None
                else state.active_player != owner.player_id
            )
            if not is_opponent_turn:
                return False
        if "they have a skill-less battle card or unison card in play" in text:
            opponent = state.players.get(self._opponent_of(owner.player_id))
            if opponent is None:
                return False
            if not (
                any(self._card_is_skillless(card) for card in opponent.battle_area)
                or any(self._card_is_skillless(card) for card in opponent.unison_area)
            ):
                return False
        leader_required_traits = {
            part.strip().lower()
            for part in re.findall(r"(?:if|while) your leader(?: card)?[^.]{0,120}?≪([^≫]+)≫", text)
            if part.strip()
        }
        if not leader_required_traits:
            leader_required_traits = {
                part.strip().lower()
                for part in re.findall(r"(?:if|while) your leader(?: card)?[^.]{0,120}?â‰ª([^â‰«]+)â‰«", text)
                if part.strip()
            }
        if leader_required_traits:
            leader_traits = {
                part.strip().lower()
                for part in [*tuple(leader_runtime.traits or ()), *tuple(getattr(leader, "traits", ()) or ()), *tuple(getattr(leader, "characters", ()) or ())]
                if part.strip()
            }
            if leader_traits.isdisjoint(leader_required_traits):
                return False
        hidden_threshold = self._parse_hidden_mode_awaken_threshold(text)
        if hidden_threshold is not None:
            hidden_count = sum(1 for board_card in owner.battle_area if board_card.hidden_mode)
            if hidden_count < hidden_threshold:
                return False
        elif "you have a hidden mode card in your battle area" in text:
            if not any(board_card.hidden_mode for board_card in owner.battle_area):
                return False
        m_owner_life = re.search(r"your life is at (\d+) or less", text)
        if m_owner_life is not None:
            try:
                needed = int(m_owner_life.group(1))
            except ValueError:
                needed = -1
            if needed >= 0 and len(owner.life) > needed:
                return False
        m_owner_energy = re.search(r"you have (\d+) or more energy", text)
        if m_owner_energy is not None:
            try:
                needed = int(m_owner_energy.group(1))
            except ValueError:
                needed = -1
            if needed >= 0 and len(owner.energy) < needed:
                return False
        opponent = state.players.get(self._opponent_of(owner.player_id))
        m_opp_energy = re.search(r"your opponent has (\d+) or more energy", text)
        if m_opp_energy is not None:
            try:
                needed = int(m_opp_energy.group(1))
            except ValueError:
                needed = -1
            if needed >= 0 and (opponent is None or len(opponent.energy) < needed):
                return False
        m_opp_battle_descriptor = re.search(r"your opponent has a (.+?) card in play in their battle area", text)
        if m_opp_battle_descriptor is not None:
            descriptor = str(m_opp_battle_descriptor.group(1) or "").strip()
            if opponent is None:
                return False
            required_traits = {
                part.strip().lower()
                for part in re.findall(r"≪([^≫]+)≫", descriptor)
                if part.strip()
            }
            if not required_traits:
                required_traits = {
                    part.strip().lower()
                    for part in re.findall(r"â‰ª([^â‰«]+)â‰«", descriptor)
                    if part.strip()
                }
            required_characters = {part.strip().lower() for part in re.findall(r"<([^>]+)>", descriptor) if part.strip()}
            allowed_colors = {
                color
                for color in ("red", "blue", "green", "yellow", "black", "white")
                if re.search(rf"\b{color}\b", descriptor)
            }
            if not any(
                self._card_matches_effect_filters(
                    battle,
                    allowed_colors=allowed_colors,
                    required_traits=required_traits,
                    required_characters=required_characters,
                    required_name_contains="",
                    required_skill_text_contains="",
                    required_card_types={"BATTLE"},
                )
                for battle in opponent.battle_area
            ):
                return False
        m_owner_z_energy = re.search(r"you have (\d+) or more z-energy", text)
        if m_owner_z_energy is not None:
            try:
                needed = int(m_owner_z_energy.group(1))
            except ValueError:
                needed = -1
            if needed >= 0 and len(owner.z_energy) < needed:
                return False
        return True

    def _leader_requirement_string_met(self, state: GameState, *, owner_player_id: int, raw_req: object) -> bool:
        if not isinstance(raw_req, str) or not raw_req.strip():
            return True
        owner = state.players[owner_player_id]
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        req = raw_req.lower()
        leader_colors = {
            part.strip().lower()
            for part in str(leader.color or leader_runtime.color or "").replace("/", ",").split(",")
            if part.strip()
        }
        required_colors = {color for color in ("red", "blue", "green", "yellow", "black", "white") if color in req}
        if required_colors and leader_colors.isdisjoint(required_colors):
            return False
        required_from_angle = {part.strip().lower() for part in re.findall(r"<([^>]+)>", req) if part.strip()}
        required_from_guillemets = {part.strip().lower() for part in re.findall(r"â‰ª([^â‰«]+)â‰«", req) if part.strip()}
        required_from_fallback = set()
        if not required_from_angle and not required_from_guillemets:
            required_from_fallback = {
                part.strip().lower()
                for part in re.findall(r"\?([a-z0-9:' -]+)\?", req)
                if part.strip()
            }
        leader_traits = {part.strip().lower() for part in (leader_runtime.traits or ()) if part.strip()}
        leader_characters = {part.strip().lower() for part in (leader_runtime.characters or ()) if part.strip()}
        if not leader_traits and getattr(leader, "traits", ()):
            leader_traits = {part.strip().lower() for part in (leader.traits or ()) if part.strip()}
        if not leader_characters and getattr(leader, "characters", ()):
            leader_characters = {part.strip().lower() for part in (leader.characters or ()) if part.strip()}
        if required_from_angle and (leader_traits | leader_characters).isdisjoint(required_from_angle):
            return False
        if required_from_guillemets and leader_traits.isdisjoint(required_from_guillemets):
            return False
        if required_from_fallback and (leader_traits | leader_characters).isdisjoint(required_from_fallback):
            return False
        required_leader_names = {
            part.strip().lower()
            for part in re.findall(r"\{([^}]+)\}", req)
            if part.strip() and self._parse_cost_token_value(part.strip())[0] <= 0
        }
        if required_leader_names:
            leader_name = str(leader_runtime.card_name or getattr(leader, "card_name", "") or "").strip().lower()
            if not leader_name:
                return False
            if all(required_name not in leader_name and leader_name not in required_name for required_name in required_leader_names):
                return False
        return True

    def _arrival_header_requirements_met(self, state: GameState, *, owner_player_id: int, raw_req: object) -> bool:
        if not isinstance(raw_req, str) or not raw_req.strip():
            return True
        owner = state.players[owner_player_id]
        leader = owner.leader_area
        leader_runtime = self._resolve_card_runtime_data(leader.card_id)
        if not self._leader_requirement_string_met(state, owner_player_id=owner_player_id, raw_req=raw_req):
            return False
        return self._text_hand_cost_reduction_requirements_met(
            raw_req,
            state=state,
            owner=owner,
            leader=leader,
            leader_runtime=leader_runtime,
        )

    def _card_matches_effect_filters(
        self,
        card: CardInstance,
        *,
        allowed_colors: set[str],
        required_traits: set[str],
        required_all_traits: set[str] | None = None,
        required_characters: set[str],
        required_name_contains: str,
        required_skill_text_contains: str = "",
        required_card_types: set[str] | None = None,
        min_character_count: int = 0,
        min_power: int = -1,
        min_energy_cost: int = -1,
    ) -> bool:
        runtime = self._resolve_card_runtime_data(card.card_id)
        normalized_allowed_colors = {part.strip().lower() for part in allowed_colors if part.strip()}
        normalized_required_traits = {part.strip().lower() for part in required_traits if part.strip()}
        normalized_required_characters = {part.strip().lower() for part in required_characters if part.strip()}
        normalized_required_card_types = {part.strip().upper() for part in (required_card_types or set()) if part.strip()}
        runtime_colors = {
            part.strip().lower()
            for part in str(runtime.color or "").replace("/", ",").split(",")
            if part.strip()
        }
        if not runtime_colors and card.color:
            runtime_colors = {
                part.strip().lower()
                for part in str(card.color).replace("/", ",").split(",")
                if part.strip()
            }
        runtime_traits = {part.strip().lower() for part in (runtime.traits or ()) if part.strip()}
        runtime_characters = {part.strip().lower() for part in (runtime.characters or ()) if part.strip()}
        if not runtime_traits and getattr(card, "traits", ()):
            runtime_traits = {part.strip().lower() for part in (card.traits or ()) if part.strip()}
        if not runtime_characters and getattr(card, "characters", ()):
            runtime_characters = {part.strip().lower() for part in (card.characters or ()) if part.strip()}
        runtime_name = str(runtime.card_name or getattr(card, "card_name", "") or "").upper()
        runtime_card_type = str(runtime.card_type or card.card_type or "").upper()
        runtime_skill_text = str(card.skill_text_raw or runtime.skill_text_raw or "").lower()
        runtime_power_value = runtime.power
        if runtime_power_value is None or (int(runtime_power_value or 0) == 0 and int(card.power or 0) != 0):
            runtime_power = int(card.power or 0)
        else:
            runtime_power = int(runtime_power_value or 0)
        runtime_energy_cost_value = runtime.energy_cost
        if runtime_energy_cost_value is None or (int(runtime_energy_cost_value or 0) == 0 and int(card.energy_cost or 0) != 0):
            runtime_energy_cost = int(card.energy_cost or 0)
        else:
            runtime_energy_cost = int(runtime_energy_cost_value or 0)
        if normalized_allowed_colors and runtime_colors.isdisjoint(normalized_allowed_colors):
            return False
        if normalized_required_card_types and runtime_card_type not in normalized_required_card_types:
            return False
        if normalized_required_traits and runtime_traits.isdisjoint(normalized_required_traits):
            return False
        normalized_required_all_traits = {part.strip().lower() for part in (required_all_traits or set()) if part.strip()}
        if normalized_required_all_traits and not normalized_required_all_traits.issubset(runtime_traits):
            return False
        if normalized_required_characters and runtime_characters.isdisjoint(normalized_required_characters):
            return False
        if min_character_count > 0 and len(runtime_characters) < min_character_count:
            return False
        if min_power >= 0 and runtime_power < min_power:
            return False
        if min_energy_cost >= 0 and runtime_energy_cost < min_energy_cost:
            return False
        if required_name_contains and required_name_contains not in runtime_name:
            return False
        if required_skill_text_contains:
            normalized_skill_probe = required_skill_text_contains.lower()
            if normalized_skill_probe not in runtime_skill_text:
                if (
                    normalized_skill_probe.startswith("[")
                    and normalized_skill_probe.endswith("]")
                    and normalized_skill_probe[:-1] in runtime_skill_text
                ):
                    pass
                else:
                    return False
        return True

    def _leader_under_card_matches_cost_step(self, owner_player_id: int, card_id: int, step: SkillCostStep) -> bool:
        candidate = self._create_card_instance(
            next_instance_id=-(owner_player_id * 100000 + int(card_id)),
            card_id=int(card_id),
            owner_id=owner_player_id,
        )
        forbidden_card_types = {
            part.strip().upper()
            for part in str(step.params.get("forbidden_card_types", "")).replace("|", ",").split(",")
            if part.strip()
        }
        if forbidden_card_types:
            runtime_type = str(self._resolve_card_runtime_data(candidate.card_id).card_type or candidate.card_type or "").upper()
            if runtime_type in forbidden_card_types:
                return False
        return self._card_matches_effect_filters(
            candidate,
            allowed_colors={
                part.strip().lower()
                for part in str(step.params.get("allowed_colors", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_traits={
                part.strip()
                for part in str(step.params.get("required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_characters={
                part.strip()
                for part in str(step.params.get("required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_name_contains=str(step.params.get("required_name_contains", "")).strip().upper(),
            required_card_types={
                part.strip().upper()
                for part in str(step.params.get("required_card_types", "")).replace("|", ",").split(",")
                if part.strip()
            },
        )

    def _can_pay_send_owner_leader_under_to_drop_cost(self, player: PlayerState, step: SkillCostStep) -> bool:
        leader_under = tuple(player.leader_area.stacked_card_ids or ())
        matching = sum(1 for card_id in leader_under if self._leader_under_card_matches_cost_step(player.player_id, int(card_id), step))
        return matching >= int(step.amount or 0)

    def _can_pay_send_owner_battle_under_to_drop_cost(
        self,
        state: GameState,
        player: PlayerState,
        step: SkillCostStep,
    ) -> bool:
        hosts = self._owner_battle_hosts_with_under_cards(
            state,
            owner_player_id=player.player_id,
            required_count=int(step.amount or 0),
            allowed_colors={
                part.strip()
                for part in str(step.params.get("required_host_allowed_colors", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_traits={
                part.strip()
                for part in str(step.params.get("required_host_required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_characters={
                part.strip()
                for part in str(step.params.get("required_host_required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_name_contains=str(step.params.get("required_host_name_contains", "")).strip().upper(),
            required_card_types={
                part.strip().upper()
                for part in str(step.params.get("required_host_card_types", "")).replace("|", ",").split(",")
                if part.strip()
            },
        )
        return bool(hosts)

    def _pay_send_owner_leader_under_to_drop_cost(
        self,
        state: GameState,
        player: PlayerState,
        step: SkillCostStep,
    ) -> dict[str, int | str | None]:
        leader_under = list(player.leader_area.stacked_card_ids or ())
        moved = 0
        idx = 0
        metadata: dict[str, int | str | None] = {}
        while idx < len(leader_under) and moved < int(step.amount or 0):
            card_id = int(leader_under[idx])
            if not self._leader_under_card_matches_cost_step(player.player_id, card_id, step):
                idx += 1
                continue
            leader_under.pop(idx)
            moved_card = self._create_card_instance(next_instance_id=state.next_instance_id, card_id=card_id, owner_id=player.player_id)
            state.next_instance_id += 1
            player.drop.append(moved_card)
            moved += 1
            if moved == 1:
                metadata["cost_target_instance_id"] = int(moved_card.instance_id)
                metadata["cost_target_card_id"] = int(moved_card.card_id)
                metadata["cost_target_zone"] = "leader_under"
        if moved < int(step.amount or 0):
            raise RulesViolation("Not enough matching cards under leader to pay skill cost.")
        player.leader_area.stacked_card_ids = tuple(leader_under)
        self._register_leader_under_card_effects(state, player_id=player.player_id)
        return metadata

    def _pay_send_owner_battle_under_to_drop_cost(
        self,
        state: GameState,
        player: PlayerState,
        step: SkillCostStep,
    ) -> None:
        moved = self._move_up_to_n_from_under_matching_owner_battle_to_drop(
            state,
            owner_player_id=player.player_id,
            amount=int(step.amount or 0),
            allowed_colors={
                part.strip()
                for part in str(step.params.get("required_host_allowed_colors", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_traits={
                part.strip()
                for part in str(step.params.get("required_host_required_traits", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_characters={
                part.strip()
                for part in str(step.params.get("required_host_required_characters", "")).replace("|", ",").split(",")
                if part.strip()
            },
            required_name_contains=str(step.params.get("required_host_name_contains", "")).strip().upper(),
            required_card_types={
                part.strip().upper()
                for part in str(step.params.get("required_host_card_types", "")).replace("|", ",").split(",")
                if part.strip()
            },
        )
        if moved < int(step.amount or 0):
            raise RulesViolation("Not enough matching cards under battle-area host to pay skill cost.")

    def _card_has_runtime_label(self, card: CardInstance, label: str) -> bool:
        normalized = str(label or "").strip().lower()
        if not normalized:
            return False
        runtime = self._resolve_card_runtime_data(card.card_id)
        runtime_name = str(runtime.card_name or "").strip().lower()
        runtime_traits = {part.strip().lower() for part in (runtime.traits or ()) if part.strip()}
        runtime_characters = {part.strip().lower() for part in (runtime.characters or ()) if part.strip()}
        runtime_keywords = {part.strip().lower() for part in (runtime.keywords or ()) if part.strip()}
        card_traits = {part.strip().lower() for part in (getattr(card, "traits", ()) or ()) if part.strip()}
        card_characters = {part.strip().lower() for part in (getattr(card, "characters", ()) or ()) if part.strip()}
        card_keywords = {part.strip().lower() for part in (getattr(card, "keywords", ()) or ()) if part.strip()}
        return (
            normalized in runtime_name
            or normalized in runtime_traits
            or normalized in runtime_characters
            or normalized in runtime_keywords
            or normalized in card_traits
            or normalized in card_characters
            or normalized in card_keywords
        )

    def _owner_leader_has_character(self, state: GameState, *, owner_player_id: int, character_name: str) -> bool:
        owner = state.players.get(owner_player_id)
        if owner is None:
            return False
        normalized = str(character_name or "").strip().lower()
        if not normalized:
            return False
        runtime = self._resolve_card_runtime_data(owner.leader_area.card_id)
        characters = {
            part.strip().lower()
            for part in [*tuple(owner.leader_area.characters or ()), *tuple(runtime.characters or ())]
            if part.strip()
        }
        return normalized in characters

    def _wish_conditions_met(self, state: GameState, *, player_id: int, spec: dict[str, object]) -> bool:
        player = state.players[player_id]
        checks: list[bool] = []
        life_at_most = int(spec.get("life_at_most", -1) or -1)
        if life_at_most >= 0:
            checks.append(len(player.life) <= life_at_most)
        drop_dragon_ball_count = int(spec.get("drop_dragon_ball_count", -1) or -1)
        if drop_dragon_ball_count >= 0:
            checks.append(sum(1 for card in player.drop if self._card_has_runtime_label(card, "dragon ball")) >= drop_dragon_ball_count)
        if not checks:
            return False
        if str(spec.get("condition_mode", "and")).strip().lower() == "or":
            return any(checks)
        return all(checks)

    def _awaken_conditions_met(self, state: GameState, *, player_id: int, spec: dict[str, object]) -> bool:
        player = state.players[player_id]
        checks: list[bool] = []
        life_at_most = int(spec.get("life_at_most", -1) or -1)
        if life_at_most >= 0:
            checks.append(len(player.life) <= life_at_most)
        owner_energy_at_least = int(spec.get("owner_energy_at_least", -1) or -1)
        if owner_energy_at_least >= 0:
            checks.append(len(player.energy) >= owner_energy_at_least)
        required_name_in_play = str(spec.get("required_owner_battle_name_in_play", "") or "").strip().upper()
        if required_name_in_play:
            checks.append(
                any(required_name_in_play in str(card.card_name or "").upper() for card in [*player.battle_area, *player.unison_area])
            )
        required_owner_token_name = str(spec.get("required_owner_token_name", "") or "").strip().lower()
        required_owner_token_count = int(spec.get("required_owner_token_count", -1) or -1)
        if required_owner_token_name and required_owner_token_count >= 0:
            checks.append(
                sum(
                    1
                    for card in player.battle_area
                    if str(getattr(card, "card_name", "") or "").strip().lower() == required_owner_token_name
                )
                >= required_owner_token_count
            )
        required_owner_unison_color = str(spec.get("required_owner_unison_color", "") or "").strip().lower()
        required_owner_unison_specified_cost = int(spec.get("required_owner_unison_specified_cost", -1) or -1)
        if required_owner_unison_color or required_owner_unison_specified_cost >= 0:
            checks.append(
                any(
                    (
                        not required_owner_unison_color
                        or required_owner_unison_color
                        in {
                            part.strip().lower()
                            for part in str(
                                card.color or self._resolve_card_runtime_data(card.card_id).color or ""
                            ).replace("/", ",").split(",")
                            if part.strip()
                        }
                    )
                    and (
                        required_owner_unison_specified_cost < 0
                        or sum(int(count) for _code, count in tuple(getattr(card, "specified_costs", ()) or ()))
                        == required_owner_unison_specified_cost
                    )
                    for card in player.unison_area
                )
            )
        required_owner_battle_area_card_type = str(spec.get("required_owner_battle_area_card_type", "") or "").strip().upper()
        required_owner_battle_area_color = str(spec.get("required_owner_battle_area_color", "") or "").strip().lower()
        required_owner_battle_area_energy_cost = int(spec.get("required_owner_battle_area_energy_cost", -1) or -1)
        if required_owner_battle_area_card_type or required_owner_battle_area_color or required_owner_battle_area_energy_cost >= 0:
            checks.append(
                any(
                    (
                        not required_owner_battle_area_card_type
                        or str(card.card_type or self._resolve_card_runtime_data(card.card_id).card_type or "").upper()
                        == required_owner_battle_area_card_type
                    )
                    and (
                        not required_owner_battle_area_color
                        or required_owner_battle_area_color
                        in {
                            part.strip().lower()
                            for part in str(
                                card.color or self._resolve_card_runtime_data(card.card_id).color or ""
                            ).replace("/", ",").split(",")
                            if part.strip()
                        }
                    )
                    and (
                        required_owner_battle_area_energy_cost < 0
                        or int(
                            getattr(card, "energy_cost", None)
                            or getattr(self._resolve_card_runtime_data(card.card_id), "energy_cost", None)
                            or 0
                        )
                        == required_owner_battle_area_energy_cost
                    )
                    for card in player.battle_area
                )
            )
        if not checks:
            return len(player.life) <= 4
        if str(spec.get("condition_mode", "and")).strip().lower() == "or":
            return any(checks)
        return all(checks)

    def _z_awaken_conditions_met(self, state: GameState, *, player_id: int, spec: dict[str, object]) -> bool:
        player = state.players[player_id]
        checks: list[bool] = []
        life_at_most = int(spec.get("life_at_most", -1) or -1)
        if life_at_most >= 0:
            checks.append(len(player.life) <= life_at_most)
        if bool(spec.get("all_energy_resting", False)):
            checks.append(bool(player.energy) and all(card.resting for card in player.energy))
        min_combo_area_count = int(spec.get("min_combo_area_count", -1) or -1)
        if min_combo_area_count >= 0:
            checks.append(len(player.combo_area) >= min_combo_area_count)
        min_owner_drop_matching = int(spec.get("min_owner_drop_matching", -1) or -1)
        if min_owner_drop_matching >= 0:
            required_traits = {
                str(part).strip().lower()
                for part in tuple(spec.get("required_owner_drop_traits", ()) or ())
                if str(part).strip()
            }
            required_characters = {
                str(part).strip().lower()
                for part in tuple(spec.get("required_owner_drop_characters", ()) or ())
                if str(part).strip()
            }
            matching_drop_count = sum(
                1
                for card in player.drop
                if self._card_matches_effect_filters(
                    card,
                    allowed_colors=set(),
                    required_traits=required_traits,
                    required_characters=required_characters,
                    required_name_contains="",
                )
            )
            checks.append(matching_drop_count >= min_owner_drop_matching)
        if not checks:
            return True
        return all(checks)

    def _leader_matches_z_awaken_target(self, leader: CardInstance, spec: dict[str, object]) -> bool:
        runtime = self._resolve_card_runtime_data(leader.card_id, side="back" if getattr(leader, "awakened", False) else "front")
        leader_name = str(runtime.card_name or leader.card_number or "").upper()
        leader_color = str(runtime.color or leader.color or "").strip().lower()
        leader_characters = {part.strip().lower() for part in (runtime.characters or ()) if part.strip()}
        if not leader_characters and getattr(leader, "characters", ()):
            leader_characters = {part.strip().lower() for part in (leader.characters or ()) if part.strip()}
        required_name_contains = str(spec.get("required_name_contains", "") or "").strip().upper()
        if required_name_contains and required_name_contains not in leader_name:
            return False
        required_characters = [str(part).strip().lower() for part in tuple(spec.get("required_characters", ()) or ()) if str(part).strip()]
        if required_characters:
            if bool(spec.get("require_all_characters", False)):
                if any(character not in leader_characters for character in required_characters):
                    return False
            elif leader_characters.isdisjoint(set(required_characters)):
                return False
        required_color = str(spec.get("required_color", "") or "").strip().lower()
        if required_color:
            leader_colors = {part.strip().lower() for part in leader_color.replace("/", ",").split(",") if part.strip()}
            if required_color not in leader_colors:
                return False
            if bool(spec.get("require_mono_color", False)) and len(leader_colors) != 1:
                return False
        return True

    def _matching_z_awaken_z_energy_warp_indexes(
        self,
        state: GameState,
        *,
        player_id: int,
        spec: dict[str, object],
    ) -> list[int] | None:
        requirements = [
            (str(character).strip().lower(), int(amount))
            for character, amount in tuple(spec.get("z_energy_warp_required_characters", ()) or ())
            if str(character).strip() and int(amount) > 0
        ]
        if not requirements:
            return []
        player = state.players[player_id]
        chosen_indexes: list[int] = []
        used_indexes: set[int] = set()
        for character, amount in requirements:
            matched_indexes: list[int] = []
            for idx, card in enumerate(player.z_energy):
                if idx in used_indexes:
                    continue
                if not self._card_matches_effect_filters(
                    card,
                    allowed_colors=set(),
                    required_traits=set(),
                    required_characters={character},
                    required_name_contains="",
                ):
                    continue
                matched_indexes.append(idx)
                used_indexes.add(idx)
                if len(matched_indexes) >= amount:
                    break
            if len(matched_indexes) < amount:
                return None
            chosen_indexes.extend(matched_indexes)
        return chosen_indexes

    def _apply_z_stack_from_z_deck(
        self,
        state: GameState,
        *,
        player_id: int,
        host: CardInstance,
        source_skill_text: object,
    ) -> None:
        spec = self._parse_z_stack_spec(source_skill_text)
        if spec is None:
            return
        player = state.players[player_id]
        chosen_indexes: list[int] = []
        allowed_colors = {
            str(part).strip().lower()
            for part in tuple(spec.get("allowed_colors", ()) or ())
            if str(part).strip()
        }
        required_traits = {
            str(part).strip().lower()
            for part in tuple(spec.get("required_traits", ()) or ())
            if str(part).strip()
        }
        max_energy_cost = int(spec.get("max_energy_cost", -1) or -1)
        required_card_type = str(spec.get("required_card_type", "") or "").strip().upper()
        require_different_character_names = bool(spec.get("require_different_character_names", False))
        max_count = int(spec.get("count", 0) or 0)
        if max_count <= 0:
            return
        chosen_character_names: set[str] = set()
        for idx, row in enumerate(player.z_deck):
            runtime = self._resolve_card_runtime_data(row.card_id)
            candidate = CardInstance(
                instance_id=-1 - idx,
                card_id=row.card_id,
                owner_id=player_id,
                card_type=str(runtime.card_type or row.card_type or ""),
                color=str(runtime.color or row.color or ""),
                energy_cost=runtime.energy_cost if runtime.energy_cost is not None else row.energy_cost,
                traits=tuple(runtime.traits or row.traits or ()),
                characters=tuple(runtime.characters or row.characters or ()),
            )
            if not self._card_matches_effect_filters(
                candidate,
                allowed_colors=allowed_colors,
                required_traits=required_traits,
                required_characters=set(),
                required_name_contains="",
                required_card_types={required_card_type} if required_card_type else None,
                min_power=-1,
            ):
                continue
            runtime_cost = int(runtime.energy_cost if runtime.energy_cost is not None else (row.energy_cost or 0))
            if max_energy_cost >= 0 and runtime_cost > max_energy_cost:
                continue
            runtime_characters = {
                part.strip().lower()
                for part in tuple(runtime.characters or row.characters or ())
                if str(part).strip()
            }
            if require_different_character_names and runtime_characters and not chosen_character_names.isdisjoint(runtime_characters):
                continue
            chosen_indexes.append(idx)
            if require_different_character_names:
                chosen_character_names.update(runtime_characters)
            if len(chosen_indexes) >= max_count:
                break
        if not chosen_indexes:
            return
        chosen_card_ids = [int(player.z_deck[idx].card_id) for idx in chosen_indexes]
        for idx in sorted(chosen_indexes, reverse=True):
            player.z_deck.pop(idx)
        host.stacked_card_ids = tuple(list(host.stacked_card_ids) + chosen_card_ids)
        self._checkpoint(state, "leader_z_stack_applied")

    def _resolve_effect_int_param(self, state: GameState, reg: EffectRegistration, key: str, *, default: int) -> int:
        raw = reg.handler_params.get(key, default)
        if isinstance(raw, bool):
            return int(raw)
        if isinstance(raw, int):
            return raw
        if isinstance(raw, str):
            txt = raw.strip().lower()
            if txt.lstrip("-").isdigit():
                return int(txt)
            if txt.startswith("expr:"):
                return self._eval_effect_int_expr(state, reg, txt[5:].strip(), default=default)
            return self._eval_effect_int_expr(state, reg, txt, default=default)
        return default

    def _eval_effect_int_expr(self, state: GameState, reg: EffectRegistration, expr: str, *, default: int) -> int:
        owner = state.players.get(reg.owner_player_id)
        if owner is None:
            return default
        opponent = state.players.get(self._opponent_of(reg.owner_player_id))
        source = self._find_by_instance(owner, reg.source_zone, reg.source_instance_id)
        values: dict[str, int] = {
            "owner_energy_count": len(owner.energy),
            "owner_energy_color_count": len(
                {
                    part.strip().lower()
                    for energy in owner.energy
                    for part in str(energy.color or "").replace("/", ",").split(",")
                    if part.strip()
                }
            ),
            "owner_drop_count": len(owner.drop),
            "owner_life_count": len(owner.life),
            "owner_battle_count": len(owner.battle_area),
            "owner_unison_count": len(owner.unison_area),
            "owner_warp_count": len(owner.warp),
            "owner_energy_markers": int(owner.energy_markers),
            "owner_unison_markers_total": sum(max(c.markers, 0) for c in owner.unison_area),
            "opponent_battle_count": len(opponent.battle_area) if opponent is not None else 0,
            "opponent_unison_count": len(opponent.unison_area) if opponent is not None else 0,
            "source_markers": int(source.markers) if source is not None else 0,
            "source_power": int(source.power) if source is not None else 0,
            "x": int(source.markers) if source is not None else 0,
        }
        mult = re.fullmatch(r"([a-z_]+)\s*\*\s*(-?\d+)", expr)
        if mult is not None:
            left = int(values.get(mult.group(1), default))
            right = int(mult.group(2))
            return left * right
        return int(values.get(expr, default))

    def _choose_effect_target_index(
        self,
        state: GameState,
        reg: EffectRegistration,
        candidates: list[CardInstance],
        policy: str,
    ) -> int:
        if not candidates:
            return 0
        if self._effect_target_chooser is not None:
            try:
                selected = int(self._effect_target_chooser(state, reg, candidates, policy))
                if selected < 0:
                    return 0
                if selected >= len(candidates):
                    return len(candidates) - 1
                return selected
            except Exception:
                pass
        if policy == "lowest_power":
            min_idx = 0
            min_key = (candidates[0].power, candidates[0].instance_id)
            for i, c in enumerate(candidates[1:], start=1):
                key = (c.power, c.instance_id)
                if key < min_key:
                    min_key = key
                    min_idx = i
            return min_idx
        return 0

    def _choose_effect_target_indexes(
        self,
        state: GameState,
        reg: EffectRegistration,
        candidates: list[CardInstance],
        count: int,
        policy: str,
    ) -> list[int]:
        if not candidates or count <= 0:
            return []
        limit = min(count, len(candidates))
        if self._effect_multi_target_chooser is not None:
            try:
                raw = self._effect_multi_target_chooser(state, reg, candidates, limit, policy)
                chosen: list[int] = []
                for value in list(raw):
                    idx = int(value)
                    if idx < 0:
                        idx = 0
                    if idx >= len(candidates):
                        idx = len(candidates) - 1
                    if idx not in chosen:
                        chosen.append(idx)
                    if len(chosen) >= limit:
                        break
                if chosen:
                    return chosen
            except Exception:
                pass
        if limit == 1:
            return [self._choose_effect_target_index(state, reg, candidates, policy)]

        if policy == "all":
            return list(range(limit))
        if policy == "lowest_power":
            ordered = sorted(range(len(candidates)), key=lambda i: (candidates[i].power, candidates[i].instance_id))
            return ordered[:limit]
        return list(range(limit))

    @staticmethod
    def _is_effect_source_active(state: GameState, reg: EffectRegistration) -> bool:
        player = state.players.get(reg.owner_player_id)
        if player is None:
            return False
        if reg.trigger in {"self_koed", "self_hidden_battle_to_drop"}:
            return (
                any(c.instance_id == reg.source_instance_id for c in player.drop)
                or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                or any(c.instance_id == reg.source_instance_id for c in player.battle_area)
                or any(c.instance_id == reg.source_instance_id for c in player.unison_area)
            )
        if reg.source_zone == "leader":
            return player.leader_area.instance_id == reg.source_instance_id
        if reg.source_zone == "leader_under":
            if reg.trigger in {"self_activate_main", "self_activate_battle", "self_placed_into_drop", "self_comboed", "self_comboed_battle_end"}:
                return (
                    any(int(card_id) == int(reg.source_card_id) for card_id in tuple(player.leader_area.stacked_card_ids or ()))
                    or any(c.instance_id == reg.source_instance_id for c in player.battle_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.unison_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.combo_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.warp)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return any(int(card_id) == int(reg.source_card_id) for card_id in tuple(player.leader_area.stacked_card_ids or ()))
        if reg.source_zone == "battle_under":
            current_battle_under_instance_ids = {
                RulesEngine._battle_under_instance_id(host.instance_id, under_index)
                for host in player.battle_area
                for under_index, owner_id in enumerate(RulesEngine._stacked_owner_ids_for_host(host))
                if int(owner_id) == int(player.player_id)
            }
            if reg.trigger in {"self_activate_main", "self_activate_battle", "self_placed_into_drop"}:
                return (
                    reg.source_instance_id in current_battle_under_instance_ids
                    or any(c.instance_id == reg.source_instance_id for c in player.battle_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.warp)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return reg.source_instance_id in current_battle_under_instance_ids
        if reg.source_zone == "battle":
            battle_anywhere = any(c.instance_id == reg.source_instance_id for other in state.players.values() for c in other.battle_area)
            if reg.trigger in {"self_activate_main", "self_activate_battle", "owner_card_left_battle_area", "self_left_battle_area"}:
                return (
                    battle_anywhere
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.warp)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return battle_anywhere
        if reg.source_zone == "energy":
            return any(c.instance_id == reg.source_instance_id for c in player.energy)
        if reg.source_zone == "unison":
            unison_anywhere = any(c.instance_id == reg.source_instance_id for other in state.players.values() for c in other.unison_area)
            if reg.trigger in {"self_placed_under_owner_card", "self_placed_under_by_union"}:
                placed_under_anywhere = any(
                    int(card_id) == int(reg.source_card_id)
                    for player in state.players.values()
                    for card_id in tuple(player.leader_area.stacked_card_ids or ())
                ) or any(
                    int(card_id) == int(reg.source_card_id)
                    for player in state.players.values()
                    for host in player.battle_area
                    for card_id in tuple(host.stacked_card_ids or ())
                )
                return unison_anywhere or placed_under_anywhere
            return unison_anywhere
        if reg.source_zone == "combo":
            if reg.trigger == "self_activate_battle":
                return (
                    any(c.instance_id == reg.source_instance_id for c in player.combo_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                )
            return any(c.instance_id == reg.source_instance_id for c in player.combo_area)
        if reg.source_zone == "hand":
            if reg.trigger in {"self_activate_main", "self_activate_battle", "self_in_hand_sent_to_drop_or_warp", "self_placed_into_drop", "self_added_to_energy", "self_comboed", "self_comboed_battle_end", "owner_battle_ko_opponent_battle_battle_end", "owner_battle_koed_by_opponent_attack_battle_end"}:
                return (
                    any(c.instance_id == reg.source_instance_id for c in player.hand)
                    or any(c.instance_id == reg.source_instance_id for c in player.combo_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.battle_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.energy)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.warp)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return any(c.instance_id == reg.source_instance_id for c in player.hand)
        if reg.source_zone == "drop":
            if reg.trigger in {"self_activate_main", "self_activate_battle", "self_activate_extra_from_hand", "self_comboed", "self_comboed_battle_end"}:
                return (
                    any(c.instance_id == reg.source_instance_id for c in player.combo_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.battle_area)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.warp)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return any(c.instance_id == reg.source_instance_id for c in player.drop)
        if reg.source_zone == "warp":
            return any(c.instance_id == reg.source_instance_id for c in player.warp)
        if reg.source_zone == "z_energy":
            if reg.trigger == "self_placed_into_drop":
                return (
                    any(c.instance_id == reg.source_instance_id for c in player.z_energy)
                    or any(c.instance_id == reg.source_instance_id for c in player.drop)
                    or any(c.instance_id == reg.source_instance_id for c in player.removed_from_game)
                )
            return any(c.instance_id == reg.source_instance_id for c in player.z_energy)
        return False

    def _checkpoint(self, state: GameState, name: str) -> None:
        state.checkpoints.append(
            CheckpointEvent(
                index=state.next_checkpoint_index,
                turn_number=state.turn_number,
                phase=state.phase,
                active_player=state.active_player,
                name=name,
            )
        )
        state.next_checkpoint_index += 1

    def _create_card_instance(self, *, next_instance_id: int, card_id: int, owner_id: int) -> CardInstance:
        runtime = self._resolve_card_runtime_data(card_id)
        return CardInstance(
            instance_id=next_instance_id,
            card_id=card_id,
            owner_id=owner_id,
            card_number=runtime.card_number,
            power=runtime.power,
            card_type=runtime.card_type,
            color=runtime.color,
            energy_cost_raw=runtime.energy_cost_raw,
            energy_cost=runtime.energy_cost,
            combo_cost=runtime.combo_cost,
            combo_power=runtime.combo_power,
            keywords=runtime.keywords,
            has_counter=runtime.has_counter,
            counter_modes=runtime.counter_modes,
            has_counter_attack=runtime.has_counter_attack,
            has_counter_battle_card_attack=runtime.has_counter_battle_card_attack,
            has_counter_play=runtime.has_counter_play,
            has_counter_counter=runtime.has_counter_counter,
            has_activate_main=runtime.has_activate_main,
            has_activate_battle=runtime.has_activate_battle,
            has_auto=runtime.has_auto,
            has_permanent=runtime.has_permanent,
            has_draw=runtime.has_draw,
            max_draw=runtime.max_draw,
            auto_once_per_turn=runtime.auto_once_per_turn,
            auto_draw_on_play=runtime.auto_draw_on_play,
            auto_draw_on_attack=runtime.auto_draw_on_attack,
            has_barrier=runtime.has_barrier,
            z_energy_cost=runtime.z_energy_cost,
            specified_costs=runtime.specified_costs,
            skill_text_raw=runtime.skill_text_raw,
            has_awaken=runtime.has_awaken,
            activate_limit_once_per_turn=runtime.activate_limit_once_per_turn,
            has_super_combo=runtime.has_super_combo,
            sparking_threshold=runtime.sparking_threshold,
            traits=runtime.traits,
            characters=runtime.characters,
        )

    def _create_z_deck_card(self, *, card_id: int, owner_id: int) -> ZDeckCard:
        runtime = self._resolve_card_runtime_data(card_id)
        return ZDeckCard(
            card_id=card_id,
            owner_id=owner_id,
            face_up=False,
            card_name=runtime.card_name,
            card_type=runtime.card_type,
            color=runtime.color,
            energy_cost=runtime.energy_cost,
            traits=runtime.traits,
            characters=runtime.characters,
        )

    def _resolve_card_runtime_data(self, card_id: int, *, side: str = "front") -> CardRuntimeData:
        cache_key = (card_id, side)
        if cache_key in self._card_cache:
            return self._card_cache[cache_key]
        runtime = CardRuntimeData()
        if self._card_repository is not None:
            try:
                card = self._card_repository.get_by_id(card_id, source_table="cards")
                runtime = self._build_card_runtime_data(card, side=side)
            except Exception:
                runtime = CardRuntimeData()
        self._card_cache[cache_key] = runtime
        return runtime

    def _apply_runtime_to_card_instance(self, card: CardInstance, runtime: CardRuntimeData, *, awakened_flag: bool) -> None:
        card.card_number = runtime.card_number
        card.power = runtime.power
        card.card_type = runtime.card_type
        card.color = runtime.color
        card.energy_cost_raw = runtime.energy_cost_raw
        card.energy_cost = runtime.energy_cost
        card.combo_cost = runtime.combo_cost
        card.combo_power = runtime.combo_power
        card.keywords = runtime.keywords
        card.has_counter = runtime.has_counter
        card.counter_modes = runtime.counter_modes
        card.has_counter_attack = runtime.has_counter_attack
        card.has_counter_battle_card_attack = runtime.has_counter_battle_card_attack
        card.has_counter_play = runtime.has_counter_play
        card.has_counter_counter = runtime.has_counter_counter
        card.has_activate_main = runtime.has_activate_main
        card.has_activate_battle = runtime.has_activate_battle
        card.has_auto = runtime.has_auto
        card.has_permanent = runtime.has_permanent
        card.has_draw = runtime.has_draw
        card.max_draw = runtime.max_draw
        card.auto_once_per_turn = runtime.auto_once_per_turn
        card.auto_draw_on_play = runtime.auto_draw_on_play
        card.auto_draw_on_attack = runtime.auto_draw_on_attack
        card.has_barrier = runtime.has_barrier
        card.z_energy_cost = runtime.z_energy_cost
        card.specified_costs = runtime.specified_costs
        card.skill_text_raw = runtime.skill_text_raw
        card.has_awaken = False
        card.activate_limit_once_per_turn = runtime.activate_limit_once_per_turn
        card.has_super_combo = runtime.has_super_combo
        card.sparking_threshold = runtime.sparking_threshold
        card.traits = runtime.traits
        card.characters = runtime.characters
        card.awakened = awakened_flag

    def _apply_leader_back_side(self, leader: CardInstance) -> None:
        runtime = self._resolve_card_runtime_data(leader.card_id, side="back")
        self._apply_runtime_to_card_instance(leader, runtime, awakened_flag=True)

    def _build_card_runtime_data(self, card: Any, *, side: str) -> CardRuntimeData:
        is_back = side == "back"
        power_raw = getattr(card, "card_back_power", None) if is_back else getattr(card, "power_int", None)
        skill_text = getattr(card, "card_back_skill_unstyled", None) if is_back else getattr(card, "card_skill_unstyled", None)
        keywords = tuple(getattr(card, "keywords", ()) or ())
        text_counter_modes = self._text_counter_modes(skill_text)
        merged_keywords = tuple(list(keywords) + [mode for mode in text_counter_modes if mode not in keywords])
        traits_raw = getattr(card, "card_back_traits_json", None) if is_back else getattr(card, "card_traits_json", None)
        characters_raw = getattr(card, "card_back_character_json", None) if is_back else getattr(card, "card_character_json", None)
        has_draw_flag = bool(getattr(card, "has_draw", False))
        return CardRuntimeData(
            card_number=str(getattr(card, "card_number", None) or ""),
            card_name=str(getattr(card, "card_name", None) or ""),
            power=int(power_raw) if power_raw is not None else 15000,
            card_type=str(getattr(card, "card_type", None) or "BATTLE"),
            color=getattr(card, "card_color", None),
            energy_cost_raw=getattr(card, "card_energy_cost", None),
            energy_cost=getattr(card, "energy_cost_int", None),
            combo_cost=getattr(card, "combo_cost_int", None),
            combo_power=getattr(card, "combo_power_int", None),
            keywords=merged_keywords,
            has_counter=bool(getattr(card, "has_counter", False)) or self._text_has_counter(skill_text),
            counter_modes=tuple(k for k in merged_keywords if str(k).startswith("Counter:")),
            has_counter_attack=bool(getattr(card, "has_counter_attack", False)) or self._text_has_counter_attack(skill_text),
            has_counter_battle_card_attack=any(str(k) == "Counter: Battle Card Attack" for k in merged_keywords),
            has_counter_play=bool(getattr(card, "has_counter_play", False)) or self._text_has_counter_play(skill_text),
            has_counter_counter=any(str(k) == "Counter: Counter" for k in merged_keywords) or self._text_has_counter_counter(skill_text),
            has_activate_main=bool(getattr(card, "has_activate_main", False)) or self._text_has_activate_main(skill_text),
            has_activate_battle=bool(getattr(card, "has_activate_battle", False)) or self._text_has_activate_battle(skill_text),
            has_auto=bool(getattr(card, "has_auto", False)) or self._text_has_auto(skill_text),
            has_permanent=bool(getattr(card, "has_permanent", False)) or self._text_has_permanent(skill_text),
            has_draw=has_draw_flag or self._text_has_draw(skill_text),
            max_draw=self._parse_optional_int(getattr(card, "max_draw", None)),
            auto_once_per_turn=self._has_once_per_turn(skill_text),
            auto_draw_on_play=self._has_auto_draw_on_play(skill_text, has_draw_flag or self._text_has_draw(skill_text)),
            auto_draw_on_attack=self._has_auto_draw_on_attack(skill_text, has_draw_flag or self._text_has_draw(skill_text)),
            has_barrier=bool(getattr(card, "has_barrier", False)) or self._text_has_barrier(skill_text),
            z_energy_cost=self._parse_optional_int(getattr(card, "z_energy_cost", None)),
            specified_costs=self._parse_specified_costs(getattr(card, "card_energy_cost", None), getattr(card, "card_color", None)),
            skill_text_raw=str(skill_text or "") if skill_text is not None else None,
            has_awaken=("[Awaken]" in str(skill_text or "")) if not is_back else False,
            activate_limit_once_per_turn=("[Limit 1]" in str(skill_text or "")) or self._has_once_per_turn(skill_text),
            has_super_combo=self._text_has_super_combo(skill_text),
            sparking_threshold=self._parse_sparking_threshold(skill_text),
            traits=self._parse_json_string_tuple(traits_raw),
            characters=self._parse_json_string_tuple(characters_raw),
        )

    @staticmethod
    def _parse_optional_int(value: object) -> int | None:
        if value is None:
            return None
        if isinstance(value, int):
            return value
        text = str(value).strip()
        return int(text) if text.isdigit() else None

    @staticmethod
    def _normalize_keyword_cost_text(text: str) -> str:
        normalized = str(text or "")
        circled = {
            "①": "1",
            "②": "2",
            "③": "3",
            "④": "4",
            "⑤": "5",
            "⑥": "6",
            "⑦": "7",
            "⑧": "8",
            "⑨": "9",
            "⑩": "10",
        }
        for src, dst in circled.items():
            normalized = normalized.replace(src, dst)
        return normalized.translate(str.maketrans("０１２３４５６７８９", "0123456789"))

    def _parse_realm_spec(self, card: CardInstance, *, keyword: str) -> dict[str, object] | None:
        raw = str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "")
        text = self._normalize_keyword_cost_text(raw)
        match = re.search(rf"\[{re.escape(keyword)}\s+(\d+)\](.*)", text, re.IGNORECASE)
        if match is None:
            return None
        drop_to_warp = int(match.group(1))
        suffix = str(match.group(2) or "")
        total_cost = 0
        specified_costs: dict[str, int] = {}
        dark_over_realm_symbol_map = {
            "r": "R",
            "u": "B",
            "g": "G",
            "y": "Y",
            "b": "K",
            "k": "K",
            "w": "W",
        }
        pos = 0
        while pos < len(suffix):
            while pos < len(suffix) and (suffix[pos].isspace() or suffix[pos] in {"/", ","}):
                pos += 1
            if pos >= len(suffix):
                break
            token = ""
            token_kind = ""
            if suffix[pos] == "(":
                end = suffix.find(")", pos + 1)
                if end < 0:
                    break
                token = suffix[pos + 1 : end]
                token_kind = "paren"
                pos = end + 1
            elif suffix[pos] == "{":
                end = suffix.find("}", pos + 1)
                if end < 0:
                    break
                token = suffix[pos + 1 : end]
                token_kind = "brace"
                pos = end + 1
            elif suffix[pos].isdigit():
                end = pos
                while end < len(suffix) and suffix[end].isdigit():
                    end += 1
                token = suffix[pos:end]
                token_kind = "digit"
                pos = end
            else:
                break
            if token_kind == "brace" and str(keyword).strip().lower() == "dark over realm":
                parsed_symbol = False
                for ch in str(token).strip().lower():
                    color = dark_over_realm_symbol_map.get(ch)
                    if color is None:
                        parsed_symbol = False
                        break
                    specified_costs[color] = specified_costs.get(color, 0) + 1
                    parsed_symbol = True
                if parsed_symbol:
                    continue
            amount, colors = self._parse_cost_token_value(token)
            total_cost += amount
            for color, count in colors.items():
                specified_costs[color] = specified_costs.get(color, 0) + count
        return {"drop_to_warp": drop_to_warp, "total_cost": total_cost, "specified_costs": specified_costs}

    def _parse_dark_over_realm_spec(self, card: CardInstance) -> dict[str, object] | None:
        return self._parse_realm_spec(card, keyword="Dark Over Realm")

    def _parse_over_realm_spec(self, card: CardInstance) -> dict[str, object] | None:
        return self._parse_realm_spec(card, keyword="Over Realm")

    def _parse_aegis_spec(self, card: CardInstance) -> dict[str, object] | None:
        raw = str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "")
        text = self._normalize_keyword_cost_text(raw)
        line = next((part.strip() for part in text.splitlines() if "[aegis" in part.lower()), "")
        if not line:
            return None
        match = re.search(r"\[Aegis\s+([^\]]+)\](.*)", line, re.IGNORECASE)
        if match is None:
            return None
        required_colors = {
            part.strip().lower()
            for part in str(match.group(1) or "").replace("/", ",").replace("|", ",").split(",")
            if part.strip()
        }
        suffix = str(match.group(2) or "")
        max_energy_to_activate = 2
        energy_match = re.search(
            r"choose up to (\d+) of your energy and switch (?:them|it) to active mode",
            suffix,
            re.IGNORECASE,
        )
        if energy_match is not None:
            try:
                max_energy_to_activate = int(energy_match.group(1))
            except ValueError:
                max_energy_to_activate = 2
        return {
            "required_colors": required_colors,
            "once_per_turn": "[once per turn]" in suffix.lower(),
            "max_energy_to_activate": max_energy_to_activate,
        }

    def _parse_arrival_spec(self, card: CardInstance) -> dict[str, object] | None:
        raw = str(card.skill_text_raw or self._resolve_card_runtime_data(card.card_id).skill_text_raw or "")
        text = self._normalize_keyword_cost_text(raw)
        match = re.search(r"\[Arrival\s+([^\]]+)\](.*)", text, re.IGNORECASE)
        if match is None:
            return None
        required_colors = {
            part.strip().lower()
            for part in str(match.group(1) or "").replace("/", ",").replace("|", ",").split(",")
            if part.strip()
        }
        suffix = str(match.group(2) or "")
        total_cost = 0
        specified_costs: dict[str, int] = {}
        pos = 0
        while pos < len(suffix):
            while pos < len(suffix) and (suffix[pos].isspace() or suffix[pos] in {"/", ","}):
                pos += 1
            if pos >= len(suffix):
                break
            token_start = pos
            token = ""
            if suffix[pos] == "(":
                end = suffix.find(")", pos + 1)
                if end < 0:
                    break
                token = suffix[pos + 1 : end]
                pos = end + 1
            elif suffix[pos] == "{":
                end = suffix.find("}", pos + 1)
                if end < 0:
                    break
                token = suffix[pos + 1 : end]
                pos = end + 1
            elif suffix[pos].isdigit():
                end = pos
                while end < len(suffix) and suffix[end].isdigit():
                    end += 1
                token = suffix[pos:end]
                pos = end
            else:
                break
            amount, colors = self._parse_cost_token_value(token)
            if amount <= 0 and not colors:
                pos = token_start
                break
            total_cost += amount
            for color, count in colors.items():
                specified_costs[color] = specified_costs.get(color, 0) + count
        remainder = str(suffix[pos:] or "")
        requirement_text = ""
        clause_match = re.match(r"\s*,?\s*(if [^:\n]+)", remainder, re.IGNORECASE)
        if clause_match is not None:
            requirement_text = str(clause_match.group(1) or "").strip()
        header_draw_amount = 0
        draw_match = re.search(r"draw\s+(\d+)\s+card", remainder, re.IGNORECASE)
        if draw_match is not None:
            try:
                header_draw_amount = int(draw_match.group(1))
            except ValueError:
                header_draw_amount = 0
        requires_leader = ""
        leader_match = re.match(r"\s*(if your leader(?: card)? is [^:\n]+)", requirement_text, re.IGNORECASE)
        if leader_match is not None:
            requires_leader = str(leader_match.group(1) or "").strip()
        return {
            "required_colors": required_colors,
            "total_cost": total_cost,
            "specified_costs": specified_costs,
            "requirement_text": requirement_text,
            "header_draw_amount": header_draw_amount,
            "requires_leader": requires_leader,
        }

    def _matching_hand_indices_for_color_requirements(
        self,
        hand: list[CardInstance],
        required_colors: set[str],
    ) -> tuple[int, ...] | None:
        normalized_required = {part.strip().lower() for part in required_colors if part.strip()}
        if not normalized_required:
            return ()
        indexed_color_sets: list[tuple[int, set[str]]] = []
        for idx, card in enumerate(hand):
            colors = {
                part.strip().lower()
                for part in str(card.color or self._resolve_card_runtime_data(card.card_id).color or "").replace("/", ",").split(",")
                if part.strip()
            }
            if colors:
                indexed_color_sets.append((idx, colors))
        max_pick = min(len(indexed_color_sets), len(normalized_required))
        for size in range(1, max_pick + 1):
            for combo in combinations(indexed_color_sets, size):
                covered: set[str] = set()
                indexes: list[int] = []
                for idx, colors in combo:
                    covered.update(colors)
                    indexes.append(idx)
                if normalized_required.issubset(covered):
                    return tuple(indexes)
        return None

    @staticmethod
    def _combo_area_color_tokens(player: PlayerState) -> set[str]:
        colors: set[str] = set()
        for card in player.combo_area:
            for part in str(card.color or "").replace("/", ",").replace("|", ",").split(","):
                normalized = str(part).strip().lower()
                if normalized:
                    colors.add(normalized)
        return colors

    @staticmethod
    def _parse_json_string_tuple(value: object) -> tuple[str, ...]:
        if value in (None, ""):
            return ()
        if isinstance(value, (list, tuple)):
            return tuple(str(item) for item in value if str(item).strip())
        try:
            parsed = json.loads(str(value))
        except Exception:
            return ()
        if isinstance(parsed, list):
            return tuple(str(item) for item in parsed if str(item).strip())
        return ()

    @staticmethod
    def _text_has_activate_main(skill_text: object) -> bool:
        text = str(skill_text or "").lower()
        return "[activate: main]" in text or "[activate main]" in text

    @staticmethod
    def _text_has_activate_battle(skill_text: object) -> bool:
        return "[activate: battle]" in str(skill_text or "").lower()

    @staticmethod
    def _parse_hidden_mode_awaken_threshold(skill_text: object) -> int | None:
        text = str(skill_text or "").lower()
        match = re.search(r"you have (\d+) or more hidden mode cards? in your battle area", text)
        if match is None:
            return None
        try:
            return int(match.group(1))
        except ValueError:
            return None

    @staticmethod
    def _parse_wish_spec(skill_text: object) -> dict[str, object] | None:
        text = str(skill_text or "")
        match = re.search(r"\[Wish\]\s*([^:]+):\s*(.+)", text, re.IGNORECASE | re.DOTALL)
        if match is None:
            return None
        condition_text = match.group(1).strip().lower()
        effect_text = match.group(2).strip().lower()
        condition_mode_text = re.sub(r"\bor (?:more|less)\b", "", condition_text)
        life_match = re.search(r"life is at (\d+) or less", condition_text)
        dragon_ball_match = re.search(r"(\d+)\s*\[dragon ball\]\s*cards?\s+in\s+your\s+drop\s+area", condition_text)
        return {
            "condition_mode": "or" if " or " in condition_mode_text else "and",
            "life_at_most": int(life_match.group(1)) if life_match else -1,
            "drop_dragon_ball_count": int(dragon_ball_match.group(1)) if dragon_ball_match else -1,
            "draw_count": 1 if "draw 1 card" in effect_text else 0,
            "add_desire_from_drop_to_hand": "desire" in effect_text and "add" in effect_text and "drop area" in effect_text,
            "recycle_drop_dragon_balls": "place all [dragon ball] cards from your drop area at the bottom of your deck" in effect_text,
        }

    @staticmethod
    def _parse_awaken_spec(skill_text: object) -> dict[str, object] | None:
        text = str(skill_text or "")
        match = re.search(r"\[Awaken\]\s*([^:]+):\s*(.+)", text, re.IGNORECASE | re.DOTALL)
        if match is None:
            return None
        condition_text = match.group(1).strip().lower()
        effect_text = match.group(2).strip().lower()
        condition_mode_text = re.sub(r"\bor (?:more|less)\b", "", condition_text)
        life_match = re.search(r"life is at (\d+) or less", condition_text)
        in_play_match = re.search(r"if you have a \{([^}]+)\} in play", condition_text, re.IGNORECASE)
        energy_match = re.search(r"you have (\d+) or more energy", condition_text, re.IGNORECASE)
        token_count_match = re.search(r"you have (\d+) or more ([a-z0-9' .:-]+?tokens?)", condition_text, re.IGNORECASE)
        unison_match = re.search(
            r"you have a ([a-z/]+) unison card with a specified cost of (\d+) in play",
            condition_text,
            re.IGNORECASE,
        )
        battle_area_card_match = re.search(
            r"(?:you have|and)\s+a ([a-z/]+) (z-extra|z-battle|z-unison|extra|battle|unison) with an energy cost of (\d+) in your battle area",
            condition_text,
            re.IGNORECASE,
        )
        draw_match = re.search(r"draw (\d+) card", effect_text)
        switch_energy_match = re.search(r"switch up to (\d+) of your energy to active mode", effect_text)
        life_target_match = re.search(r"until you have (\d+) life left", effect_text)
        token_match = re.search(
            r"play (?:up to )?(\d+) ([^(\n]+?tokens?)(?: into your battle area| to your battle area)?",
            effect_text,
            re.IGNORECASE,
        )
        token_stats_match = re.search(
            r"\([^)]*?(\d+)\s+power,\s*(\d+)\s+combo cost,\s*(?:and\s*)?(\d+)\s+combo power[^)]*\)",
            text,
            re.IGNORECASE,
        )
        token_name = str(token_match.group(2) or "").strip().lower() if token_match else ""
        if token_name.endswith("tokens"):
            token_name = token_name[:-1]
        required_owner_token_name = str(token_count_match.group(2) or "").strip().lower() if token_count_match else ""
        if required_owner_token_name.endswith("tokens"):
            required_owner_token_name = required_owner_token_name[:-1]
        battle_area_card_type = ""
        if battle_area_card_match:
            type_token = str(battle_area_card_match.group(2) or "").strip().upper().replace("-", "")
            battle_area_card_type = {
                "ZEXTRA": "Z-EXTRA",
                "ZBATTLE": "Z-BATTLE",
                "ZUNISON": "Z-UNISON",
                "EXTRA": "EXTRA",
                "BATTLE": "BATTLE",
                "UNISON": "UNISON",
            }.get(type_token, "")
        return {
            "condition_mode": "or" if " or " in condition_mode_text else "and",
            "life_at_most": int(life_match.group(1)) if life_match else -1,
            "owner_energy_at_least": int(energy_match.group(1)) if energy_match else -1,
            "required_owner_battle_name_in_play": in_play_match.group(1).strip().upper() if in_play_match else "",
            "required_owner_token_count": int(token_count_match.group(1)) if token_count_match else -1,
            "required_owner_token_name": required_owner_token_name,
            "required_owner_unison_color": str(unison_match.group(1) or "").strip().lower() if unison_match else "",
            "required_owner_unison_specified_cost": int(unison_match.group(2)) if unison_match else -1,
            "required_owner_battle_area_card_type": battle_area_card_type,
            "required_owner_battle_area_color": str(battle_area_card_match.group(1) or "").strip().lower()
            if battle_area_card_match
            else "",
            "required_owner_battle_area_energy_cost": int(battle_area_card_match.group(3)) if battle_area_card_match else -1,
            "draw_count": int(draw_match.group(1)) if draw_match else 0,
            "switch_owner_energy_active_count": int(switch_energy_match.group(1)) if switch_energy_match else 0,
            "life_to_hand_until": int(life_target_match.group(1)) if life_target_match else 6,
            "play_token_amount": int(token_match.group(1)) if token_match else 0,
            "play_token_name": token_name,
            "play_token_power": int(token_stats_match.group(1)) if token_stats_match else 0,
            "play_token_combo_cost": int(token_stats_match.group(2)) if token_stats_match else 0,
            "play_token_combo_power": int(token_stats_match.group(3)) if token_stats_match else 0,
        }

    @staticmethod
    def _parse_z_awaken_spec(skill_text: object) -> dict[str, object] | None:
        text = str(skill_text or "")
        match = re.search(r"\[Z-Awaken\](.*)", text, re.IGNORECASE | re.DOTALL)
        if match is None:
            return None
        line = str(match.group(1) or "").replace("<br>", "\n").splitlines()[0].strip()
        if not line:
            return None
        if ":" in line:
            header, target_text = line.split(":", 1)
        else:
            prefix_parts = []
            remainder = line
            while remainder.startswith("["):
                closing = remainder.find("]")
                if closing < 0:
                    break
                prefix_parts.append(remainder[: closing + 1])
                remainder = remainder[closing + 1 :].lstrip()
            if prefix_parts and remainder:
                header = " ".join(prefix_parts)
                target_text = remainder
            else:
                header, target_text = line, ""
        header = header.strip()
        target_text = target_text.strip().rstrip(".")
        specified_costs: dict[str, int] = {}
        for token in re.findall(r"\(([^)]+)\)|\{([^}]+)\}", header):
            raw = next((part for part in token if part), "").strip()
            amount, colors = RulesEngine._parse_cost_token_value(raw)
            if amount <= 0 and not colors:
                continue
            for color, count in colors.items():
                specified_costs[color] = specified_costs.get(color, 0) + int(count)
        cost_total = sum(specified_costs.values())
        lower_header = header.lower()
        life_match = re.search(r"life is at (\d+) or less", lower_header)
        combo_match = re.search(r"you have (\d+) or more cards? in your combo area", lower_header)
        all_energy_resting = "all of your energy is in rest mode" in lower_header
        skip_next_charge_phase = "skip your charge phase during your next turn" in lower_header
        spirit_boost_match = re.search(r"\[Spirit Boost\s+(\d+)\]", header, re.IGNORECASE)
        drop_character_match = re.search(r"there (?:are|is) (\d+) or more <([^>]+)> cards? in your drop(?: area)?", header, re.IGNORECASE)
        drop_trait_match = re.search(r"there (?:are|is) (\d+) or more [≪<]([^>≫]+)[≫>] cards? in your drop(?: area)?", header, re.IGNORECASE)
        z_energy_warp_required_characters = tuple(
            (character.strip(), int(amount))
            for amount, character in re.findall(r"(\d+)\s+<([^>]+)>\s+card", header, re.IGNORECASE)
            if character.strip()
        ) if "from your z-energy to your warp" in lower_header else ()
        name_match = re.search(r"\{([^}]+)\}", target_text)
        character_matches = [part.strip() for part in re.findall(r"<([^>]+)>", target_text) if part.strip()]
        require_all_characters = "both" in target_text.lower()
        if len(character_matches) > 1 and " or " not in target_text.lower() and "and/or" not in target_text.lower():
            require_all_characters = True
        color = next(
            (
                color
                for color in ("red", "blue", "green", "yellow", "black")
                if re.search(rf"\b(?:mono-)?{color}\b", target_text.lower())
            ),
            "",
        )
        return {
            "specified_costs": specified_costs,
            "total_cost": cost_total,
            "life_at_most": int(life_match.group(1)) if life_match else -1,
            "all_energy_resting": all_energy_resting,
            "skip_next_charge_phase": skip_next_charge_phase,
            "spirit_boost_cost": int(spirit_boost_match.group(1)) if spirit_boost_match else 0,
            "min_combo_area_count": int(combo_match.group(1)) if combo_match else -1,
            "min_owner_drop_matching": int((drop_character_match or drop_trait_match).group(1)) if (drop_character_match or drop_trait_match) else -1,
            "required_owner_drop_characters": tuple([drop_character_match.group(2).strip()]) if drop_character_match else (),
            "required_owner_drop_traits": tuple([drop_trait_match.group(2).strip()]) if drop_trait_match and not drop_character_match else (),
            "z_energy_warp_required_characters": z_energy_warp_required_characters,
            "required_name_contains": str(name_match.group(1)).strip().upper() if name_match else "",
            "required_characters": tuple(character_matches),
            "require_all_characters": require_all_characters,
            "required_color": color,
            "require_mono_color": "mono-" in target_text.lower(),
        }

    @staticmethod
    def _parse_z_stack_spec(skill_text: object) -> dict[str, object] | None:
        text = str(skill_text or "")
        match = re.search(r"\[Z-Stack\s+(\d+)\](.*)", text, re.IGNORECASE | re.DOTALL)
        if match is None:
            return None
        count = int(match.group(1))
        line = str(match.group(2) or "").replace("<br>", "\n").splitlines()[0].strip()
        if not line:
            return None
        descriptor = re.split(r"\s+\(", line, maxsplit=1)[0].strip().rstrip(".")
        lower_descriptor = descriptor.lower()
        allowed_colors = tuple(
            color
            for color in ("red", "blue", "green", "yellow", "black")
            if re.search(rf"\b(?:mono-)?{color}\b", lower_descriptor)
        )
        required_traits = tuple(part.strip() for part in re.findall(r"≪([^≫]+)≫", descriptor) if part.strip())
        required_card_type = "BATTLE" if "battle card" in lower_descriptor else ""
        max_energy_cost_match = re.search(r"energy cost of (\d+) or less", lower_descriptor)
        return {
            "count": count,
            "allowed_colors": allowed_colors,
            "required_traits": required_traits,
            "required_card_type": required_card_type,
            "max_energy_cost": int(max_energy_cost_match.group(1)) if max_energy_cost_match else -1,
            "require_different_character_names": "different character names" in lower_descriptor,
        }

    @staticmethod
    def _text_has_auto(skill_text: object) -> bool:
        return "[auto]" in str(skill_text or "").lower()

    @staticmethod
    def _text_has_permanent(skill_text: object) -> bool:
        return "[permanent]" in str(skill_text or "").lower()

    @staticmethod
    def _text_has_draw(skill_text: object) -> bool:
        return "draw" in str(skill_text or "").lower()

    @staticmethod
    def _text_has_barrier(skill_text: object) -> bool:
        return "[barrier]" in str(skill_text or "").lower()

    @staticmethod
    def _text_counter_modes(skill_text: object) -> tuple[str, ...]:
        lowered = str(skill_text or "").lower()
        modes: list[str] = []
        if "[counter: attack]" in lowered:
            modes.append("Counter: Attack")
        if "[counter: play]" in lowered:
            modes.append("Counter: Play")
        if "[counter: counter]" in lowered:
            modes.append("Counter: Counter")
        if "[counter: battle card attack]" in lowered:
            modes.append("Counter: Battle Card Attack")
        return tuple(modes)

    @classmethod
    def _text_has_counter(cls, skill_text: object) -> bool:
        return bool(cls._text_counter_modes(skill_text))

    @classmethod
    def _text_has_counter_attack(cls, skill_text: object) -> bool:
        return "Counter: Attack" in cls._text_counter_modes(skill_text)

    @classmethod
    def _text_has_counter_play(cls, skill_text: object) -> bool:
        return "Counter: Play" in cls._text_counter_modes(skill_text)

    @classmethod
    def _text_has_counter_counter(cls, skill_text: object) -> bool:
        return "Counter: Counter" in cls._text_counter_modes(skill_text)

    @staticmethod
    def _text_has_super_combo(skill_text: object) -> bool:
        return "[super combo]" in str(skill_text or "").lower()

    @staticmethod
    def _parse_sparking_threshold(skill_text: object) -> int | None:
        import re

        text = str(skill_text or "")
        match = re.search(r"\[sparking\s+(\d+)\]", text, flags=re.IGNORECASE)
        if not match:
            return None
        try:
            return int(match.group(1))
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _parse_specified_costs(raw_cost: object, fallback_color: object) -> tuple[tuple[str, int], ...]:
        if raw_cost is None:
            raw = ""
        else:
            raw = str(raw_cost).strip()
        if raw == "":
            return ()

        txt = raw.upper()
        for word, code in {
            "RED": "R",
            "BLUE": "B",
            "GREEN": "G",
            "YELLOW": "Y",
            "BLACK": "K",
        }.items():
            txt = txt.replace(word, code)

        counts: dict[str, int] = {}
        for ch in txt:
            if ch in {"R", "B", "G", "Y", "K"}:
                counts[ch] = counts.get(ch, 0) + 1

        if not counts and any(c.isdigit() for c in txt):
            return ()

        if not counts and fallback_color:
            code = RulesEngine._color_to_code(str(fallback_color))
            if code:
                counts[code] = 1
        return tuple(sorted(counts.items()))

    @staticmethod
    def _has_auto_draw_on_play(skill_text: object, has_draw_flag: bool) -> bool:
        if not has_draw_flag:
            return False
        text = str(skill_text or "").lower()
        return ("when this card is played" in text) or ("when you play this card" in text)

    @staticmethod
    def _has_once_per_turn(skill_text: object) -> bool:
        text = str(skill_text or "").lower()
        return "[once per turn]" in text or "once per turn" in text

    @staticmethod
    def _has_auto_draw_on_attack(skill_text: object, has_draw_flag: bool) -> bool:
        if not has_draw_flag:
            return False
        text = str(skill_text or "").lower()
        return "when this card attacks" in text

    @staticmethod
    def _color_to_code(color: str | None) -> str | None:
        if color is None:
            return None
        c = color.strip().lower()
        mapping = {"red": "R", "blue": "B", "green": "G", "yellow": "Y", "black": "K", "white": "W"}
        return mapping.get(c)

    @staticmethod
    def _opponent_of(player_id: int) -> int:
        if player_id == 1:
            return 2
        if player_id == 2:
            return 1
        raise ValueError(f"Unknown player_id: {player_id}")

